NAME = 'DaOT1871NT1907: Danish OT1871 + NT1907 with original orthography'
BOOK = 'Genesis'

CHAPTERS = {
    1: {
        1: 'I Begyndelsen skabte Gud Himmelen og Jorden.',
        2: 'Og Jorden var øde og tom, og der var Mørke oven over Afgrunden, og Guds Aand svævede oven over Vandene.',
        3: 'Og Gud sagde: Der vorde Lys; og der blev Lys.',
        4: 'Og Gud saa, at Lyset var godt, og Gud gjorde Skilsmisse imellem Lyset og Mørket.',
        5: 'Og Gud kaldte Lyset Dag, og Mørket kaldte han Nat; og der blev Aften, og der blev Morgen, første Dag.',
        6: 'Og Gud sagde: Der vorde en udstrakt Befæstning midt i Vandene, og den skal skille imellem Vand og Vand.',
        7: 'Og Gud gjorde den udstrakte Befæstning og gjorde Skilsmisse imellem Vandet, som var nedentil i den udstrakte Befæstning, og imellem Vandet, som var oventil i den udstrakte Befæstning; og det skete saa.',
        8: 'Og Gud kaldte den udstrakte Befæstning Himmel; og der blev Aften, og der blev Morgen, anden Dag.',
        9: 'Og Gud sagde: Vandene under Himlene samle sig til eet Sted, at det tørre ses; og det skete saa.',
        10: 'Og Gud kaldte det tørre Jord, og Vandenes Samling kaldte han Hav; og Gud saa, at det var godt.',
        11: 'Og Gud sagde: Jorden lade fremvokse Græs, Urter, som give Sæd, frugtbare Træer, som bære Frugt efter sit Slags og have sin Sæd i sig paa Jorden; og det skete saa.',
        12: 'Og Jorden frembragte Græs, Urter, som gave Sæd efter sit Slags, og Træer, som bare Frugt og havde sin Sæd i sig efter sit Slags; og Gud saa, at det var godt.',
        13: 'Og der blev Aften, og der blev Morgen, tredje Dag.',
        14: 'Og Gud sagde: Der vorde Lys paa Himmelens udstrakte Befæstning, at gøre Skilsmisse imellem Dagen og imellem Natten; og de skulle være til Tegn og til bestemte Tider og til Dage og Aar.',
        15: 'Og de skulle være til Lys paa Himmelens udstrakte Befæstning til at lyse over Jorden; og det skete saa.',
        16: 'Og Gud gjorde de to store Lys, det store Lys at regere Dagen og det lille Lys at regere Natten og Stjernerne.',
        17: 'Og Gud satte dem paa Himmelens udstrakte Befæstning til at lyse over Jorden',
        18: 'og til at regere om Dagen og om Natten og til at skille imellem Lyset og imellem Mørket; og Gud saa, at det var godt.',
        19: 'Og der blev Aften, og der blev Morgen, fjerde Dag.',
        20: 'Og Gud sagde: Vandet vrimle med en Vrimmel af levende Væsener, og Fugle skulle flyve over Jorden imod Himmelens udstrakte Befæstning.',
        21: 'Og Gud skabte de store Havdyr og alle Haande levende Væsener, som krybe, hvilke vrimle i Havet, efter sit Slags og alle Haande Fugle med Vinger efter sit Slags; og Gud saa, at det var godt.',
        22: 'Og Gud velsignede dem og sagde: Vorder frugtbare og mangfoldige, og fylder Vandene i Havet, og Fuglene vorde mangfoldige paa Jorden.',
        23: 'Og der blev Aften, og der blev Morgen, femte Dag.',
        24: 'Og Gud sagde: Jorden frembringe levende Dyr efter sit Slags, Fæ og Kryb og vilde Dyr paa Jorden efter sit Slags; og det skete saa.',
        25: 'Og Gud gjorde vilde Dyr paa Jorden efter sit Slags og Fæ efter sit Slags og alle Haande Kryb paa Jorden efter sit Slags; og Gud saa, at det var godt.',
        26: 'Og Gud sagde: Lader os gøre et Menneske i vort Billede, efter vor Lignelse; og de skulle regere over Havets Fiske og over Himmelens Fugle og over Fæet og over al Jorden og over alt Kryb, som kryber paa Jorden.',
        27: 'Og Gud skabte Mennesket i sit Billede, han skabte det i Guds Billede; Mand og Kvinde skabte han dem.',
        28: 'Og Gud velsignede dem, og Gud sagde til dem: Vorder frugtbare og mangfoldige, og opfylder Jorden, og gører eder den underdanig, og regerer over Havets Fiske og over Himmelens Fugle og over hvert Dyr, som kryber paa Jorden.',
        29: 'Og Gud sagde: Se, jeg har givet eder alle Urter, som give Sæd, som ere over al Jorden, og alle Haande Træer, i hvilke er Træers Frugt, som have Sæd; de skulle være eder til Føde.',
        30: 'Og alle Dyr paa Jorden og alle Fugle under Himmelen og alt Kryb paa Jorden, i hvilke er en levende Sjæl, har jeg givet alle Haande grønne Urter til at æde; og det skete saa.',
        31: 'Og Gud saa alt det, han havde gjort, og se, det var meget godt; og der blev Aften, og der blev Morgen, den sjette Dag.',
    },
    2: {
        1: 'Og Himmelen og Jorden bleve fuldkommede, og al deres Hær.',
        2: 'Og Gud havde fuldkommet paa den syvende Dag sin Gerning, som han havde gjort, og hvilede paa den syvende Dag fra al sin Gerning, som han havde gjort.',
        3: 'Og Gud velsignede den syrende Dag og helligede den; thi paa den hvilede han fra al sin Gerning, som Gud skabte og gjorde.',
        4: 'Disse ere Himmelens og Jordens Oprindelser, der de skabtes, paa den Dag Gud Herren gjorde Jorden og Himmelen.',
        5: 'Og alle Haande Buske paa Marken vare endnu ikke paa Jorden, og alle Haande Urter paa Marken vare endnu ikke fremspirede; thi Gud Herren havde ikke ladet regne paa Jorden, og der var intet Menneske til at dyrke Jorden.',
        6: 'Og der opgik en Damp af Jorden og vandede al Jordens Overflade.',
        7: 'Og Gud Herren dannede Mennesket af Støv af Jorden og blæste Livets Aande i hans Næse; og Mennesket blev til en levende Sjæl.',
        8: 'Og Gud Herren plantede en Have udi Eden mod Østen og satte der Mennesket, hvilket han havde gjort.',
        9: 'Og Gud Herren lod opvokse alle Haande Træer af Jorden, som vare lystelige at se til og gode til at æde af, og Livsens Træ midt i Haven og Kundskabens Træ paa godt og ondt.',
        10: 'Og der gik en Flod ud fra Eden til at vande Haven, og derfra deltes den og blev til fire Hovedstrømme.',
        11: 'Den førstes Navn er Pison, hvilken løber om det ganske Land Havila, hvor der er Guld.',
        12: 'Og Guldet fra det samme Land er godt; der er Bdellion og den Sten Onyks.',
        13: 'Og den anden Flods Navn er Gihon, hvilken løber om det ganske Land Kus.',
        14: 'Og den tredje Flods Navn er Hiddekel, hvilken gaar Østen for Assyrien; og den fjerde Flod, den er Frat.',
        15: 'Og Gud Herren tog Mennesket og satte det i Edens Have at dyrke den og vogte den.',
        16: 'Og Gud Herren bød Mennesket og sagde: Du maa frit æde af alle Træer i Haven;',
        17: 'men af Kundskabens Træ paa godt og ondt, af det skal du ikke æde; thi paa hvilken Dag du æder af det, skal du dø Døden.',
        18: 'Og Gud Herren sagde: Det er ikke godt, at Mennesket er ene, jeg vil gøre ham en Medhjælp, som skal være hos ham.',
        19: 'Og Gud Herren havde gjort af Jorden alle vilde Dyr paa Marken og alle Himmelens Fugle og ledte dem til Mennesket for at se, hvad han vilde kalde hvert; og alt det, som Adam kaldte hver levende Sjæl, det var dens Navn.',
        20: 'Saa gav Adam alt Kvæget og Himmelens Fugle og alle vilde Dyr paa Marken Navne; men for Mennesket fandt han ingen Medhjælp, som kunde være hos ham.',
        21: 'Da lod Gud Herren falde en dyb Søvn paa Adam, og han sov; og han tog et af hans Ribben og lukkede med Kød i Stedet derfor.',
        22: 'Og Gud Herren byggede af det Ribben, som han havde taget af Mennesket, en Mandinde og ledte hende til Adam.',
        23: 'Da sagde Adam: Denne Gang er det Ben af mine Ben og Kød af mit Kød; denne skal kaldes Mandinde, thi denne er tagen af Manden.',
        24: 'Derfor skal Manden forlade sin Fader og sin Moder og blive fast hos sin Hustru, og de skulle være til eet Kød.',
        25: 'Og de vare begge nøgne, Adam og hans Hustru, og de bluedes ikke.',
    },
    3: {
        1: 'Og Slangen var træskere end alle vilde Dyr paa Marken, hvilke Gud Herren havde gjort; og den sagde til Kvinden: Mon Gud skulde have sagt: I maa ikke æde af hvert Træ i Haven?',
        2: 'Da sagde Kvinden til Slangen: Vi maa æde af Havens Træers Frugt;',
        3: 'men om det Træs Frugt, som er midt i Haven, sagde Gud: Æder ikke deraf og rører ikke derved, at I ikke skulle dø.',
        4: 'Da sagde Slangen til Kvinden: I skulle ikke dø Døden;',
        5: 'men Gud ved, at hvilken Dag I æde deraf, da skulle eders Øjne oplades, og I skulle blive ligesom Gud og kende godt og ondt.',
        6: 'Og Kvinden saa, at Træet var godt at æde af, og at det var lysteligt at se til og et ønskeligt Træ til at faa Forstand af, og hun tog af dets Frugt og aad; og hun gav ogsaa sin Mand med sig, og han aad.',
        7: 'Da oplodes begges Øjne, og de kendte, at de vare nøgne, og de hæftede Figenblade sammen og gjorde sig Bælter.',
        8: 'Og de hørte Gud Herrens Røst, som gik i Haven, der Dagen blev sval; da skjulte Adam og hans Hustru sig for Gud Herrens Ansigt iblandt Træerne i Haven.',
        9: 'Og Gud Herren kaldte ad Adam og sagde til ham: Hvor er du?',
        10: 'Og han sagde: Jeg hørte din Røst i Haven og frygtede; thi jeg var nøgen, og jeg skjulte mig.',
        11: 'Og han sagde: Hvo gav dig til Kende, at du var nøgen? har du ædet af det Træ, om hvilket jeg bød dig, at du skulde ikke æde deraf?',
        12: 'Og Adam sagde: Kvinden, som du gav til at være hos mig, hun gav mig af Træet, og jeg aad.',
        13: 'Da sagde Gud Herren til Kvinden: Hvi har du gjort dette? Og Kvinden sagde: Slangen forførte mig, og jeg aad.',
        14: 'Da sagde Gud Herren til Slangen: Efterdi du gjorde dette, da vær forbandet fremfor alt Kvæget og fremfor alle vilde Dyr paa Marken; du skal gaa paa din Bug og æde Støv alle dit Livs Dage.',
        15: 'Og jeg vil sætte Fjendskab imellem dig og imellem Kvinden og imellem din Sæd og imellem hendes Sæd; den skal sønderknuse dit Hoved, men du skal sønderknuse hans Hæl.',
        16: 'Til Kvinden sagde han: Jeg vil meget mangfoldiggøre din Kummer og din Undfangelse, med Smerte skal du føde Børn; og din Attraa skal være til din Mand, men han skal herske over dig.',
        17: 'Og til Adam sagde han: Efterdi du lød din Hustrus Røst og aad af det Træ, om hvilket jeg bød dig og sagde: Du skal ikke æde deraf, da være Jorden forbandet for din Skyld, med Kummer skal du æde deraf alle dit Livs Dage.',
        18: 'Og den skal bære dig Torn og Tidsel, og du skal æde Urter paa Marken.',
        19: 'I dit Ansigts Sved skal du æde dit Brød, indtil du bliver til Jord igen, thi deraf er du tagen; thi du er Støv, og du skal blive til Støv igen.',
        20: 'Og Adam kaldte sin Hustrus Navn Eva, thi hun er bleven alle levendes Moder.',
        21: 'Og Gud Herren gjorde Adam og hans Hustru Kjortler af Skind og iførte dem.',
        22: 'Og Gud Herren sagde: Se, Adam er bleven som en af os til at kende godt og ondt; men nu, paa det han ikke skal udrække sin Haand og tage ogsaa af Livsens Træ og æde og leve evindeligen:',
        23: 'da forviste Gud Herren ham af Edens Have til at dyrke Jorden, som han var tagen af.',
        24: 'Og han drev Mennesket ud og satte Keruber Østen for Edens Have med et blinkende Sværd, som vendte sig hid og did, til at vogte Vejen til Livsens Træ.',
    },
    4: {
        1: 'Og Adam kendte sin Hustru Eva; og hun undfik og fødte Kain og sagde: Jeg har faaet en Mand, som er Herren.',
        2: 'Og hun blev ved at føde, nemlig hans Broder Abel; og Abel blev en Faarehyrde, og Kain dyrkede Jorden.',
        3: 'Og det hændte sig, der en Tid var forløben, og Kain frembar et Offer til Herren af Jordens Frugt.',
        4: 'Og Abel, ogsaa han bar frem af sin Hjords første Affødning og af deres Fedme; og Herren saa til Abel og til hans Offer.',
        5: 'Men til Kain og til hans Offer saa han ikke; da blev Kain meget vred, og hans Ansigt falmede.',
        6: 'Og Herren sagde til Kain: Hvi er du vred, og hvi er dit Ansigt falmet?',
        7: 'Er det ikke saa, at dersom du gør godt, da er du behagelig, og dersom du ikke gør godt, da ligger Synden for Døren, og til dig er dens Attraa? men du skal herske over den.',
        8: 'Og Kain talede med Abel sin Broder; og det hændte sig, der de vare paa Marken, da stod Kain op imod Abel sin Broder og ihjelslog ham.',
        9: 'Og Herren sagde til Kain: Hvor er Abel, din Broder? Og han sagde: Jeg ved ikke, mon jeg være min Broders Vogter?',
        10: 'Og han sagde: Hvad har du gjort? din Broders Blods Røst raaber til mig af Jorden.',
        11: 'Og nu være du forbandet fra Jorden, som oplod sin Mund til at tage din Broders Blod af din Haand.',
        12: 'Naar du dyrker Jorden, skal den ikke ydermere give dig sin Kraft; ustadig og flygtig skal du være paa Jorden.',
        13: 'Da sagde Kain til Herren: Min Misgerning er større, end jeg kan bære.',
        14: 'Se, du har i Dag drevet mig fra Jordens Kreds, og jeg maa skjule mig for dit Ansigt; og jeg bliver ustadig og flygtig paa Jorden, og det vil ske, hvo som finder mig, slaar mig ihjel.',
        15: 'Men Herren sagde til ham: Derfor, hvo som ihjelslaar Kain, paa ham skal det hævnes syvfold; saa satte Herren for Kain et Tegn, at ingen, som fandt ham, skulde slaa ham ihjel.',
        16: 'Saa gik Kain ud fra Herrens Ansigt og blev i det Land Nod Østen for Eden.',
        17: 'Og Kain kendte sin Hustru, og hun undfik og fødte Hanok; og han byggede en Stad og kaldte Stadens Navn efter sin Søns Navn, Hanok.',
        18: 'Og for Hanok blev født Irad, og Irad avlede Mehujael, og Mehujael avlede Mathusael, og Mathusael avlede Lamek.',
        19: 'Og Lamek tog sig to Hustruer, den enes Navn var Ada, og den andens Navn Zilla.',
        20: 'Og Ada fødte Jabal; han var Fader til dem, som boede i Telte og vogtede Kvæg.',
        21: 'Og hans Broders Navn var Jubal; han var Fader til alle dem, der legede paa Harpe og Fløjte.',
        22: 'Og Zilla, ogsaa hun fødte, nemlig Thubalkain, som kunstigen gjorde alle Haande skarpt Kobber- og Jerntøj; og Thubalkains Søster var Naama.',
        23: 'Og Lamek sagde til sine Hustruer: Ada og Zilla, hører min Røst, Lameks Hustruer, mærker min Tale! Om jeg har slagen en Mand ihjel, mig til et Saar, og en Dreng, mig til en Byld:',
        24: 'da skal Kain hævnes syvfold, og Lamek halvfjerdsindstyve Gange og syv Gange.',
        25: 'Og Adam kendte ydermere sin Hustru, og hun fødte en Søn og kaldte hans Navn Seth; thi Gud har sat mig, sagde hun, en anden Sæd i Abels Sted; thi Kain slog ham ihjel.',
        26: 'Og for Seth blev og født en Søn, og han kaldte hans Navn Enos; da begyndte man at paakalde Herrens Navn.',
    },
    5: {
        1: 'Denne er Menneskens Slægters Bog. Paa den Dag Gud skabte Mennesket, gjorde han det i Guds Lignelse.',
        2: 'Han skabte dem Mand og Kvinde og velsignede dem og kaldte deres Navn Menneske, paa den Dag de bleve skabte.',
        3: 'Og Adam levede hundrede og tredive Aar og avlede en Søn i sin Lignelse, efter sit Billede og kaldte hans Navn Seth.',
        4: 'Og Adam levede, efter at han havde avlet Seth, otte Hundrede Aar og avlede Sønner og Døtre.',
        5: 'Og Adams ganske Alder, som han levede, blev ni Hundrede Aar og tredive Aar; og han døde.',
        6: 'Og Seth var hundrede Aar og fem Aar gammel og avlede Enos.',
        7: 'Og Seth levede, efter at han havde avlet Enos, otte Hundrede Aar og syv Aar og avlede Sønner og Døtre.',
        8: 'Og Seths ganske Alder blev ni Hundrede Aar og tolv Aar; og han døde.',
        9: 'Og Enos var halvfemsindstyve Aar gammel og avlede Kenan.',
        10: 'Og Enos levede, efter at han havde avlet Kenan, otte Hundrede Aar og femten Aar og avlede Sønner og Døtre.',
        11: "Og Enos' ganske Alder blev ni Hundrede Aar og fem Aar; og han døde.",
        12: 'Og Kenan var halvfjerdsindstyve Aar gammel og avlede Mahalaleel.',
        13: 'Og Kenan levede, efter at han havde avlet Mahalaleel, otte Hundrede Aar og fyrretyve Aar og avlede Sønner og Døtre.',
        14: 'Og Kenans ganske Alder blev ni Hundrede Aar og ti Aar; og han døde.',
        15: 'Og Mahalaleel var fem Aar og tresindstyve Aar gammel og avlede Jared.',
        16: 'Og Mahalaleel levede, efter at han havde avlet Jared, otte Hundrede Aar og tredive Aar og avlede Sønner og Døtre.',
        17: 'Og Mahalaleels ganske Alder var otte Hundrede Aar og fem og halvfemsindstyve Aar; og han døde.',
        18: 'Og Jared var hundrede Aar og to og tresindstyve Aar gammel og avlede Enok.',
        19: 'Og Jared levede, efter at han havde avlet Enok, otte Hundrede Aar og avlede Sønner og Døtre.',
        20: 'Og Jareds ganske Alder blev ni Hundrede Aar og to og tresindstyve Aar; og han døde.',
        21: 'Og Enok var fem og tresindstyve Aar gammel og avlede Methusela.',
        22: 'Og Enok vandrede med Gud, efter at han havde avlet Methusela, tre Hundrede Aar og avlede Sønner og Døtre.',
        23: 'Og Enoks ganske Alder blev tre Hundrede Aar og fem og tresindstyve Aar.',
        24: 'Og Enok vandrede med Gud, og han var ikke mere; thi Gud tog ham.',
        25: 'Og Methusela var hundrede Aar og syv og firsindstyve Aar gammel og avlede Lamek.',
        26: 'Og Methusela levede, efter at han havde avlet Lamek, syv Hundrede Aar og to og firsindstyve Aar og avlede Sønner og Døtre.',
        27: 'Og Methuselas ganske Alder blev ni Hundrede Aar og ni og tresindstyve Aar; og han døde.',
        28: 'Og Lamek var hundrede Aar og to og firsindstyve Aar gammel og avlede en Søn;',
        29: 'og han kaldte hans Navn Noa og sagde: Denne skal trøste os i vor Kummer og vore Hænders Arbejde paa Jorden, hvilken Herren har forbandet.',
        30: 'Og Lamek levede, efter at han havde avlet Noa, fem Hundrede Aar og fem og halvfemsindstyve Aar og avlede Sønner og Døtre.',
        31: 'Og Lameks ganske Alder blev syv Hundrede Aar og syv og halvfjerdsindstyve Aar; og han døde.',
        32: 'Og Noa var fem Hundrede Aar gammel, og Noa avlede Sem, Kam og Jafet.',
    },
    6: {
        1: 'Og det skete, der Menneskene havde begyndt at formeres paa Jorden, og Døtre fødtes dem,',
        2: 'da saa Guds Sønner Menneskens Døtre, at de vare skønne, og toge sig Hustruer af alle, hvilke de valgte.',
        3: 'Da sagde Herren: Min Aand skal ikke herske i Mennesket evindelig, eftersom han er Kød; og hans Dage skulle være hundrede og tyve Aar.',
        4: 'Paa den Tid vare Kæmper paa Jorden, ja ogsaa efter at Guds Sønner vare indgangne til Menneskens Døtre og havde avlet sig Børn; disse ere de vældige, hvilke fra fordums Tid have været navnkundige Mænd.',
        5: 'Og Herren saa, at Menneskets Ondskab var stor paa Jorden, og at alt hans Hjertes Tankers Paafund var ikkun ondt hver Dag.',
        6: 'Da angrede Herren, at han havde gjort Mennesket paa Jorden, og det bedrøvede ham i hans Hjerte.',
        7: 'Og Herren sagde: Jeg vil udslette Mennesket, som jeg har skabt, af Jorden, baade Mennesker og Kvæg og Kryb og Fugle under Himmelen; thi jeg angrer, at jeg gjorde dem.',
        8: 'Men Noa fandt Naade for Herrens Øjne.',
        9: 'Disse ere Noas Slægter. Noa, en retfærdig Mand, var ustraffelig i sin Tid, Noa vandrede med Gud.',
        10: 'Og Noa avlede tre Sønner: Sem, Kam og Jafet.',
        11: 'Men Jorden var fordærvet for Guds Ansigt, og Jorden var fuld af Vold.',
        12: 'Da saa Gud Jorden, og se, den var fordærvet; thi alt Kød havde fordærvet sin Vej paa Jorden.',
        13: 'Da sagde Gud til Noa: Alt Køds Ende er kommen for mit Ansigt; thi Jorden er fuld af Vold af dem; og se, jeg vil fordærve dem med Jorden.',
        14: 'Gør dig en Ark af Gofertræ; gør Rum i Arken, og beg den inden og udentil med Beg.',
        15: 'Og denne er Maaden, efter hvilken du skal gøre den: Tre Hundrede Alen skal Arkens Længde være, halvtredsindstyve Alen dens Bredde og tredive Alen dens Højde.',
        16: 'Du skal gøre et Vindue paa Arken, og oventil skal du fuldkomme den til en Alen, og Arkens Dør skal du sætte paa dens Side; du skal gøre den med et nederste, et mellemste og et tredje Loft.',
        17: 'Og jeg, se, jeg lader komme en Vandflod over Jorden til at fordærve alt Kød, som har Livs Aande i sig under Himmelen; alt det, som er paa Jorden, skal udaande.',
        18: 'Men med dig opretter jeg min Pagt; og du skal gaa i Arken, du og dine Sønner og din Hustru og dine Sønners Hustruer med dig.',
        19: 'Og af alt det, som lever, af alt Kød, et Par af hver Slags skal du indføre i Arken, at lade leve med dig; Han og Hun skal det være.',
        20: 'Af Fuglene efter deres Slags og af Kvæget efter deres Slags, af alle Haande Kryb paa Jorden efter deres Slags; et Par af hvert skal gaa ind til dig, at de maa leve.',
        21: 'Og tag du dig af alle Haande Føde, som ædes, og samle til dig, at det maa blive dig og dem til Næring.',
        22: 'Og Noa gjorde det, efter alt det, som Gud havde befalet ham, saaledes gjorde han.',
    },
    7: {
        1: 'Og Herren sagde til Noa: Gak ind, du og dit ganske Hus, i Arken; thi dig har jeg set retfærdig for mig i denne Slægt.',
        2: 'Tag dig af alle Haande rent Kvæg syv og syv, Han og Hun; men af det Kvæg, som er urent, et Par, Han og Hun;',
        3: 'ogsaa af Fuglene under Himmelen, syv og syv, Han og Hun, at holde Sæd paa al Jorden i Live.',
        4: 'Thi end om syv Dage vil jeg lade regne paa Jorden fyrretyve Dage og fyrretyve Nætter og udslette af Jorden alle levende Væsener, som jeg har gjort.',
        5: 'Og Noa gjorde efter alt, hvad Herren bød ham.',
        6: 'Og der Noa var seks Hundrede Aar gammel, da kom Floden med Vande over Jorden.',
        7: 'Og Noa gik ind og hans Sønner og hans Hustru og hans Sønners Hustruer med ham i Arken for Flodens Vande.',
        8: 'Af rent Kvæg og af det Kvæg, som ikke er rent, og af Fuglene og alt det, som kryber paa Jorden,',
        9: 'gik Par og Par til Noa til Arken, Han og Hun, ligesom Gud havde befalet Noa.',
        10: 'Og det skete paa den syvende Dag, da kom Flodens Vande over Jorden.',
        11: 'I det Aar, der Noa var seks Hundrede Aar gammel, i den anden Maaned, paa den syttende Dag i Maaneden, paa den Dag opbrast alle Kilder i den store Afgrund, og Himmelens Sluser oplodes.',
        12: 'Og der var Regn paa Jorden fyrretyve Dage og fyrretyve Nætter.',
        13: 'Paa den selvsamme Dag gik Noa og Sem og Kam og Jafet, Noas Sønner, og Noas Hustru og hans Sønners tre Hustruer med dem i Arken;',
        14: 'de og alle Haande vilde Dyr efter deres Slags og alle Haande Kvæg efter deres Slags og alle Haande Kryb, som krybe paa Jorden, efter deres Slags, og alle Haande Fugle efter deres Slags, alt det, som kan flyve, alt det, som har Vinger.',
        15: 'Og de gik i Arken til Noa, Par og Par af alt Kød, i hvilket der var Livs Aande.',
        16: 'Og de, som kom, kom Han og Hun af alle Haande Kød, ligesom Gud havde budet ham; og Herren lukkede til efter ham.',
        17: 'Da kom Floden fyrretyve Dage over Jorden; og Vandet formeredes og opløftede Arken, og den hævedes op over Jorden.',
        18: 'Og Vandet fik Overhaand og formeredes saare over Jorden; og Arken flød oven paa Vandet.',
        19: 'Og Vandet fik Overhaand saare meget over Jorden; og alle høje Bjerge bleve skjulte, som vare under den ganske Himmel.',
        20: 'Femten Alen oventil fik Vandet Overhaand, og Bjergene bleve skjulte.',
        21: 'Saa udaandede alt Kød, som rørte sig paa Jorden, af Fugle og af Kvæg og af vilde Dyr og af al den Vrimmel, som vrimlede paa Jorden, og hvert Menneske.',
        22: 'Alt det, som havde Livs Aande i sin Næse, alt det, som var paa det tørre, døde.',
        23: 'Og hvert Væsen udslettedes, som var paa Jorden, fra Mennesket indtil Kvæg, indtil Kryb og indtil Fugle under Himmelen, og de bleve udslettede af Jorden; og Noa blev alene igen, og hvad der var med ham i Arken.',
        24: 'Og Vandet havde Overhaand over Jorden hundrede og halvtredsindstyve Dage.',
    },
    8: {
        1: 'Og Gud ihukom Noa og alle vilde Dyr og alt Kvæg, som var med ham i Arken, og Gud lod Vejr fare over Jorden, og Vandet faldt.',
        2: 'Og Kilderne i Afgrunden stoppedes, og Himmelens Sluser og Regnen fra Himmelen holdt op.',
        3: 'Og Vandet vendte tilbage af Jorden, gaaende frem og tilbage; og Vandet formindskedes, efter at hundrede og halvtredsindstyve Dage vare forløbne.',
        4: 'Og Arken hvilede i den syvende Maaned, paa deri syttende Dag i Maaneden, paa Ararats Bjerge.',
        5: 'Og Vandet for hid og did og formindskedes indtil den tiende Maaned; i den tiende Maaned, paa den første Dag i Maaneden, lode Toppene af Bjergene sig til Syne.',
        6: 'Og det hændte sig efter fyrretyve Dage, da oplod Noa Vinduet paa Arken, som han havde gjort.',
        7: 'Og han udlod en Ravn; den fløj frem og tilbage, indtil Vandet borttørredes af Jorden.',
        8: 'Og han udlod en Due fra sig for at se, om Vandet var sunket fra Jordens Overflade.',
        9: 'Og der Duen ikke fandt det, den kunde hvile sin Fodsaale paa, da kom den igen til ham i Arken, fordi Vandet endnu var over den ganske Jord; og han udrakte sin Haand og annammede den og tog den til sig i Arken.',
        10: 'Da biede han endnu syv andre Dage og udlod atter en Due af Arken.',
        11: 'Og den Due kom til ham ved Aftens Tid, og se, den havde et afbrudt Olieblad i sin Mund; da fornam Noa, at Vandet var sunket paa Jorden.',
        12: 'Men han biede endnu andre syv Dage og udlod en Due, og den kom ikke ydermere til ham.',
        13: 'Og det skete i det seks Hundrede og første Aar, i den første Maaned, paa den første Dag i Maaneden, da tørredes Vandet fra Jorden; da tog Noa Dækket af Arken og saa sig om, og se, Jordens Overflade tørredes.',
        14: 'Og i den anden Maaned, paa den syr og tyvende Dag i Maaneden, blev Jorden tør.',
        15: 'Da talede Gud til Noa og sagde:',
        16: 'Gak ud ad Arken, du og din Hustru og dine Sønner og dine Sønners Hustruer med dig.',
        17: 'Udfør med dig alle Dyr, som ere hos dig af alt Kød, af Fugle og af Kvæg og af alle Kryb, som krybe paa Jorden, og de skulle vrimle paa Jorden og vorde frugtbare og mangfoldige paa Jorden.',
        18: 'Saa gik Noa ud og hans Sønner og hans Hustru og hans Sønners Hustruer med ham.',
        19: 'Alle vilde Dyr og alle Kryb og alle Fugle, alt hvad der kryber paa Jorden, efter deres Slags, de gik ud ad Arken.',
        20: 'Og Noa byggede Herren et Alter og tog af alle Haande rent Kvæg og af alle Haande rene Fugle og ofrede Brændoffer paa Alteret.',
        21: 'Og Herren lugtede den behagelige Lugt; da sagde Herren i sit Hjerte: Jeg vil ikke mere herefter forbande Jorden for Menneskets Skyld, thi Menneskets Hjertes Tanke er ond fra hans Ungdom; og jeg vil ikke mere slaa alt, hvad der lever, saaledes som jeg har gjort.',
        22: 'Saa længe Jorden staar, skal Sæd og Høst og Frost og Hede og Sommer og Vinter og Dag og Nat ikke aflade.',
    },
    9: {
        1: 'Og Gud velsignede Noa og hans Sønner og sagde til dem: Vorder frugtbare og mangfoldige, og opfylder Jorden!',
        2: 'Og Frygt for eder og Rædsel for eder skal være over alle vilde Dyr paa Jorden og over alle Fugle under Himmelen, over alt det, som kryber paa Jorden, og over alle Fiske i Havet, de skulle være givne i eders Hænder.',
        3: 'Alt det, som vrimler, som lever, skal være eder til Spise, ligesom grønne Urter har jeg givet eder alt dette.',
        4: 'Dog Kød med Sjælen, med Blodet i, maa I ikke æde.',
        5: 'Derimod eders Livs Blod vil jeg kræve, af alle Dyrs Haand vil jeg kræve det; og af Menneskenes Haand, af hvers Haand, endog af hans Broders, vil jeg kræve Menneskenes Sjæl.',
        6: 'Hvo som udøser Menneskenes Blod, ved Mennesket skal hans Blod udøses; thi i Guds Billede gjorde han Mennesket.',
        7: 'Og vorder frugtbare og mangfoldige, vrimler paa Jorden og vorder mangfoldige derpaa.',
        8: 'Og Gud talede til Noa og til hans Sønner med ham og sagde:',
        9: 'Jeg, se, jeg opretter min Pagt med eder og med eders Afkom efter eder',
        10: 'og med hver levende Sjæl, som er hos eder af Fugle, af Kvæg og af alle vilde Dyr paa Jorden hos eder, af alle dem, som gik ud ad Arken, af alle Dyr, som ere paa Jorden.',
        11: 'Og jeg opretter min Pagt med eder, at herefter skal intet Kød ødelægges af Flodens Vande, og der skal ikke komme Vandflod herefter at fordærve Jorden.',
        12: 'Og Gud sagde: Dette er et Tegn paa den Pagt, som jeg gør imellem mig og imellem eder og imellem hver levende Sjæl, som er hos eder, til evig Tid.',
        13: 'Jeg har sat min Bue i Skyen, og den skal være til en Pagtes Tegn imellem mig og imellem Jorden.',
        14: 'Og det skal ske, naar jeg fører Skyen over Jorden, da skal Buen ses i Skyen.',
        15: 'Og jeg vil komme min Pagt i Hu, som er imellem mig og imellem eder og imellem alle levende Sjæle af alt Kød, at Vandene ikke mere skulle blive til en Flod, at fordærve alt Kød.',
        16: 'Derfor skal Buen være i Skyen, og jeg vil se den for at ihukomme den evige Pagt imellem Gud og imellem alle levende Sjæle af alt Kød, som er paa Jorden.',
        17: 'Og Gud sagde til Noa: Dette skal være et Tegn paa den Pagt, som jeg har oprettet imellem mig og imellem alt Kød, som er paa Jorden.',
        18: 'Og Noas Sønner, som gik ud ad Arken, vare Sem og Kam og Jafet; men Kam er Kanaans Fader.',
        19: 'Disse tre ere Noas Sønner, og af disse blev hele Jorden befolket alle Vegne.',
        20: 'Men Noa begyndte at blive en Avlsmand og plantede en Vingaard.',
        21: 'Og han drak af Vinen og blev drukken og blottede sig midt i sit Telt.',
        22: 'Der Kam, Kanaans Fader, saa sin Faders Blusel, forkyndte han begge sine Brødre det udenfor.',
        23: 'Da tog Sem og Jafet et Klæde og lagde det begge paa deres Skulder og gik baglæns og skjulte deres Faders Blusel; og deres Ansigter vare bortvendte, at de ikke saa deres Faders Blusel.',
        24: 'Og Noa vaagnede op af sin Vin og fik at vide, hvad hans yngste Søn havde gjort ham.',
        25: 'Da sagde han: Forbandet være Kanaan, han skal være Trælles Træl for sine Brødre!',
        26: 'Og han sagde: Lovet være Herren, Sems Gud, og Kanaan skal være deres Træl!',
        27: 'Gud udbrede Jafet, og han skal bo i Sems Pauluner, og Kanaan skal være deres Træl!',
        28: 'Og Noa levede efter Floden tre Hundrede Aar og halvtredsindstyve Aar.',
        29: 'Og alle Noas Dage vare ni Hundrede Aar og halvtredsindstyve Aar; og han døde.',
    },
    10: {
        1: 'Og disse ere Noas Sønners Slægter, Sems, Kams og Jafets; og dem fødtes Børn efter Floden.',
        2: 'Jafets Sønner vare: Gomer og Magog og Madai og Javan og Thubal og Mesek og Thiras.',
        3: 'Og Gomers Sønner: Askenas og Rifat og Thogarma.',
        4: 'Og Javans Sønner: Elisa og Tharsis, Kithim og Dodanim.',
        5: 'Af disse bleve Hedningernes Øer befolkede i deres Lande, hver efter sit Tungemaal, efter deres Slægter, i deres Folk.',
        6: 'Og Kams Sønner vare: Kus og Mizraim og Put og Kanaan.',
        7: "Og Kus' Sønner: Seba og Havila og Sabtha og Raema og Sabtheka; og Raemas Sønner: Skeba og Dedan.",
        8: 'Men Kus avlede Nimrod; han begyndte at blive en vældig paa Jorden.',
        9: 'Han var en vældig Jæger for Herrens Ansigt; derfor siges: Som Nimrod, en vældig Jæger for Herrens Ansigt.',
        10: 'Og Babel var hans Riges Begyndelse, og Erek og Akad og Kalne i Landet Sinear.',
        11: 'Fra dette Land drog han ud til Assur, og han byggede Ninive og Rekoboth-Ir og Kala',
        12: 'og Resen imellem Ninive og Kala; denne er den store Stad.',
        13: 'Og Mizraim avlede Luder og Anamer og Lehaber og Naftuher',
        14: 'og Pathruser og Gasluher, fra hvilke Filisterne udgik, og Kaftorer.',
        15: 'Og Kanaan avlede Zidon, sin førstefødte, og Heth',
        16: 'og Jebusiter og Amoriter og Girgarsiter',
        17: 'og Heviter og Arkiter og Siniter',
        18: 'og Arvaditer og Zemariter og Hamathiter; og derefter udbredte sig Kananiternes Slægter.',
        19: 'Og Kananiternes Grænse var fra Zidon henimod Gerar indtil Gaza, henimod Sodoma og Gomorra, Adma og Zeboim indtil Lasa.',
        20: 'Disse ere Kams Børn efter deres Slægter, efter deres Tungemaal, i deres Lande, i deres Folk.',
        21: 'Og Sem fødtes ogsaa Børn; han var alle Ebers Børns Fader, Jafets ældre Broder.',
        22: 'Sems Sønner vare: Elam og Assur og Arfaksad og Lud og Aram.',
        23: 'Og Arams Sønner vare: Uz og Hul og Gether og Mas.',
        24: 'Og Arfaksad avlede Sala; og Sala avlede Eber.',
        25: 'Og Eber fødtes to Sønner: den enes Navn var Peleg, fordi Jorden blev skiftet i hans Tid, og hans Broders Navn var Joktan.',
        26: 'Og Joktan avlede Almodad og Salef og Hazarmaveth og Jara',
        27: 'og Adoram og Usal og Dikla',
        28: 'og Obal og Abimael og Skeba',
        29: 'og Ofir og Havila og Jobab; alle disse ere Joktans Sønner.',
        30: 'Og deres Bolig var fra Mesa henimod Sefar, det Bjerg mod Østen.',
        31: 'Disse ere Sems Børn efter deres Slægter, efter deres Tungemaal, i deres Lande, efter deres Folk.',
        32: 'Disse ere Noas Børns Slægter i deres Afkom, i deres Folk; og af dem have Folkene adskilt sig paa Jorden efter Floden.',
    },
    11: {
        1: 'Og al Jorden havde eet Tungemaal og eet Sprog.',
        2: 'Og det skete, der de rejste fra Østen, da fandt de en Dal i Landet Sinear og boede der.',
        3: 'Og de sagde, den ene til den anden: Velan, lader os stryge Tegl og brænde dem vel; og de havde Tegl for Sten, og Jordbeg havde de for Kalk.',
        4: 'Og de sagde: Velan, lader os bygge os en Stad og et Taarn, hvis Spidse kan naa op til Himmelen, og lader os gøre os et Navn, at vi ikke skulle adspredes over al Jorden.',
        5: 'Da nedfor Herren for at se den Stad og det Taarn, som Menneskens Børn byggede.',
        6: 'Og Herren sagde: Se, dette er eet Folk, og de have alle eet Tungemaal, og dette have de begyndt at gøre; og nu vil intet formenes dem af alt, hvad de faa i Sinde at gøre.',
        7: 'Velan, lader os fare ned og blande deres Tungemaal der, at den ene ikke forstaar den andens Tungemaal.',
        8: 'Og Herren adspredte dem derfra over al Jordens Kreds; og de lode af at bygge Staden.',
        9: 'Derfor kaldte man dens Navn Babel; thi Herren blandede der al Jordens Tungemaal, og Herren adspredte dem derfra over al Jordens Kreds.',
        10: 'Disse ere Sems Slægter. Sem var hundrede Aar gammel og avlede Arfaksad, to Aar efter Floden.',
        11: 'Og Sem levede, efter at han havde avlet Arfaksad, fem Hundrede Aar og avlede Sønner og Døtre.',
        12: 'Og Arfaksad levede fem og tredive Aar og avlede Sala.',
        13: 'Og Arfaksad levede, efter at han havde avlet Sala, fire Hundrede og tre Aar og avlede Sønner og Døtre.',
        14: 'Og Sala levede tredive Aar og avlede Eber.',
        15: 'Og Sala levede, efter at han havde avlet Eber, fire Hundrede Aar og tre Aar og avlede Sønner og Døtre.',
        16: 'Og Eber levede fire og tredive Aar og avlede Peleg.',
        17: 'Og Eber levede, efter at han havde avlet Peleg, fire Hundrede Aar og tredive Aar og avlede Sønner og Døtre.',
        18: 'Og Peleg levede tredive Aar og avlede Reu.',
        19: 'Og Peleg levede, efter at han havde avlet Reu, to Hundrede og ni Aar og avlede Sønner og Døtre.',
        20: 'Og Reu levede to og tredive Aar og avlede Serug.',
        21: 'Og Reu levede, efter at han havde avlet Serug, to Hundrede Aar og syv Aar og avlede Sønner og Døtre.',
        22: 'Og Serug levede tredive Aar og avlede Nakor.',
        23: 'Og Serug levede, efter at han havde avlet Nakor, to Hundrede Aar og avlede Sønner og Døtre.',
        24: 'Og Nakor levede ni og tyve Aar og avlede Thara.',
        25: 'Og Nakor levede, efter at han havde avlet Thara, hundrede Aar og nitten Aar og avlede Sønner og Døtre.',
        26: 'Og Thara levede halvfjerdsindstyve Aar og avlede Abram, Nakor og Haran.',
        27: 'Og disse ere Tharas Slægter. Thara avlede Abram, Nakor og Haran; og Haran avlede Lot.',
        28: 'Og Haran døde for Thara sin Faders Ansigt i sit Fædreneland, udi Ur i Kaldæa.',
        29: 'Og Abram og Nakor toge sig Hustruer; Abrams Hustrus Navn var Sarai og Nakors Hustrus Navn Milka, en Datter af Haran, som var Fader til Milka og Fader til Jiska.',
        30: 'Og Sarai var ufrugtbar, hun havde intet Barn.',
        31: 'Og Thara tog Abram sin Søn og Lot Harans Søn, sin Sønnesøn, og Sarai sin Sønnekvinde, som var Abrams, hans Søns Hustru, og de droge ud med dem fra Ur i Kaldæa, at drage til det Land Kanaan, og de kom til Haran og boede der.',
        32: 'Og Thara blev to Hundrede Aar og fem Aar gammel, og Thara døde i Haran.',
    },
    12: {
        1: 'Og Herren sagde til Abram: Gak du ud af dit Land og fra din Slægt og af din Faders Hus til det Land, som jeg vil vise dig.',
        2: 'Og jeg vil gøre dig til et stort Folk og velsigne dig og gøre dit Navn stort, og vær en Velsignelse.',
        3: 'Og jeg vil velsigne dem, som velsigne dig, og den, som forbander dig, vil jeg forbande; og i dig skulle alle Slægter paa Jorden velsignes.',
        4: 'Og Abram gik, ligesom Herren havde sagt til ham, og Lot gik med ham; og Abram var halvfjerdsindstyve Aar og fem Aar gammel, der han uddrog af Haran.',
        5: 'Saa tog Abram Sarai sin Hustru og Lot sin Broders Søn og al deres Ejendom, som de ejede, og de Folk, som de havde forskaffet sig i Haran, og de droge ud for at rejse til Kanaans Land, og de kom til Kanaans Land.',
        6: 'Og Abram drog igennem Landet til det Sted Sikem indtil More Lund; og Kananiten var da i Landet.',
        7: 'Og Herren aabenbaredes for Abram og sagde: Dit Afkom vil jeg give dette Land; og han byggede der et Alter for Herren, som aabenbaredes for ham.',
        8: 'Og han brød op derfra til Bjerget Østen for Bethel og udslog sit Telt, saa Bethel var mod Vesten og Ai mod Østen; og han byggede der et Alter for Herren og paakaldte Herrens Navn.',
        9: 'Og Abram rejste videre og vandrede mod Sønden.',
        10: 'Og der var Hunger i Landet, og Abram drog ned til Ægypten at leve som fremmed der; thi Hungeren var svar i Landet.',
        11: 'Og det skete, der han nærmede sig at komme til Ægypten, sagde han til Sarai sin Hustru: Se nu, jeg ved, at du er en dejlig Kvinde at se til.',
        12: 'Og det vil ske, naar Ægypterne se dig og sige: denne er hans Hustru, at de slaa mig ihjel og lade dig leve.',
        13: 'Kære, sig, at du er min Søster, at det kan gaa mig vel for din Skyld, og min Sjæl maa leve formedelst dig.',
        14: 'Og det skete, der Abram kom til Ægypten, da saa Ægypterne Kvinden, at hun var meget dejlig.',
        15: 'Og Faraos Fyrster saa hende og roste hende for Farao, og Kvinden blev ført til Faraos Hus.',
        16: 'Og han gjorde Abram godt for hendes Skyld; og han fik Faar og Kvæg og Asener og Svende og Tjenestepiger og Aseninder og Kameler.',
        17: 'Og Herren slog Farao og hans Hus med store Plager for Sarai, Abrams Hustrus, Skyld.',
        18: 'Da kaldte Farao ad Abram og sagde: Hvi har du gjort mig dette? hvi gav du mig ikke til Kende, at hun er din Hustru?',
        19: 'Hvorfor sagde du: hun er min Søster? og jeg tog hende mig til Hustru; og nu, se, der er din Hustru, tag hende og gak!',
        20: 'Og Farao gav sine Mænd Befaling om ham, og de udførte ham og hans Hustru og alt det, han havde.',
    },
    13: {
        1: 'Og Abram drog op af Ægypten, han og hans Hustru og alt det, han havde, og Lot med ham, mod Sønden.',
        2: 'Og Abram var meget rig paa Fæ, paa Sølv og paa Guld.',
        3: 'Og han drog paa sine Rejser fra Sønden og indtil Bethel, indtil det Sted, hvor hans Telt var i Begyndelsen, imellem Bethel og imellem Ai,',
        4: 'til det Alters Sted, som han havde gjort der i Førstningen; og Abram paakaldte der Herrens Navn.',
        5: 'Men og Lot, som vandrede med Abram, havde Faar og Fæ og Telte.',
        6: 'Og Landet kunde ikke bære dem, at de kunde bo hos hverandre; thi deres Ejendom var megen, saa de kunde ikke bo tilsammen.',
        7: 'Og der var Trætte imellem Abrams Fæhyrder og imellem Lots Fæhyrder; og der boede den Gang Kananiter og Feresiter i Landet.',
        8: 'Og Abram sagde til Lot: Kære, lad der ikke være Trætte imellem mig og imellem dig, og imellem mine Hyrder og imellem dine Hyrder; thi vi ere jo Brødre.',
        9: 'Er ikke det ganske Land for dig? Kære, skil dig fra mig; dersom du vil til den venstre Side, da vil jeg fare til den højre, og dersom du vil til den højre, da vil jeg fare til den venstre.',
        10: 'Og Lot opløftede sine Øjne, og saa den ganske Slette ved Jordanen, thi den var vandrig overalt; førend Herren fordærvede Sodoma og Gomorra, var den som Herrens Have, som Ægyptens Land, henimod Zoar.',
        11: 'Og Lot udvalgte sig hele Sletten ved Jordanen, og Lot drog Øster paa: den ene fra den anden.',
        12: 'Abram boede i Kanaans Land, og Lot boede i Stæderne paa Sletten og opslog Telte indtil Sodoma.',
        13: 'Og de Mænd i Sodoma vare onde, og de syndede saare mod Herren.',
        14: 'Og Herren sagde til Abram, efter at Lot var skilt fra ham: Kære, opløft dine Øjne; og se fra det Sted, hvor du er, mod Norden og mod Sønden og mod Østen og mod Vesten.',
        15: 'Thi alt det Land, som du ser, det vil jeg give dig og dit Afkom evindeligen.',
        16: 'Og jeg vil gøre dit Afkom som Støv paa Jorden; dersom nogen kan tælle Støvet paa Jorden, da skal ogsaa dit Afkom tælles.',
        17: 'Staa op, vandre igennem Landet, i dets Længde og i dets Bredde; thi dig vil jeg give det.',
        18: 'Saa opslog Abram Telt og kom og boede i Mamre Lund, som er i Hebron, og byggede der Herren et Alter.',
    },
    14: {
        1: 'Og det skete i de Dage, der Amrafel var Konge i Sinear, Ariok Konge i Elassar, Kedorlaomer Konge i Elam, og Thideal Konge over Gojim,',
        2: 'at de førte Krig mod Bera, Kongen af Sodoma, og imod Birsa, Kongen af Gomorra, Sineab, Kongen af Adma, og Semeber, Kongen af Zeboim, og Kongen af Bela, det er Zoar.',
        3: 'Alle disse kom sammen i Siddims Dal, det er Salthavet.',
        4: 'Tolv Aar havde de tjent Kedorlaomer, og i det trettende Aar vare de affaldne.',
        5: 'Og i det fjortende Aar kom Kedorlaomer og de Konger, som vare med ham, og sloge Refaiterne i Astharoth-Karnaim og Susiterne i Ham og Emiterne i Schaveh-Kirjathaim',
        6: 'og Horiterne paa deres Bjerg Sejr indtil Parans Slette, som er ved Ørken.',
        7: 'Derefter vendte de om og kom til den Kilde Mispat, det er Kades, og sloge Amalekiternes hele Land og Amoriterne, som boede i Hazezon-Thamar.',
        8: 'Da drog Kongen af Sodoma ud og Kongen af Gomorra og Kongen af Adma og Kongen af Zeboim og Kongen af Bela, det er Zoar, og rustede sig mod dem til Strid udi Siddims Dal,',
        9: 'imod Kedorlaomer, Kongen af Elam, og Thideal, Kongen over Gojim, og Amrafel, Kongen af Sinear, og Ariok, Kongen af Elassar, fire Konger mod fem.',
        10: 'Og Siddims Dal var fuld af Jordbegsgruber, og Kongen af Sodoma og Gomorra flyede, og de faldt deri; og de, som overbleve, flyede paa Bjerget.',
        11: 'Og de toge alt det Gods, som var i Sodoma og Gomorra, og al deres Føde og droge bort.',
        12: 'Og de toge Abrams Brodersøn, Lot, og hans Gods og droge bort; men han boede i Sodoma.',
        13: 'Da kom en, som var undkommen, og forkyndte Hebræeren Abram det; men han boede i Amoriten Mamres Lund; denne var Broder til Eskol og Broder til Aner, og disse vare i Forbund med Abram.',
        14: 'Der Abram hørte, at hans Broder var fangen, da væbnede han sine tre Hundrede og atten oplærte unge Karle, som vare fødte i hans Hus, og forfulgte dem til Dan.',
        15: 'Og han og hans Svende delte sig over dem om Natten og slog dem og forfulgte dem til Hoba, som ligger paa den venstre Side for Damaskus,',
        16: 'og han førte alt Godset tilbage, og tilmed Lot, sin Broder, og hans Gods førte han tilbage og desligeste Kvinderne og Folket.',
        17: 'Og Kongen af Sodoma gik ud imod ham, efter at han var kommen tilbage fra det Slag imod Kedorlaomer og de Konger, som vare med ham, til Schave-Dal, som kaldes Kongens Dal.',
        18: 'Og Melkisedek, Kongen af Salem, bragte Brød og Vin, og han var den højeste Guds Præst.',
        19: 'Og han velsignede ham og sagde: Velsignet være Abram for den højeste Gud, som ejer Himmel og Jord,',
        20: 'og velsignet være den højeste Gud, som gav dine Fjender i din Haand; og Abram gav ham Tiende af alt.',
        21: 'Og Kongen af Sodoma sagde til Abram: Giv mig Folket, og tag Godset til dig.',
        22: 'Men Abram sagde til Kongen af Sodoma: Jeg har opløftet min Haand til Herren, den højeste Gud, som ejer Himmel og Jord,',
        23: 'at jeg ikke vil tage saa meget som en Traad eller Skotvinge af alt det, som tilhører dig, at du ikke skal sige: jeg har gjort Abram rig;',
        24: 'undtagen det alene, som de unge Karle have fortæret, og de Mænds Del, som gik med mig, Aner, Eskol og Mamre, de maa tage deres Del.',
    },
    15: {
        1: 'Efter at dette var sket, kom Herrens Ord til Abram i et Syn, og sagde: Frygt ikke, Abram, jeg er dit Skjold og din meget store Løn.',
        2: 'Og Abram sagde: Herre, Herre, hvad vil du give mig? og jeg gaar hen uden Børn, og den, der forestaar mit Hus, er Elieser af Damaskus.',
        3: 'Og Abram sagde: Se, mig har du intet Afkom givet, og se, min vornede arver mig.',
        4: 'Og se, Herrens Ord skete til ham og sagde: Denne, han skal ikke arve dig; men den, som skal udkomme af dit Liv, han skal arve dig.',
        5: 'Og han førte ham udenfor og sagde: Kære, se til Himmelen, og tæl Stjernerne, om du kan tælle dem; og han sagde til ham: Saa skal dit Afkom vorde.',
        6: 'Og han troede paa Herren, og han regnede ham det til Retfærdighed.',
        7: 'Og han sagde til ham: jeg er Herren, som udførte dig fra Ur i Kaldæa for at give dig dette Land til at eje det.',
        8: 'Da sagde han: Herre, Herre, hvorpaa skal jeg kende, at jeg skal eje det?',
        9: 'Og han sagde til ham: Tag mig en tre Aar gammel Kvie og en tre Aar gammel Ged og en tre Aar gammel Vædder og en Turteldue og en Dueunge.',
        10: 'Og han tog ham alt dette og delte det midt over og lagde den ene Del deraf tvært overfor den anden; men Fuglene delte han ikke.',
        11: 'Og Rovfugle sloge ned paa de døde Kroppe; men Abram jog dem derfra.',
        12: 'Og det skete, der Solen vilde gaa ned, da faldt en dyb Søvn paa Abram, og se, der faldt Forfærdelse og stort Mørke over ham.',
        13: 'Da sagde han til Abram: du skal visseligen vide, at dit Afkom skal være fremmed i et Land, som ikke er deres, og de skulle trælle for dem, der skulle plage dem, fire Hundrede Aar.',
        14: 'Men jeg vil ogsaa dømme det Folk, som de skulle tjene; og derefter skulle de udgaa med meget Gods.',
        15: 'Men du skal fare til dine Fædre med Fred, og du skal blive begravet i en god Alderdom.',
        16: 'Og i den fjerde Slægt skulle de komme hid igen; thi Amoritens Ondskab er endnu ikke fuld.',
        17: 'Og det skete, der Solen var nedgangen, og der var stort Mørke, se, da var der en rygende Ovn og Ilds Blus, som for hen imellem disse Stykker.',
        18: 'Paa den samme Dag gjorde Herren en Pagt med Abram og sagde: Dit Afkom har jeg givet dette Land, fra Ægyptens Flod indtil den store Flod, den Flod Frat,',
        19: 'Keniter og Kenisiter og Kadmoniter',
        20: 'og Hethiter og Feresiter og Refaiter',
        21: 'og Amoriter og Kananiter og Girgasiter og Jebusiter.',
    },
    16: {
        1: 'Og Sarai, Abrams Hustru, fødte ham ikke Børn; men hun havde en ægyptisk Pige, og hendes Navn var Hagar.',
        2: 'Og Sarai sagde til Abram: Se nu, Herren har tillukket mig, at jeg kan ikke føde; kære, gak til min Pige, maaske jeg kunde bygges ved hende; og Abram lød Sarais Røst.',
        3: 'Saa tog Sarai, Abrams Hustru, Hagar, sin ægyptiske Pige, efter Udløbet af de ti Aar, Abram havde boet i Kanaans Land, og hun gav Abram sin Mand hende til hans Hustru.',
        4: 'Og han gik til Hagar, og hun undfik; der hun saa, at hun havde undfanget, da blev hendes Frue ringeagtet af hende.',
        5: 'Da sagde Sarai til Abram: Den Uret sker mig formedelst dig; jeg har givet min Pige i din Favn, og hun ser, at hun har undfanget, og jeg er ringeagtet af hende; Herren skal dømme imellem mig og imellem dig.',
        6: 'Da sagde Abram til Sarai: Se, din Pige er i din Haand, gør med hende, som dig godt synes; og Sarai ydmygede hende, saa flyede hun fra hendes Aasyn.',
        7: 'Men Herrens Engel fandt hende ved en Vandkilde i Ørken, ved den Kilde paa Vejen til Sur.',
        8: "Og han sagde: Hagar, Sarai' Pige, hvorfra kommer du, og hvorhen gaar du? og hun sagde: Jeg flyr fra min Frue Sarai' Aasyn.",
        9: 'Og Herrens Engel sagde til hende: Gak tilbage til din Frue, og ydmyg dig under hendes Hænder.',
        10: 'Og Herrens Engel sagde til hende: Jeg vil gøre dit Afkom meget mangfoldigt, og det skal ikke tælles for Mangfoldighed.',
        11: 'Og Herrens Engel sagde fremdeles til hende: Se, du er frugtsommelig og skal føde en Søn, og du skal kalde hans Navn Ismael, fordi Herren har hørt din Modgang.',
        12: 'Og han skal blive et vildt Menneske, hans Haand skal være imod hver, og hvers Haand imod ham, og han skal bo Østen for alle sine Brødre.',
        13: 'Og hun kaldte Herrens Navn, som talede med hende: „Du mit Syns Gud‟; thi hun sagde: Mon jeg her ser efter mit Syn?',
        14: 'Derfor kaldte man den Kilde: Beer Lakai Roi; se, den er imellem Kades og Bered.',
        15: 'Og Hagar fødte Abram en Søn, og Abram kaldte sin Søns Navn, som Hagar fødte, Ismael.',
        16: 'Og Abram var seks Aar og firsindstyve Aar gammel, der Hagar fødte Abram Ismael.',
    },
    17: {
        1: 'Og Abram var ni Aar og halvfemsindstyve Aar gammel, og Herren aabenbaredes for Abram og sagde til ham: Jeg er den almægtige Gud, vandre for mit Ansigt og vær fuldkommen!',
        2: 'Og jeg vil gøre min Pagt imellem mig og imellem dig og formere dig saare meget.',
        3: 'Da faldt Abram paa sit Ansigt, og Gud talede med ham og sagde:',
        4: 'Hvad mig angaar, se, min Pagt er med dig, og du skal vorde mange Folks Fader.',
        5: 'Og dit Navn skal ikke ydermere kaldes Abram, men dit Navn skal være Abraham; thi jeg har gjort dig til mange Folks Fader.',
        6: 'Og jeg vil gøre dig saare meget frugtbar og gøre dig til Folk, og Konger skulle udgaa af dig.',
        7: 'Og jeg vil oprette min Pagt imellem mig og imellem dig, og imellem dit Afkom efter dig, i deres Slægter, til en evig Pagt, til at være en Gud for dig og dit Afkom efter dig.',
        8: 'Og jeg vil give dig og dit Afkom efter dig det Land, som du er fremmed udi, det hele Kanaans Land, til en evig Ejendom, og jeg vil være dem en Gud.',
        9: 'Og Gud sagde til Abraham: Og du skal holde min Pagt, du og dit Afkom efter dig, i deres Slægter.',
        10: 'Denne er min Pagt, som I skulle holde, imellem mig og imellem eder og imellem dit Afkom efter dig: alt Mandkøn skal omskæres hos eder.',
        11: 'Og I skulle omskære eders Forhuds Kød, og det skal være til en Pagtes Tegn imellem mig og imellem eder.',
        12: 'Og hvert Drengebarn, som er otte Dage gammelt, skal omskæres af eder hos eders Efterkommere, et hjemfødt Barn og den, som er købt for Penge af hver fremmed, som ikke selv er af dit Afkom.',
        13: 'Din hjemfødte og den, som er købt for dine Penge, skal omskæres, og min Pagt i eders Kød skal være til en evig Pagt.',
        14: 'Og er der et Drengebarn, som har Forhud, og hans Forhuds Kød ikke bliver omskaaret, da skal den samme Sjæl udslettes af sit Folk; han har brudt min Pagt.',
        15: 'Og Gud sagde til Abraham: Hvad angaar Sarai, din Hustru, du skal ikke kalde hendes Navn Sarai; thi Sara skal være hendes Navn.',
        16: 'Og jeg vil velsigne hende, og af hende vil jeg ogsaa give dig en Søn; og jeg vil velsigne hende, og hun skal vorde til Folkefærd, Folks Konger skulle vorde af hende.',
        17: 'Og Abraham faldt paa sit Ansigt og lo, og han sagde i sit Hjerte: Skulde nogen fødes for mig, som er hundrede Aar gammel? og skulde Sara, som er halvfemsindstyve Aar gammel, føde?',
        18: 'Og Abraham sagde til Gud: Gid Ismael maatte leve for dit Ansigt!',
        19: 'Og Gud sagde: Sandelig, Sara, din Hustru, skal føde dig en Søn, og du skal kalde hans Navn Isak, og jeg vil oprette min Pagt med ham til en evig Pagt for hans Afkom efter ham.',
        20: 'Og om Ismael har jeg hørt dig; se, jeg har velsignet ham og vil gøre ham frugtbar og gøre ham saare meget mangfoldig, han skal avle tolv Fyrster, og jeg vil gøre ham til et stort Folk.',
        21: 'Men min Pagt vil jeg stadfæste med Isak, som Sara skal føde dig paa den bestemte Tid i det næste Aar.',
        22: 'Og han lod af at tale med ham, og Gud for op fra Abraham.',
        23: 'Saa tog Abraham Ismael, sin Søn, og alle, som vare fødte i hans Hus, og alle, som vare købte for hans Penge, alt Mandkøn af Folkene, som vare i Abrahams Hus, og han omskar deres Forhuds Kød paa den selvsamme Dag, ligesom Gud havde talet med ham.',
        24: 'Og Abraham var ni og halvfemsindstyve Aar gammel, der hans Forhuds Kød blev omskaaret.',
        25: 'Og Ismael, hans Søn, var tretten Aar gammel, der hans Forhuds Kød blev omskaaret.',
        26: 'Paa den selvsamme Dag bleve Abraham og Ismael, hans Søn, omskaarne.',
        27: 'Og alle Mænd i hans Hus, den hjemfødte og den, som var købt for Penge af den fremmede, de bleve omskaarne med ham.',
    },
    18: {
        1: 'Og Herren aabenbaredes for ham i Mamre Lund, og han sad i sit Telts Dør, der Dagen var hed.',
        2: 'Og han opløftede sine Øjne og saa, og se, tre Mænd stode for ham; og der han saa dem, løb han dem i Møde fra Teltets Dør og bøjede sig til Jorden.',
        3: 'Og han sagde: Min Herre! Kære, dersom jeg har fundet Naade for dine Øjne, da gak ikke din Tjener forbi!',
        4: 'Kære, lad hente lidt Vand, og toer eders Fødder, og hviler eder under Træet!',
        5: 'Og jeg vil hente en Mundfuld Brød, og vederkvæger eders Hjerte, siden kunne I gaa længere; thi derfor gik I forbi eders Tjener; og de sagde: Gør saaledes, som du har sagt.',
        6: 'Og Abraham skyndte sig til Teltet, til Sara, og sagde: Tag hastig tre Maader Hvedemel, ælt og bag Kager!',
        7: 'Og Abraham løb til Kvæget og hentede en blød og god Kalv, og han gav Drengen den, og han skyndte sig at tilberede den.',
        8: 'Og han tog Fløde og Mælk og Kalven, som han havde ladet tilberede, og satte for dem, og han stod hos dem under Træet, og de aade.',
        9: 'Og de sagde til ham: Hvor er Sara, din Hustru? og han svarede: Se, i Teltet.',
        10: 'Og han sagde: Jeg vil visseligen komme til dig igen ved denne Aarsens Tid, og se, Sara, din Hustru, skal have en Søn; og Sara hørte det i Teltets Dør, og den var bag ham.',
        11: 'Og Abraham og Sara vare gamle, vel ved Alder, det gik ikke mere Sara efter Kvinders Vis.',
        12: 'Og Sara lo ved sig selv og sagde: Skulde jeg lade mig lyste, efter at jeg er bleven gammel, og min Herre er gammel!',
        13: 'Da sagde Herren til, Abraham: Hvorfor lo Sara og sagde: monne jeg og visseligen skal føde, og jeg er gammel!',
        14: 'Skulde nogen Ting være underlig for Herren? til den bestemte Tid vil jeg komme til dig igen, ved denne Aarsens Tid, og Sara skal have en Søn.',
        15: 'Og Sara nægtede og sagde: Jeg lo ikke; thi hun frygtede; men han sagde: Nej, thi du lo.',
        16: 'Saa stode Mændene op derfra og vendte sig imod Sodoma, og Abraham gik med dem for at ledsage dem.',
        17: 'Da sagde Herren: Skulde jeg dølge for Abraham det, jeg gør?',
        18: 'efterdi Abraham skal visseligen vorde et stort og stærkt Folk, og alle Folk paa Jorden skulle velsignes i ham.',
        19: 'Thi jeg kender ham, at han skal byde sine Børn og sit Hus efter sig, at de skulle bevare Herrens Vej i at gøre Retfærdighed og Dom, paa det at Herren skal lade det komme over Abraham, som han har lovet ham.',
        20: 'Og Herren sagde: Efterdi Skriget i Sodoma og Gomorra er stort, og efterdi deres Synd er meget svar,',
        21: 'da vil jeg nu fare ned og se, om de have gjort ganske efter det Skrig, som er kommet for mig, eller hvis ikke, saa vil jeg vide det.',
        22: 'Og Mændene vendte deres Ansigt derfra og gik til Sodoma; men Abraham blev endnu staaende for Herrens Aasyn.',
        23: 'Og Abraham traadte frem og sagde: Vil du da ødelægge den retfærdige med den ugudelige?',
        24: 'Der maatte maaske være halvtredsindstyve retfærdige i Staden; vil du og ødelægge og ej spare det Sted for de halvtredsindstyve retfærdiges Skyld, som kunde være derinde?',
        25: 'Det være langt fra dig at gøre efter denne Vis, at ihjelslaa den retfærdige med den ugudelige, at den retfærdige skulde være ligesom den ugudelige, det være langt fra dig; den, som dømmer den ganske Jord, skulde han ikke gøre Ret?',
        26: 'Da sagde Herren: Dersom jeg finder halvtredsindstyve retfærdige udi Sodoma Stad, da vil jeg spare hele Stedet for deres Skyld.',
        27: 'Og Abraham svarede og sagde: Se nu, jeg har begyndt at tale til Herren, og jeg er Støv og Aske.',
        28: 'Der maatte maaske fattes fem i de halvtredsindstyve retfærdige, vilde du ødelægge hele Staden for de fems Skyld? Og han sagde: Jeg vil ikke ødelægge den, om jeg finder fem og fyrretyve der.',
        29: 'Og han blev endnu ved at tale til ham og sagde: Der maatte maaske findes fyrretyve; og han sagde: Jeg vil ikke gøre det for de fyrretyves Skyld.',
        30: 'Og han sagde: Herren blive dog ikke vred, saa vil jeg tale: der kunde maaske findes tredive; og han sagde: Jeg vil ikke gøre det, om jeg finder tredive der.',
        31: 'Og han sagde: Se nu, jeg har begyndt at tale til Herren, der maatte maaske findes tyve; og han sagde: Jeg vil ikke ødelægge den for de tyves Skyld.',
        32: 'Og han sagde: Herren blive dog ikke vred, saa vil jeg tale alene denne Gang: der maatte maaske findes ti; og han sagde: Jeg vil ikke ødelægge den for de tis Skyld.',
        33: 'Og Herren gik bort, der han havde udtalt med Abraham, og Abraham vendte om til sit Sted.',
    },
    19: {
        1: 'Og de to Engle kom til Sodoma om Aftenen; men Lot sad i Sodomas Port, og der Lot saa dem, da stod han op og gik dem i Møde og bøjede Ansigtet til Jorden.',
        2: 'Og lian sagde: Se nu mine Herrer, kommer dog ind i eders Tjeners Hus, og bliver her i Nat, og toer eders Fødder, saa maa I staa aarle op og gaa eders Vej; og de sagde: Nej, men vi ville blive paa Gaden i Nat.',
        3: 'Da nødte han dem meget, og de gik ind til ham og kom i hans Hus, og han gjorde dem et Gæstebud og bagede usyrede Brød, og de aade.',
        4: 'Men førend de lagde sig, da omringede Mændene af Staden, Mændene af Sodoma, Huset, baade ung og gammel, det ganske Folk allesteds fra.',
        5: 'Og de kaldte ad Lot og sagde til ham: Hvor ere de Mænd, som kom til dig i Nat? før dem ud til os, at vi maa kende dem.',
        6: 'Da gik Lot ud til dem uden for Døren og lukkede Døren efter sig.',
        7: 'Og han sagde: Mine Brødre, kære, gører dem intet ondt!',
        8: 'Se, kære, jeg har to Døtre, som ikke have kendt Mand, kære, jeg vil lede dem ud til eder, gører saa med dem, hvad eder godt synes; kun disse Mænd maa I ikke gøre noget; thi derfor ere de komne under mit Tags Skygge.',
        9: 'Og de sagde: Kom nærmere; og de sagde: Denne ene er kommen at bosætte sig her og vil dømme; nu, vi ville gøre dig mere ondt end dem; saa trængte de saare hart ind paa Manden, paa Lot, og traadte til for at bryde Døren op.',
        10: 'Da udrakte Mændene deres Hænder og toge Lot ind til sig i Huset og lukkede Døren.',
        11: 'Og Mændene, som vare uden for Husets Dør, sloge de med Blindhed, baade liden og stor, og disse søgte med Møje at finde Døren.',
        12: 'Da sagde de Mænd til Lot: Har du endnu her nogen Svigersøn eller Sønner eller Døtre af dig eller nogen, som hører dig til i Staden, saa før dem ud fra dette Sted!',
        13: 'Thi vi skulle ødelægge dette Sted; thi deres Skrig er blevet stort for Herrens Aasyn, og Herren sendte os til at ødelægge den.',
        14: 'Og Lot gik ud og talede med sine Svigersønner, som skulde tage hans Døtre, og sagde: Staar op, gaar ud fra dette Sted, thi Herren vil ødelægge Staden; men han syntes for hans Svigersønners Øjne, som han gækkede.',
        15: 'Og der det begyndte at dages, da skyndte Englene paa Lot og sagde: Staa op, tag din Hustru og dine to Døtre, som ere til Stede, at ikke ogsaa du omkommer ved Stadens Misgerning.',
        16: 'Der han tøvede, da toge Mændene ham ved Haanden og hans Hustru ved Haanden og hans to Døtre ved Haanden, fordi Herren vilde spare ham, og de førte ham ud og lode ham blive uden for Staden.',
        17: 'Og det skete, der de havde ført dem udenfor, da sagde den ene: Frels dit Liv, se ikke bag dig, og stands ikke paa hele Sletten, frels dig paa Bjerget, at du ikke omkommer.',
        18: 'Da sagde Lot til dem: Ak nej, Herre!',
        19: 'Se nu, din Tjener har fundet Naade for dine Øjne, og du har ladet din Miskundhed blive stor, som du har bevist mig, ved at lade mig leve; og jeg kan ikke frelse mig paa Bjerget, Ulykken maatte komme paa mig, saa at jeg døde.',
        20: 'Se, kære, denne Stad er nær ved, den kunde jeg fly til, og den samme er liden; kære, der vil jeg frelse mig, er den ikke liden? at min Sjæl maa leve.',
        21: 'Da sagde han til ham: Se, jeg har og bønhørt dig i dette Stykke, at jeg ikke vil omstyrte den Stad, som du har talt om,',
        22: 'Skynd dig, red dig der! thi jeg kan intet gøre, før du kommer derhen; derfor kaldes den Stads Navn Zoar.',
        23: 'Solen var opgangen over Jorden, og Lot kom til Zoar.',
        24: 'Herren lod regne over Sodoma og over Gomorra Svovl og Ild, fra Herren af Himmelen.',
        25: 'Og han omstyrtede disse Stæder og den ganske Egn og alle Indbyggerne i Stæderne og Jordens Grøde.',
        26: 'Da saa hans Hustru om bag ham og blev en Saltstøtte.',
        27: 'Og Abraham skyndte sig aarle op om Morgenen til Stedet, hvor han havde staaet for Herrens Ansigt.',
        28: 'Og han vendte sit Ansigt til Sodoma og Gomorra og til hele Landet paa Sletten, og han saa, og se, en Røg steg op af Landet som en Røg af en Ovn.',
        29: 'Og det skete, der Gud ødelagde Stæderne paa Sletten, da kom Gud Abraham i Hu, og han lod Lot føre ud midt af Ødelæggelsen, der han omstyrtede de Stæder, som Lot boede udi.',
        30: 'Og Lot gik op fra Zoar og blev paa Bjerget, og begge hans Døtre med ham; thi han frygtede for at blive i Zoar, og han blev i en Hule, han og begge hans Døtre.',
        31: 'Da sagde den førstefødte til den yngste: vor Fader er gammel, og der er ikke en Mand i dette Land, som kan komme til os efter al Jordens Vis.',
        32: 'Kom, lader os give vor Fader Vin at drikke og ligge hos ham, saa faa vi Sæd af vor Fader.',
        33: 'Saa gave de deres Fader Vin at drikke den samme Nat, og den førstefødte gik ind og lagde sig hos sin Fader, og han fornam ikke, der hun lagde sig, eller der hun stod op.',
        34: 'Og det skete den anden Dag, da sagde den førstefødte til den yngste: se, i Gaar Nat laa jeg hos min Fader, lader os ogsaa i denne Nat give ham Vin at drikke, og gak ind, lig hos ham, at vi kunne faa Sæd af vor Fader.',
        35: 'Saa gave de deres Fader ogsaa i den samme Nat Vin at drikke, saa gjorde den yngste sig rede og laa hos ham, og han fornam ikke, der hun lagde gig, eller der hun stod op.',
        36: 'Saa undfik begge Lots Døtre af deres Fader.',
        37: 'Og den førstefødte fødte en Søn, og hun kaldte hans Navn Moab; han er de Moabiters Fader indtil denne Dag.',
        38: 'Og den yngste fødte ogsaa en Søn og kaldte hans Navn Ben-Ammi; han er Ammons Børns Fader indtil denne Dag.',
    },
    20: {
        1: 'Og Abraham rejste derfra i Landet Sønder paa og boede imellem Kades og imellem Sur og var fremmed i Gerar.',
        2: 'Og Abraham sagde om Sara sin Hustru: hun er min Søster; saa udsendte Abimelek, Kongen af Gerar, og tog Sara.',
        3: 'Og Gud kom til Abimelek i en Drøm om Natten, og han sagde til ham: Se, du skal dø for den Kvindes Skyld, som du har taget; thi hun er en Mands Ægtehustru.',
        4: 'Og Abimelek havde ikke nærmet sig til hende, og han sagde: Herre, vil du og slaa retfærdigt Folk ihjel?',
        5: 'Har han ej selv sagt til mig: hun er min Søster? og hun, ja, hun har ogsaa selv sagt: han er min Broder; i mit Hjertes Oprigtighed og med uskyldige Hænder gjorde jeg dette.',
        6: 'Og Gud sagde til ham i Drømmen: Ogsaa jeg ved, at du gjorde det af et oprigtigt Hjerte; derfor har jeg ogsaa forhindret dig, at du ikke skulde synde mod mig, derfor har jeg ikke tilstedt dig at røre ved hende.',
        7: 'Og nu, lad Manden faa sin Hustru tilbage, thi han er en Profet, og han skal bede for dig, saa skal du leve; men dersom du ikke lader hende komme tilbage, da vid, at du skal visseligen dø, du og enhver, som hører dig til.',
        8: 'Da stod Abimelek aarle op om Morgenen og kaldte ad alle sine Tjenere og sagde alle disse Ord for deres Øren, og Mændene frygtede saare.',
        9: 'Og Abimelek kaldte ad Abraham og sagde til ham: Hvad har du gjort os? og hvad har jeg syndet imod dig, at du har ført saa stor en Synd over mig og mit Rige? du har gjort imod mig de Ting, som ikke burde at ske.',
        10: 'Og Abimelek sagde til Abraham: Hvad saa du paa, at du gjorde dette?',
        11: 'Og Abraham sagde: Fordi jeg tænkte: her er slet ingen Gudsfrygt paa dette Sted, og de maatte slaa mig ihjel for min Hustrus Skyld.',
        12: 'Hun er dog ogsaa i Sandhed min Søster, min Faders Datter, men ikke min Moders Datter, og hun er bleven mig til Hustru.',
        13: 'Og det skete, den Tid Gud lod mig vanke hid og did fra min Faders Hus, da sagde jeg til hende: denne er din Kærlighed, som du skal vise mig: paa hvert det Sted, hvor vi komme hen, da sig om mig: han er min Broder.',
        14: 'Saa tog Abimelek Faar og Kvæg og Tjenere og Tjenestepiger og gav Abraham og gav ham Sara sin Hustru igen.',
        15: 'Og Abimelek sagde: Se, mit Land er aabent for dig, du maa bo, hvor det synes dig godt.',
        16: 'Og han sagde til Sara: Se, jeg har givet din Broder tusinde Sekel Sølv; se, det skal være dig Skjul for Øjne for alle dem som ere hos dig, ogsaa for alle andre; og det var hendes Straf.',
        17: 'Saa bad Abraham til Gud; og Gud helbredede Abimelek og hans Hustru og hans Tjenestekvinder, og de fødte.',
        18: 'Thi Herren havde aldeles lukket for hvert Moderliv i Abimeleks Hus, for Sara, Abrahams Hustrus, Skyld.',
    },
    21: {
        1: 'Og Herren besøgte Sara, ligesom han havde sagt, og Herren gjorde ved Sara, efter som han havde talet.',
        2: 'Og Sara undfik og fødte Abraham en Søn i hans Alderdom paa den bestemte Tid, som Gud havde sagt ham.',
        3: 'Og Abraham kaldte sin Søns Navn, som var født ham, som Sara havde født ham, Isak.',
        4: 'Og Abraham omskar Isak sin Søn, der han var otte Dage gammel, ligesom Gud havde befalet ham.',
        5: 'Og Abraham var hundrede Aar gammel, der hans Søn Isak blev født ham.',
        6: 'Da sagde Sara: Gud har gjort mig til Latter; hver den, som hører dette, maa le ad mig.',
        7: 'Og hun sagde: Hvo skulde have sagt til Abraham: Sara har givet Børn at die; thi jeg har født en Søn i hans Alderdom.',
        8: 'Og Barnet vokste op og blev afvant, og Abraham gjorde et stort Gæstebud den Dag, Isak blev afvant.',
        9: 'Og Sara saa Ægypterinden Hagars Søn, som hun havde født Abraham, at han spottede.',
        10: 'Og hun sagde til Abraham: Uddriv denne Tjenestekvinde og hendes Søn; thi denne Tjenestekvindes Søn skal ikke arve med min Søn, med Isak.',
        11: 'Og det Ord behagede Abraham saare ilde for hans Søns Skyld.',
        12: 'Men Gud sagde til Abraham: Lad det ikke behage dig ilde for Drengen og for din Tjenestekvinde; i hvad som helst Sara siger dig, lyd hendes Røst; thi udi Isak skal Sæden kaldes dig.',
        13: 'Og jeg vil ogsaa gøre Tjenestekvindens Søn til et Folk, fordi han er din Sæd.',
        14: 'Da stod Abraham aarle op om Morgenen og tog Brød og en Flaske Vand og gav Hagar og lagde det paa hendes Skuldre og flyede hende Drengen og lod hende fare; da drog hun hen og for vild i Beersaba Ørken.',
        15: 'Der Vandet var drukket af Flasken, da kastede hun Drengen under en af Buskene.',
        16: 'Og hun gik og satte sig tværs overfor, efter at hun var gaaet et Pileskud derfra; thi hun sagde: Jeg vil ikke se paa Drengens Død. Saa satte hun sig tværs overfor og opløftede sin Røst og græd.',
        17: 'Da hørte Gud Drengens Røst, og Guds Engel raabte til Hagar af Himmelen og sagde til hende: Hvad fattes dig, Hagar? frygt intet; thi Gud har hørt Drengens Røst, der hvor han er.',
        18: 'Staa op, opløft Drengen og hold fast paa ham med din Haand; thi jeg vil gøre ham til et stort Folk.',
        19: 'Og Gud oplod hendes Øjne, at hun saa en Vandbrønd, saa gik hun og fyldte Flasken med Vand og gav Drengen at drikke.',
        20: 'Og Gud var med Drengen, og han vokste op og boede i Ørken og blev en Bueskytte.',
        21: 'Og han boede i den Ørken Paran, og hans Moder tog ham en Hustru af Ægyptens Land.',
        22: 'Og det skete paa den samme Tid, da talede Abimelek og Pikol, hans Stridshøvedsmand, til Abraham og sagde: Gud er med dig i alt det, du gør.',
        23: 'Saa sværg mig nu her ved Gud, at du ikke vil handle svigefuldt imod mig og min Søn og min Sønnesøn; efter den Miskundhed, som jeg har gjort mod dig, skal du gøre mod mig og mod Landet, i hvilket du har været fremmed.',
        24: 'Da sagde Abraham: jeg vil sværge.',
        25: 'Og Abraham straffede Abimelek for den Vandbrønds Skyld, som Abimeleks Tjenere havde borttaget med Vold.',
        26: 'Da svarede Abimelek: Jeg vidste ikke, hvem der gjorde dette, og du har heller ikke givet mig det til Kende, og jeg har heller ikke hørt det førend i Dag.',
        27: 'Da tog Abraham Faar og Kvæg og gav Abimelek, og de gjorde begge et Forbund.',
        28: 'Og Abraham stillede syv Lam af Hjorden for sig selv.',
        29: 'Da sagde Abimelek til Abraham: Hvad skulle, disse syv Lam her, som du stillede for sig selv?',
        30: 'Og han svarede: Fordi du skal tage syv Lam af min Haand; og det skal være mig til et Vidnesbyrd, at jeg har gravet denne Brønd.',
        31: 'Derfor kaldte han dette Sted Beersaba; thi der svore de begge.',
        32: 'Og de gjorde Forbund i Beersaba; da stod Abimelek op og Pikol, hans Stridshøvedsmand, og droge igen til Filisternes Land.',
        33: 'Og han plantede en Lund i Beersaba og paakaldte der Herrens, den evige Guds, Navn.',
        34: 'Og Abraham var fremmed i Filisternes Land en lang Tid.',
    },
    22: {
        1: 'Og det skete derefter, at Gud fristede Abraham og sagde til ham: Abraham! og han sagde: se, her er jeg.',
        2: 'Og han sagde: Tag nu din Søn, din eneste, som du har kær, Isak, og gak du til Moria Land og offer ham der til et Brændoffer paa et af Bjergene, som jeg vil sige dig.',
        3: 'Saa stod Abraham aarle op om Morgenen og sadlede sit Asen og tog to af sine Drenge med sig og Isak sin Søn; og han kløvede Veddet til Brændofferet og gjorde sig rede og gik til Stedet, som Gud havde sagt ham.',
        4: 'Paa den tredje Dag, da opløftede Abraham sine Øjne og saa Stedet langt borte.',
        5: 'Da sagde Abraham til sine Drenge: Bliver I her med Asenet, og jeg og Drengen vi ville gaa derhen, og vi ville tilbede og komme til eder igen.',
        6: 'Og Abraham tog Veddet til Brændofferet og lagde paa Isak, sin Søn, men han tog Ilden og Kniven i sin Haand, og de gik begge tilsammen.',
        7: 'Da talede Isak til Abraham, sin Fader, og sagde: Min Fader! og denne sagde: Se, her er jeg, min Søn; og han sagde: Se, Ilden og Veddet! men hvor er Lammet til Brændofferet?',
        8: 'Og Abraham sagde: Gud skal selv udse sig Lammet til Brændofferet, min Søn; saa gik de begge tilsammen.',
        9: 'Og der de kom til det Sted, som Gud havde sagt ham, da byggede Abraham der et Alter og lagde Veddet til Rette, og han bandt Isak, sin Søn, og lagde ham paa Alteret oven paa Veddet.',
        10: 'Og Abraham rakte sin Haand ud og greb Kniven for at slagte sin Søn.',
        11: 'Da raabte Herrens Engel af Himmelen til ham og sagde: Abraham, Abraham! og han sagde: Se, her er jeg.',
        12: 'Og han sagde: Læg ikke din Haand paa Drengen og gør ham intet; thi nu kender jeg, at du frygter Gud og har ikke sparet din Søn, din eneste, for mig.',
        13: 'Da opløftede Abraham sine Øjne og saa, og se, en Vædder bag ham var indviklet i Busken ved sine Horn; og Abraham gik og tog Vædderen og ofrede den til Brændoffer i sin Søns Sted.',
        14: 'Saa kaldte Abraham det samme Steds Navn: Herren skal se; hvilket siges paa denne Dag: Paa Herrens Bjerg skal ses.',
        15: 'Og Herrens Engel raabte til Abraham anden Gang af Himmelen.',
        16: 'Og han sagde: Jeg har svoret ved mig, siger Herren, at fordi du gjorde dette og ikke sparede din Søn, den eneste:',
        17: 'derfor vil jeg storligen velsigne dig og meget mangfoldiggøre din Sæd som Stjernerne paa Himmelen og som Sand, der er ved Havets Bred, og din Sæd skal eje sine Fjenders Port;',
        18: 'og udi din Sæd skulle alle Folk paa Jorden velsignes, fordi du lød min Røst.',
        19: 'Saa gik Abraham tilbage til sine Drenge, og de gjorde sig rede og fore tilsammen til Beersaba; thi Abraham boede i Beersaba.',
        20: 'Og det skete efter disse Handeler, at det blev Abraham forkyndt, idet man sagde: Se, Milka, hun har ogsaa født din Broder Nakor Sønner,',
        21: 'nemlig Uz, hans førstefødte, og Bus, hans Broder, og Kemuel, Arams Fader,',
        22: 'og Kesed og Kaso og Pildask og Jidlaf og Bethuel;',
        23: 'men Bethuel avlede Rebekka; disse otte fødte Milka Nakor, Abrahams Broder.',
        24: 'Og han havde en Medhustru, og hendes Navn var Reuma, og hun fødte ogsaa Tebak og Gakam og Takask og Maaka.',
    },
    23: {
        1: 'Og Sara levede hundrede og syv og tyve Aar, disse vare Saras Livsaar.',
        2: 'Og Sara døde i Kirjath-Arba, det er Hebron i Kanaans Land; da kom Abraham for at sørge over Sara og at begræde hende.',
        3: 'Siden stod Abraham op fra sin dødes Aasyn og talede til Heths Børn og sagde:',
        4: 'Jeg er en fremmed og Gæst hos eder, giver mig en Ejendom til en Begravelse hos eder, at jeg kan begrave min døde og bringe hende bort fra mit Ansigt.',
        5: 'Da svarede Heths Børn Abraham og sagde til ham:',
        6: 'Hør os, min Herre! du er en Guds Fyrste iblandt os, begrav din døde i vore bedste Grave, ingen af os skal formene dig sin Grav, at du jo maa begrave din døde.',
        7: 'Da stod Abraham op og bøjede sig for Folket i Landet, for Heths Børn.',
        8: 'Og han talede med dem sigende: Dersom det er med eders Villie, at jeg maa begrave min døde og bringe hende bort fra mit Ansigt, da hører mig og beder for mig hos Efron, Zokars Søn,',
        9: 'at han vil give mig Hulen Makpela, som er hans, som er ved Enden af hans Ager; han give mig den for fuld Værdi midt iblandt eder til en Begravelses Ejendom.',
        10: 'Men Efron sad midt iblandt Heths Børn; da svarede Efron den Hethiter Abraham, saa at Heths Børn hørte derpaa, alle de, som gik ind ad hans Stads Port sigende:',
        11: 'Nej, min Herre, hør mig! jeg giver dig den Ager, og Hulen, som er paa den, giver jeg dig, for mit Folks Børns Øjne giver jeg dig den, begrav din døde!',
        12: 'Da bøjede Abraham sig for Folket i Landet,',
        13: 'og han talede med Efron i Folkets Paahør i Landet og sagde: Gid du dog blot vilde høre mig; jeg giver Sølv for Ageren, tag det af mig, og jeg vil begrave min døde der.',
        14: 'Da svarede Efron Abraham og sagde til ham:',
        15: 'Min Herre, hør mig! den Jord er fire Hundrede Sekel Sølv værd; hvad er det imellem mig og dig? begrav ikkun din døde.',
        16: 'Og Abraham lød Efron, og Abraham tilvejede Efron det Sølv, hvilket han havde nævnet, i Heths Børns Paahør, fire Hundrede Sekel Sølv, gængse i Køb.',
        17: 'Saa blev Efrons Ager, som er ved Makpela, som er tværs over for Mamre, Ageren og Hulen, som er paa den, og alle Træer, som vare paa Ageren inden al dens Grænse, stadfæstede',
        18: 'Abraham til en Ejendom i Heths Børns Aasyn, for alle, som gik ind ad hans Stads Port.',
        19: 'Og siden begrov Abraham Sara, sin Hustru, i Hulen paa Ageren, i Makpela tværs over for Mamre, det er Hebron i Kanaans Land.',
        20: 'Saa blev Ageren og Hulen paa den stadfæstede Abraham til en Begravelses Ejendom af Heths Børn.',
    },
    24: {
        1: 'Og Abraham var gammel, vel ved Alder, og Herren havde velsignet Abraham i alting.',
        2: 'Og Abraham sagde til sin ældste Svend i sit Hus, som raadede over alt hans Gods: Kære, læg din Haand under min Lænd,',
        3: 'og jeg vil lade dig sværge ved Herren, Himmelens Gud og Jordens Gud, at du ikke skal tage min Søn en Hustru af Kananiternes Døtre, iblandt hvilke jeg bor;',
        4: 'men du skal gaa til mit Land og til min Slægt og tage min Søn Isak en Hustru.',
        5: 'Og Svenden sagde til ham: Maaske Kvinden ikke vil drage med mig til dette Land; skal jeg da vel føre din Søn tilbage til det Land, som du er kommen fra?',
        6: 'Og Abraham sagde til ham: Forvar dig, at du ikke fører min Søn did igen.',
        7: 'Herren, Himmelens Gud, som tog mig fra min Faders Hus og fra min Slægts Land, og som talede med mig, og som tilsvor mig og sagde: dette Land vil jeg give din Sæd, han skal sende sin Engel for dig, at du skal tage min Søn en Hustru derfra.',
        8: 'Men dersom Kvinden ikke vil følge dig, da skal du være fri for denne min Ed; ikkun min Søn skal du ikke føre derhen.',
        9: 'Da lagde Svenden sin Haand under Abrahams, sin Herres, Lænd og tilsvor ham om denne Sag.',
        10: 'Saa tog Svenden ti Kameler af sin Herres Kameler og for bort og havde alle Haande af sin Herres Gods med sig og gjorde sig rede og drog til Aram Naharaim, til Nakors Stad.',
        11: 'Der lod han Kamelerne lægge sig uden for Staden ved en Vandbrønd mod Aftens Tid, mod den Tid da Kvinderne gaa ud at drage Vand.',
        12: 'Og han sagde: Herre, min Herre Abrahams Gud! Kære, lad det møde mig i Dag, og gør Miskundhed mod min Herre Abraham.',
        13: 'Se, jeg staar ved denne Vandbrønd, og Byens Folks Døtre komme ud at drage Vand.',
        14: 'Og naar det sker, at der kommer en Pige, til hvem jeg siger: Bøj nu din Krukke ned og lad mig drikke, og hun siger: Drik, og jeg vil ogsaa give dine Kameler at drikke, lad hende da være den, som du har udset til din Tjener Isak, saa jeg derpaa kan kende, at du har gjort Miskundhed mod min Herre.',
        15: 'Og det skete, før han havde endt at tale, se, da kom Rebekka ud, som var en Datter af Bethuel, som var en Søn af Milka, Nakors, Abrahams Broders, Hustru, og hendes Krukke var paa hendes Skulder.',
        16: 'Og Pigen var meget smuk af Anseelse, en Jomfru, og ingen Mand havde kendt hende, og hun gik ned til Brønden og fyldte sin Krukke og gik op.',
        17: 'Da løb Svenden imod hende og sagde: Kære, lad mig drikke lidt Vand af din Krukke.',
        18: 'Og hun sagde: Drik, min Herre! og hun skyndte sig og tog sin Krukke ned i sin Haand og gav ham at drikke.',
        19: 'Der hun havde givet ham at drikke, da sagde hun: Jeg vil og drage Vand til dine Kameler, til de have afdrukket.',
        20: 'Og hun skyndte sig og tømte sin Krukke i Truget og løb fremdeles til Brønden at øse, og hun drog til alle hans Kameler.',
        21: 'Og Manden undrede sig over hende, tav dog stille for at faa at vide, om Herren havde ladet hans Rejse lykkes eller ej.',
        22: 'Og det skete, der Kamelerne havde afdrukket, gav Manden hende en Guldring, som vejede en halv Sekel, og satte to Armbaand paa hendes Hænder, de vejede ti Guldsekler.',
        23: 'Og han sagde: Hvis Datter er du? Kære, sig mig, monne der være Rum i din Faders Hus at give os Nattely?',
        24: 'Og hun sagde til ham: Jeg er en Datter af Bethuel, som er en Søn af Milka, der fødte ham for Nakor.',
        25: 'Og hun sagde til ham: Der er baade Straa og meget Foder hos os, ogsaa er der Rum til Herberge i Nat.',
        26: 'Og Manden bøjede sig og tilbad Herren.',
        27: 'Og han sagde: Lovet være Herren, min Herre Abrahams Gud, som ikke har afladt med sin Miskundhed og sin Trofasthed mod min Herre! mig, ja, mig har Herren ført paa Vejen til min Herres Broders Hus.',
        28: 'Og Pigen løb og kundgjorde i sin Moders Hus disse Ting.',
        29: 'Og Rebekka havde en Broder, og hans Navn var Laban, og Laban løb ud til Manden, til Brønden.',
        30: 'Og det skete, der han saa Ringen og Armbaandene paa sin Søsters Hænder, og der han hørte Rebekkas, sin Søsters, Ord, at hun sagde: Saaledes har Manden sagt til mig, da kom han til Manden, og se, han stod hos Kamelerne ved Brønden.',
        31: 'Og han sagde: Kom ind, du Herrens Velsignede, hvi staar du herude? thi jeg har beredt Huset, og der er Rum for Kamelerne.',
        32: 'Saa kom Manden i Huset og løste Kamelerne, og han gav Straa og Foder til Kamelerne, og Vand til at to hans Fødder og de Mænds Fødder, som vare med ham.',
        33: 'Og der blev sat Mad for ham; men han sagde: Jeg vil ikke æde, før jeg har udsagt mit Ærinde; og han sagde: Tal!',
        34: 'Og han sagde: Jeg er Abrahams Svend.',
        35: 'Og Herren har velsignet min Herre meget, at han er bleven mægtig; og han har givet ham Faar og Kvæg og Sølv og Guld og Svende og Tjenestepiger og Kameler og Asener.',
        36: 'Og Sara, min Herres Hustru, har født min Herre en Søn, efter at hun var gammel, og denne har han givet alt det, han ejer.',
        37: 'Og min Herre har taget en Ed af mig og sagt: Du skal ikke tage min Søn en Hustru af Kananiternes Døtre, i hvis Land jeg bor.',
        38: 'Men du skal fare hen til min Faders Hus og til min Slægt og tage min Søn en Hustru.',
        39: 'Og jeg sagde til min Herre: Maaske Kvinden ikke vil drage med mig.',
        40: 'Og han sagde til mig: Herren, for hvis Ansigt jeg har vandret, skal sende sin Engel med dig og give dig en lyksalig Rejse, og du skal tage min Søn en Hustru af min Slægt og af min Faders Hus.',
        41: 'Da skal du være fri for min Ed, naar du kommer til min Slægt; og om de ikke ville give dig hende, saa er du fri for min Ed.',
        42: 'Saa kom jeg i Dag til Brønden og sagde: Herre, min Herre Abrahams Gud! Kære, dersom du har givet Lykke paa min Rejse, paa hvilken jeg har vandret,',
        43: 'se, jeg staar ved denne Vandbrønd, og naar det sker, der kommer en Jomfru ud at drage Vand, og jeg siger til hende: Giv mig nu lidet Vand at drikke af din Krukke;',
        44: 'og hun siger mig: Baade maa du drikke, og jeg vil ogsaa øse til dine Kameler, lad hende være den Kvinde, som Herren har udset til min Herres Søn.',
        45: 'Førend jeg havde udtalet i mit Hjerte, se, da kom Rebekka ud, og hendes Krukke var paa hendes Skulder, og hun gik ned til Brønden og drog Vand! da sagde jeg til hende: Kære, giv mig at drikke.',
        46: 'Saa skyndte hun sig og tog sin Krukke ned ad sig og sagde: Drik, og jeg vil ogsaa give dine Kameler at drikke; og jeg drak, og hun gav ogsaa Kamelerne at drikke.',
        47: 'Og jeg spurgte hende og sagde: Hvis Datter er du? og hun sagde: Jeg er en Datter af Bethuel, Nakors Søn, som Milka fødte ham. Saa hængte jeg en Ring i hendes Næse og Armbaand paa hendes Hænder.',
        48: 'Og jeg bøjede mig og tilbad Herren og lovede Herren, min Herre Abrahams Gud, som havde ledet mig paa den rette Vej at tage min Herres Broders Datter til hans Søn.',
        49: 'Og nu, dersom I ville vise Miskundhed og Trofasthed mod min Herre, siger mig det; men dersom I ikke ville det, da siger mig det, at jeg kan vende mig til den højre eller til den venstre Side.',
        50: 'Da svarede Laban og Bethuel og sagde: Denne Sag er kommen fra Herren, vi kunne hverken tale til dig ondt eller godt.',
        51: 'Se, der er Rebekka for dig, tag hende og gak, at hmi bliver din Herres Søns Hustru, som Herren har sagt.',
        52: 'Og det skete, der Abrahams Svend hørte deres Ord, da bøjede han sig til Jorden for Herren.',
        53: 'Og Svenden udtog Sølvtøj og Guldtøj og Klæder og gav Rebekka; men hendes Broder og hendes Moder gav han dyrebar Skænk.',
        54: 'Saa aade de og drak, han og de Mænd, som vare med ham, og bleve der om Natten, og de stode op om Morgenen, og han sagde: Lader mig fare til min Herre!',
        55: 'Da sagde hendes Broder og hendes Moder: Lad Pigen blive hos os nogle Dage eller ti, siden maa du fare.',
        56: 'Og han sagde til dem: Holder mig ikke op, thi Herren har givet Lykke paa min Rejse; lader mig fare, og jeg vil vandre til min Herre.',
        57: 'Og de sagde: Lader os kalde Pigen og spørge, hvad hun siger.',
        58: 'Saa kaldte de ad Rebekka og sagde til hende: Vil du fare med denne Mand? og hun sagde: Jeg vil fare.',
        59: 'Saa lode de deres Søster Rebekka og hendes Amme og Abrahams Svend og hans Mænd fare.',
        60: 'Og de velsignede Rebekka og sagde til hende: Vor Søster! bliv du til tusinde Gange Titusinde, og din Sæd skal eje sine Fjenders Port.',
        61: 'Saa stod Rebekka op og hendes Piger, og de satte sig paa Kameler og fore med Manden, og Svenden annammede Rebekka og for bort.',
        62: 'Og Isak kom gaaende fra den Brønd, som kaldes Beer Lakai Roi; thi han boede i Landet imod Sønden.',
        63: 'Og Isak var udgangen til at gøre Bøn paa Marken mod Aften, og han opløftede sine Øjne og saa, og se, Kamelerne kom.',
        64: 'Og Rebekka opløftede sine Øjne og saa Isak og steg hastig ned ad Kamelen.',
        65: 'Og hun sagde til Svenden: Hvo er den Mand, som gaar paa Marken imod os? og Svenden sagde: Det er min Herre; saa tog hun et Slør og skjulte sig.',
        66: 'Og Svenden fortalte Isak hele Sagen, som han havde udrettet.',
        67: 'Saa ledte Isak hende til sin Moder Saras Telt, og han tog Rebekka, og hun blev hans Hustru, og han elskede hende; og Isak blev trøstet efter sin Moder.',
    },
    25: {
        1: 'Og Abraham tog atter en Hustru, og hendes Navn var Ketura.',
        2: 'Og hun fødte ham Simran og Joksan og Medan og Midian og Jisbak og Sua.',
        3: 'Og Joksan avlede Seba og Dedan; men Dedans Børn vare Asurim og Letusim og Leumim.',
        4: 'Og Midians Børn vare Efa og Efer og Kanok og Abida og Eldaa; disse ere alle Keturas Børn.',
        5: 'Og Abraham gav Isak alt det, han ejede.',
        6: 'Men de Medhustruers Børn, som Abraham havde, gav Abraham Skænk og lod dem, medens han endnu levede, fare fra Isak sin Søn mod Østen til Østerland.',
        7: 'Og disse ere Abrahams Livs Aars Dage, som han levede: hundrede Aar og halvfjerdsindstyve Aar og fem Aar.',
        8: 'Og Abraham opgav Aanden og døde i en god Alderdom, gammel og mæt, og blev samlet til sit Folk,',
        9: 'Og Isak og Ismael, hans Sønner, begrove ham i Hulen Makpela, paa Efrons, Zokars den Hethiters Søns, Ager, som ligger tvært over for Mamre.',
        10: 'Paa den Ager, som Abraham købte af Heths Børn, der blev Abraham begraven og Sara hans Hustru.',
        11: 'Og det skete efter Abrahams Død, at Gud velsignede Isak hans Søn, og Isak boede ved den Kilde, som kaldes Beer Lakai Roi.',
        12: 'Og disse ere Ismaels, Abrahams Søns, Slægter, som Ægypterinden Hagar, Saras Pige, fødte Abraham.',
        13: 'Og disse ere Ismaels Børns Navne, efter deres Navne, i deres Slægter: Ismaels førstefødte Nebajoth og Kedar og Adbeel og Mibsam',
        14: 'og Misma og Duma og Massa,',
        15: 'Kadar og Thema, Jetur, Nafis og Kedma.',
        16: 'Disse ere Ismaels Sønner, og disse ere deres Navne udi deres Byer og i deres Lejre, tolv Fyrster for deres Folk.',
        17: 'Og disse ere Ismaels Livs Aar: hundrede Aar og tredive Aar og syv Aar, saa opgav han Aanden og døde og blev samlet til sit Folk.',
        18: 'Og de boede fra Havila indtil Sur, som er foran Ægypten og henimod Assyrien; hans Arv faldt foran alle hans Brødre.',
        19: 'Og disse ere Isaks, Abrahams Søns, Slægter: Abraham avlede Isak.',
        20: 'Og Isak var fyrretyve Aar gammel, der han tog Rebekka, Bethuel den Syrers Datter, af Paddan-Aram, Laban den Syrers Søster, sig til Hustru.',
        21: 'Og Isak bad til Herren paa sin Hustrus Vegne, thi hun var ufrugtbar; og Herren bønhørte ham, og Rebekka, hans Hustru, undfik.',
        22: 'Og Børnene stødte mod hinanden i hendes Liv, og hun sagde: Dersom det er saaledes, hvorfor er jeg da til? og hun gik at udspørge Herren.',
        23: 'Og Herren sagde til hende: Tvende Folk ere i dit Liv, og to forskellige Folk skulle udgaa af dit Liv, og det ene Folk skal være stærkere end det andet Folk, og det større skal tjene det mindre.',
        24: 'Der nu hendes Tid kom, at hun skulde føde, se, da vare der Tvillinger i hendes Liv.',
        25: 'Og den første kom frem, han var rød, ganske laadden som en Kappe, og de kaldte hans Navn Esau.',
        26: 'Og derefter kom hans Broder frem, og hans Haand havde fat paa Esaus Hæl, og man kaldte hans Navn Jakob; og Isak var tresindstyve Aar gammel, der han avlede dem.',
        27: 'Og Drengene bleve store, og Esau blev en Mand, som forstod sig paa Jagt og levede paa Marken; men Jakob var en from Mand, som boede i Telte.',
        28: 'Og Isak havde Esau kær, thi hans Jagt smagte ham; men Rebekka havde Jakob kær.',
        29: 'Og Jakob havde tilberedt en Ret, og Esau kom fra Marken og var træt.',
        30: 'Og Esau sagde til Jakob: Kære, lad mig smage af det røde, dette røde, thi jeg er træt; derfor kaldte man hans Navn Edom.',
        31: 'Da sagde Jakob: Sælg mig i Dag din Førstefødsel.',
        32: 'Og Esau sagde: Se, jeg gaar at dø, hvad kan jeg da gøre med den Førstefødsel?',
        33: 'Og Jakob sagde: Sværg mig i Dag; og han tilsvor ham, og han solgte Jakob sin Førstefødsel.',
        34: 'Da gav Jakob Esau Brød og den Ret af Linser, og han aad og drak og stod op og gik bort; og Esau foragtede Førstefødselen.',
    },
    26: {
        1: 'Og der var Hunger i Landet, foruden den forrige Hunger, som var i Abrahams Tid, og Isak drog til Abimelek, Filisternes Konge i Gerar.',
        2: 'Da aabenbaredes Herren for ham og sagde: Drag ikke ned til Ægypten, bo i det Land, hvilket jeg siger dig.',
        3: 'Vær en Udlænding i dette Land, og jeg vil være med dig og velsigne dig; thi dig og din Sæd vil jeg give alle disse Lande og stadfæste den Ed, som jeg har svoret Abraham, din Fader.',
        4: 'Og jeg vil gøre din Sæd mangfoldig som Stjernerne paa Himmelen og give din Sæd alle disse Lande, og i din Sæd skulle alle Folk paa Jorden velsignes,',
        5: 'fordi Abraham lød min Røst og bevarede det, jeg vil have bevaret, mine Bud, mine Skikke og mine Love.',
        6: 'Saa boede Isak i Gerar.',
        7: 'Og de Mænd paa samme Sted spurgte om hans Hustru; da sagde han: Hun er min Søster; thi han frygtede at sige: Hun er min Hustru, idet han tænkte, at ikke Mændene paa dette Sted maaske skulle slaa mig ihjel for Rebekkas Skyld, thi hun var dejlig af Anseelse.',
        8: 'Og det skete, der han havde boet der en Tid lang, saa Abimelek, Filisternes Konge, ud igennem Vinduet og saa, og se, Isak legede med Rebekka, sin Hustru.',
        9: 'Da kaldte Abimelek ad Isak og sagde: Visselig, se, hun er din Hustru, og hvorledes har du sagt: hun er min Søster? Og Isak sagde til ham: Thi jeg tænkte: Maaske jeg maatte slaas ihjel for hendes Skyld.',
        10: 'Da sagde Abimelek: Hvi har du gjort os dette? En af Folket kunde snart have ligget hos din Hustru, saa havde du ført Skyld over os.',
        11: 'Saa bød Abimelek alt Folket og sagde: Hvo, som rører ved denne Mand og ved hans Hustru, skal visselig dødes.',
        12: 'Og Isak saaede der i Landet og fik samme Aar hundrede Fold, og Herren velsignede ham.',
        13: 'Og Manden blev mægtig og gik frem og blev mægtig, indtil han blev saare mægtig.',
        14: 'Og han ejede Faar og ejede Kvæg og mange Tyende; derfor bare Filisterne Avind mod ham.',
        15: 'Og alle Brøndene, som hans Faders Tjenere havde gravet i Abrahams, hans Faders Tid, dem tilstoppede Filisterne og fyldte dem med Jord.',
        16: 'Og Abimelek sagde til Isak: Drag fra os; thi du er bleven os alt for mægtig.',
        17: 'Saa drog Isak derfra og slog Telt i Dalen Gerar og boede der.',
        18: 'Og Isak lod igen de Vandbrønde opgrave, som de havde gravet i Abrahams, hans Faders Tid, og som Filisterne havde tilstoppet efter Abrahams Død, og han gav dem Navne efter de Navne, som hans Fader havde kaldet dem.',
        19: 'Saa grove Isaks Tjenere i Dalen og fandt der en Brønd med levende Vande.',
        20: 'Men Hyrderne af Gerar kivedes med Isaks Hyrder og sagde: Vandet hører os til; saa kaldte han den Brønds Navn Esek, thi de kivedes med ham.',
        21: 'Saa grove de en anden Brønd, og de kivedes og om den; derfor kaldte de dens Navn Sitna.',
        22: 'Da flyttede han derfra og grov en anden Brønd, og de kivedes ikke om den, og han kaldte dens Navn Rekoboth og sagde: thi nu har Herren gjort Rum for os, og vi ere voksede i Landet.',
        23: 'Og han drog op derfra til Beersaba.',
        24: 'Og Herren aabenbaredes for ham i den samme Nat og sagde: Jeg er din Fader Abrahams Gud; frygt ikke, thi jeg er med dig og vil velsigne dig og formere din Sæd for min Tjener Abrahams Skyld.',
        25: 'Saa byggede han der et Alter og paakaldte Herrens Navn og opslog der sit Telt, og Isaks Tjenere grove der en Brønd.',
        26: 'Og Abimelek drog til ham fra Gerar med Akusat sin Ven og Pikol sin Stridshøvedsmand.',
        27: 'Da sagde Isak til dem: Hvi komme I til mig, da I dog have hadet mig og drevet mig fra Eder?',
        28: 'Og de svarede: Vi se klarligen, at Herren er med dig; derfor sagde vi: Kære, lad være en Ed imellem os, imellem os og dig, og vi ville gøre et Forbund med dig,',
        29: 'at du ikke skal gøre ondt imod os, ligesom vi ikke have rørt dig, og ligesom vi ikke have gjort dig andet end godt, og vi lode dig fare i Fred; du er nu Herrens velsignede.',
        30: 'Saa gjorde han dem et Gæstebud, og de aade og drak.',
        31: 'Og de stode tidlig op om Morgenen og tilsvore hinanden gensidig, og Isak ledsagede dem, og de droge fra ham i Fred.',
        32: 'Og det skete, paa den samme Dag kom Isaks Tjenere og forkyndte ham angaaende den Brønd, som de havde gravet, og de sagde til ham: Vi have fundet Vand.',
        33: 'Og han kaldte den Skibea, deraf er Stadens Navn Beersaba indtil denne Dag.',
        34: 'Og Esau var fyrretyve Aar gammel og tog en Hustru, Judith, Beeriden Hethiters Datter, og Basmat, Elon den Hethiters Datter.',
        35: 'Og de vare Aands Bitterhed for Isak og Rebekka.',
    },
    27: {
        1: 'Og det hændte sig, der Isak blev gammel, og hans Øjne bleve dunkle, at han ikke kunde se, da kaldte han sin ældste Søn, Esau, og sagde til ham: Min Søn! og han sagde til ham: Se, her er jeg.',
        2: 'Og han sagde: Se nu, jeg er gammel og ved ikke min Dødsdag.',
        3: 'Saa tag nu dine Redskaber, dit Kogger og din Bue, gak ud paa Marken og fang mig noget Vildt!',
        4: 'Og tilbered mig en god Ret, saasom jeg har Lyst til, og bring mig den, at jeg maa æde, paa det min Sjæl maa velsigne dig, før jeg skal dø.',
        5: 'Og Rebekka hørte, der Isak talede til Esau, sin Søn; saa gik Esau paa Marken at fange noget Vildt, at bære hjem.',
        6: 'Da sagde Rebekka til Jakob, sin Søn, sigende: Se, jeg hørte din Fader tale til Esau, din Broder, og sige:',
        7: 'Hent mig noget Vildt og tilbered mig en god Ret, at jeg kan æde, saa vil jeg velsigne dig for Herrens Ansigt, førend jeg dør.',
        8: 'Saa adlyd nu min Røst, min Søn! eftersom jeg befaler dig.',
        9: 'Gak nu til Hjorden og hent mig derfra to gode Gedekid, at jeg kan tilberede din Fader en god Ret af dem, saasom han har Lyst til.',
        10: 'Og den skal du bære til din Fader, at han skal æde deraf, paa det han skal velsigne dig, førend han dør.',
        11: 'Da sagde Jakob til Rebekka, sin Moder: Se, Esau, min Broder, er en laadden Mand, og jeg er en glat Mand.',
        12: 'Maaske min Fader føler paa mig, og jeg vil synes for ham som en Bedrager og føre Forbandelse over mig og ikke Velsignelse.',
        13: 'Da sagde hans Moder til ham: Din Forbandelse komme over mig, min Søn! lyd kun min Røst og gak, hent mig dem!',
        14: 'Da gik han og hentede og bragte sin Moder dem; saa tilberedte hans Moder en god Ret, saasom hans Fader havde Lyst til.',
        15: 'Og Rebekka tog Esaus, sin ældste Søns, kostelige Klæder, som hun havde i Huset hos sig, og lod Jakob, sin yngste Søn, iføre sig dem.',
        16: 'Men Skindene af Gedekiddene iførte hun ham om hans Hænder, og hvor han var glat paa Halsen.',
        17: 'Og hun gav ham den gode Ret og Brød, som hun havde tilberedt, i sin Søn Jakobs Haand.',
        18: 'Og han gik til sin Fader og sagde: Min Fader! og han sagde: Se, her er jeg; hvo er du, min Søn?',
        19: 'Og Jakob sagde til sin Fader: Jeg, Esau, din førstefødte, har gjort, saasom du sagde til mig; kære, staa op, sæt dig og æd af mit Vildt, paa det din Sjæl skal velsigne mig.',
        20: 'Da sagde Isak til sin Søn: Hvorledes har du saa snart fundet det, min Søn? og han sagde: Fordi Herren din Gud skikkede mig det til Hænde.',
        21: 'Da sagde Isak til Jakob: Kom dog nær hid, og jeg vil føle paa dig, min Søn! om du er min Søn Esau eller ej.',
        22: 'Og Jakob gik nær til sin Fader Isak, og han følte paa ham og sagde: Røsten er Jakobs Røst, men Hænderne ere Esaus Hænder.',
        23: 'Og han kendte ham ikke, thi hans Hænder vare laadne som Esaus, hans Broders, Hænder; og han velsignede ham.',
        24: 'Og han sagde: Du, er du denne min Søn Esau? og han sagde: Jeg er det.',
        25: 'Da sagde han: Bring mig det hid og lad mig æde af min Søns Vildt, at min Sjæl skal velsigne dig; saa bragte han ham det, og han aad, og han bragte ham Vin, og han drak.',
        26: 'Og Isak, hans Fader, sagde til ham: Kære, kom nærmere og kys mig, min Søn!',
        27: 'Og han kom nærmere og kyssede ham; og han lugtede Lugten af hans Klæder og velsignede ham og sagde: Se, min Søns Lugt er som Lugten af en Mark, hvilken Herren har velsignet.',
        28: 'Og Gud give dig af Himmelens Dug og af Jordens Fedme og meget Korn og Most.',
        29: 'Folkene skulle tjene dig, og Folkefærd skulle falde dig til Fode. Bliv en Herre over dine Brødre, og din Moders Sønner skulle falde dig til Fode; hvo som forbander dig, være forbandet, og hvo som velsigner dig, være velsignet!',
        30: 'Og det skete, der Isak var færdig med at velsigne Jakob, da Jakob lige var gaaet ud fra sin Fader Isak, at Esau, hans Broder, kom fra sin Jagt.',
        31: 'Og han tilberedte ogsaa en god Ret og bragte den ind til sin Fader og sagde til sin Fader: Min Fader staa op og æde af sin Søns Vildt, at din Sjæl skal velsigne mig.',
        32: 'Da sagde Isak, hans Fader til ham: Hvo er du? og han sagde: Jeg er din Søn, din førstefødte, Esau.',
        33: 'Da forfærdedes Isak med en overmaade stor Forfærdelse og sagde: Hvo er dog den, som fangede Vildt og frembar til mig? og jeg aad af alt, før du kom, og jeg har velsignet ham; og han skal ogsaa være velsignet.',
        34: 'Der Esau hørte sin Faders Tale, da skreg han med et stort og overmaade bittert Skrig og sagde til sin Fader: Velsign mig, ogsaa mig, min Fader!',
        35: 'Og han sagde: Din Broder kom med List og tog din Velsignelse.',
        36: 'Da sagde han: Mon man derfor har kaldet hans Navn Jakob, fordi han nu har to Gange bedraget mig? min Førstefødselsret har han taget, og se, nu tog han min Velsignelse; og han sagde: Har du ikke bevaret mig en Velsignelse?',
        37: 'Og Isak svarede og sagde til Esau: Se, jeg har sat ham til en Herre over dig og gjort alle hans Brødre til hans Tjenere og forsørget ham med Korn og Most, hvad skal jeg da gøre ved dig, min Søn?',
        38: 'Og Esau sagde til sin Fader: Har du ikke uden denne ene Velsignelse, min Fader? velsign mig, ogsaa mig, min Fader! og Esau opløftede sin Røst og græd.',
        39: 'Da svarede Isak, hans Fader, og sagde til ham: Se, din Bolig skal være uden Jordens Fedme og uden Himmelens Dug fra oven ned.',
        40: 'Og ved dit Sværd skal du leve og tjene din Broder, og det skal ske, naar du bliver ustyrlig, da skal du bryde hans Aag af din Hals.',
        41: 'Og Esau var Jakob hadsk for den Velsignelses Skyld, som hans Fader havde velsignet ham med, og Esau sagde i sit Hjerte: Det kommer snart, at vi skulle sørge for min Fader, da vil jeg slaa Jakob, min Broder, ihjel.',
        42: 'Og Esaus, hendes ældste Søns, Ord bleve Rebekka tilkendegivne; og hun sendte hen og lod Jakob, sin yngste Søn, kalde, og sagde til ham: Se, Esau, din Broder, vil trøste sig med at slaa dig ihjel.',
        43: 'Og nu, min Søn, hør min Røst og staa op, fly til Laban, min Broder, i Karan,',
        44: 'og bliv hos ham nogen Tid, indtil din Broders Hidsighed lægger sig,',
        45: 'indtil din Broders Vrede vender sig fra dig, og han glemmer det, du har gjort ham, saa vil jeg sende Bud og hente dig derfra; hvi skulde jeg dog berøves eder begge paa en Dag?',
        46: 'Og Rebekka sagde til Isak: Jeg kedes ved at leve for Heths Døtres Skyld; dersom Jakob tog en Hustru af Heths Døtre, som disse af dette Lands Døtre, hvad skulde jeg da leve for?',
    },
    28: {
        1: 'Og Isak kaldte ad Jakob og velsignede ham og bød ham og sagde til ham: Du skal ikke tage en Hustru af Kanaans Døtre;',
        2: 'staa op, gak til Paddan-Aram til Bethuel din Morfaders Hus, og tag dig derfra en Hustru af Laban din Morbroders Døtre.',
        3: 'Og den almægtige Gud velsigne dig og gøre dig frugtbar og formere dig, at du maa blive til en Hob af Folk.',
        4: 'Og han give dig Abrahams Velsignelse, dig: og din Sæd med dig, at du kan arve det Land, hvori du er fremmed, hvilket Gud gav Abraham.',
        5: 'Saa sendte Isak Jakob hen, og han drog til Paddan-Aram til Laban, Bethuel den Syrers Søn, en Broder til Rebekka, Jakobs og Esaus Moder.',
        6: 'Og Esau saa, at Isak havde velsignet Jakob og sendt ham til Paddan-Aram at tage sig derfra en Hustru og havde, der han velsignede ham, budet ham og sagt: Du skal ikke tage en Hustru af Kanaans Døtre.',
        7: 'Og Jakob var sin Fader og sin Moder lydig og drog til Paddan-Aram.',
        8: 'Og Esau saa, at Kanaans Døtre ikke behagede Isak hans Fader.',
        9: 'Saa gik Esau til Ismael og tog sig til Hustru Makalath, en Datter af Ismael, Abrahams Søn, en Søster til Nebajoth, foruden sine andre Hustruer.',
        10: 'Og Jakob drog ud fra Beersaba og gik til Karan.',
        11: 'Og han kom til et Sted og blev der om Natten, thi Solen var nedgangen, og han tog af Stenene paa det Sted og lagde under sit Hoved og lagde sig paa det samme Sted.',
        12: 'Og han drømte, og se, en Stige var oprejst paa Jorden, og det øverste deraf naaede til Himmelen, og se, Guds Engle stege op og ned ad den.',
        13: 'Og se, Herren stod oven over den og sagde: Jeg er Herren, din Fader Abrahams Gud og Isaks Gud; det Land, som du ligger paa, det vil jeg give dig og din Sæd.',
        14: 'Og din Sæd skal blive som Støv paa Jorden, og du skal udbredes mod Vesten og mod Østen og mod Norden og mod Sønden; og i dig og i din Sæd skulle alle Slægter paa Jorden velsignes.',
        15: 'Og se, jeg er med dig og vil bevare dig overalt, hvor du drager hen, og jeg vil føre dig til dette Land igen; thi jeg vil ikke forlade dig, før jeg har fuldkommet det, jeg har sagt dig.',
        16: 'Og Jakob vaagnede af sin Søvn og sagde: Sandelig, Herren er paa dette Sted, og jeg vidste det ikke.',
        17: 'Og han frygtede og sagde: hvor forfærdeligt er dette Sted! dette er ikke andet end Guds Hus, og dette er Himmelens Port.',
        18: 'Og Jakob stod aarle op om Morgenen og tog den Sten, som han havde lagt under sit Hoved, og oprejste den til en Mindesten og øste Olie oven paa den.',
        19: 'Og han kaldte det samme Steds Navn Bethel, men ellers var Lus Stadens Navn fra Begyndelsen.',
        20: 'Og Jakob gjorde et Løfte og sagde: Dersom Gud vil være med mig og beskærme mig paa denne Vej, som jeg rejser, og give mig Brød at æde og Klæder at iføre mig,',
        21: 'og jeg kommer igen til min Faders Hus med Fred, og Herren vil være mig en Gud,',
        22: 'da skal denne Sten, som jeg har oprejst til en Mindesten, være et Guds Hus, og jeg vil visselig give dig Tiende af alt det, du giver mig.',
    },
    29: {
        1: 'Og Jakob løftede sine Fødder og gik til det Folks Land i Østen.',
        2: 'Og han saa og se, der var en Brønd paa Marken, og se, der vare tre Faarehjorde, som laa ved den; thi man skulde vande Hjorden af den samme Brønd, og Stenen over Hullet paa Brønden var stor.',
        3: 'Og derhen skulde alle Hjordene sankes, og Stenen væltes fra Hullet paa Brønden, og Faarene vandes, og Stenen igen lægges over Hullet paa Brønden, paa sit Sted.',
        4: 'Og Jakob sagde til dem: Mine Brødre, hvorfra ere I? og de sagde: Fra Karan ere vi.',
        5: 'Og han sagde til dem: Kende I Laban, Nakors Søn? og de sagde: Vi kende ham.',
        6: 'Og han sagde til dem: Gaar det ham vel? og de sagde: Vel! og se, Rakel, hans Datter, kommer med Faarene.',
        7: 'Da sagde han: Se, det er endnu højt paa Dagen, det er ikke Tid, at Kvæget samles; vander Faarene og gaar, vogter dem!',
        8: 'Og de sagde: Vi kunne ikke, førend alle Hjordene sankes, og man vælter Stenen fra Hullet paa Brønden, og da vande vi Faarene.',
        9: 'Medens han endnu talede med dem, da kom Rakel med Faarene, som vare hendes Faders; thi hun vogtede.',
        10: 'Og det skete, der Jakob saa Rakel, sin Morbroder Labans Datter, og Labans, sin Morbroders, Faar, da gik Jakob til og væltede Stenen fra Hullet paa Brønden og vandede Labans, sin Morbroders, Faar.',
        11: 'Og Jakob kyssede Rakel og opløftede sin Røst og græd.',
        12: 'Og Jakob sagde Rakel, at han var hendes Faders Broder, og at han var Rebekkas Søn; saa løb hun og forkyndte sin Fader det.',
        13: 'Og det skete, der Laban hørte den Tidende om Jakob, sin Søstersøn, da løb han mod ham og tog ham i Favn og kyssede ham og ledte ham ind i sit Hus; da fortalte han Laban alle disse Ting.',
        14: 'Da sagde Laban til ham: Sandelig, du er mit Ben og mit Kød; og han blev hos ham en Maanedstid.',
        15: 'Og Laban sagde til Jakob: Fordi du er min Broder, skulde du derfor tjene mig for intet? sig mig, hvad din Løn skal være.',
        16: 'Og Laban havde to Døtre: Den ældstes Navn var Lea, og den yngstes Navn Rakel.',
        17: 'Og Lea havde svage Øjne; men Rakel var dejlig af Skikkelse og dejlig af Anseelse.',
        18: 'Og Jakob elskede Rakel og sagde: Jeg vil tjene dig syv Aar for Rakel, din yngste Datter.',
        19: 'Og Laban sagde: Det er bedre, at jeg giver hende til dig, end at jeg giver hende til en anden Mand, bliv hos mig!',
        20: 'Saa tjente Jakob for Rakel syv Aar, og de syntes ham at være faa Dage, fordi han havde Kærlighed til hende.',
        21: 'Og Jakob sagde til Laban: Giv mig min Hustru; thi min Tid er fuldkommet, og jeg vil gaa ind til hende.',
        22: 'Saa bød Laban alle Mænd paa det Sted tilsammen og gjorde et Gæstebud.',
        23: 'Og det skete om Aftenen, at han tog Lea sin Datter og ledte hende ind til ham, og han gik ind til hende.',
        24: 'Og Laban gav hende Silpa, sin Tjenestepige, til Pige for Lea, sin Datter.',
        25: 'Og det skete om Morgenen, se, da var det Lea; og han sagde til Laban: Hvi gjorde du dette imod mig? har jeg ej tjent hos dig for Rakel? og hvi har du bedraget mig?',
        26: 'Og Laban sagde: Det sker ikke saaledes paa vort Sted, at man giver den yngste bort før den førstefødte.',
        27: 'Hold dennes Uge ud, saa ville vi ogsaa give dig denne for den Tjeneste, som du skal tjene hos mig endnu syv andre Aar.',
        28: 'Og Jakob gjorde saa og holdt dennes Uge ud; saa gav han ham Rakel, sin Datter, til hans Hustru.',
        29: 'Og Laban gav sin Datter Rakel Bilha, sin Tjenestepige, til Tjenestepige for hende.',
        30: 'Saa gik han og ind til Rakel, og elskede Rakel mere end Lea; og han tjente hos ham endnu syr andre Aar.',
        31: 'Der Herren saa, at Lea var foragtet, da aabnede han hendes Moderliv; men Rakel var ufrugtbar.',
        32: 'Og Lea undfik og fødte en Søn, og hun kaldte hans Navn Ruben; thi hun sagde: Herren har set paa min Elendighed; thi nu skal min Mand elske mig.',
        33: 'Og hun undfik igen og fødte en Søn og sagde: Fordi Herren har hørt, at jeg var forsmaaet, da har han givet mig ogsaa denne; saa kaldte hun hans Navn Simeon.',
        34: 'Og hun undfik igen og fødte en Søn og sagde: Nu denne Sinde skal min Mand holde sig til mig, thi jeg har født ham tre Sønner; derfor kaldte man hans Navn Levi.',
        35: 'Og hun undfik igen og fødte en Søn og sagde: Denne Sinde vil jeg prise Herren; derfor kaldte hun hans Navn Juda; saa holdt hun op at føde.',
    },
    30: {
        1: 'Og Rakel saa, at hun ikke fødte Jakob Børn; da bar Rakel Avind mod sin Søster og sagde til Jakob: Fly mig Børn! og hvis ikke, da dør jeg.',
        2: 'Og Jakob blev saare vred paa Rakel og sagde: Mon jeg være i Guds Sted, som formener dig Livsens Frugt?',
        3: 'Da sagde hun: Se, der er min Tjenestepige Bilha, gak ind til hende, at hun maa føde over mine Knæ, at ogsaa jeg maa bygges op ved hende.',
        4: 'Saa gav hun ham Bilha, sin Pige, til Hustru, og Jakob gik ind til hende.',
        5: 'Og Bilha undfik og fødte Jakob en Søn.',
        6: 'Da sagde Rakel: Gud har dømt mig og hørt ogsaa min Røst og givet mig en Søn; derfor kaldte hun hans Navn Dan.',
        7: 'Og Bilha, Rakels Pige, undfik igen og fødte Jakob den anden Søn.',
        8: 'Da sagde Rakel: Jeg har kæmpet Guds Kampe med min Søster, jeg har og faaet Overhaand; og hun kaldte hans Navn Naftali.',
        9: 'Og Lea saa, at hun havde holdt op at føde, og hun tog Silpa, sin Pige, og gav Jakob hende til Hustru.',
        10: 'Og Silpa, Leas Tjenestepige, fødte Jakob en Søn.',
        11: 'Da sagde Lea: Til Lykke! og hun kaldte hans Navn Gad.',
        12: 'Og Silpa, Leas Tjenestepige, fødte Jakob en anden Søn.',
        13: 'Da sagde Lea: Held mig! thi Døtre prise mig lykkelig; og hun kaldte hans Navn Aser.',
        14: 'Og Ruben gik i de Dage, man høstede Hvede, og fandt Dudaim paa Marken og bar dem til Lea, sin Moder; da sagde Rakel til Lea: Kære, giv mig af din Søns Dudaim!',
        15: 'Og hun sagde til hende: Er det en ringe Ting, at du har taget min Mand, og du tager ogsaa min Søns Dudaim? Og Rakel sagde: Derfor maa han ligge hos dig i denne Nat, for din Søns Dudaim.',
        16: 'Der Jakob kom af Marken om Aftenen, da gik Lea ud imod ham og sagde: Til mig skal du komme ind; thi jeg har tinget dig for min Søns Dudaim; saa laa han hos hende den samme Nat.',
        17: 'Og Gud hørte Lea, og hun undfik og fødte Jakob den femte Søn.',
        18: 'Og Lea sagde: Gud har givet mig min Løn, fordi jeg gav min Mand min Tjenestepige; og hun kaldte hans Navn Isaskar.',
        19: 'Og Lea undfik igen og fødte Jakob den sjette Søn.',
        20: 'Og Lea sagde: Gud har givet mig, ja mig en god Gave; nu vil min Mand bo hos mig, thi jeg har født ham seks Sønner; og hun kaldte hans Navn Sebulon.',
        21: 'Og siden fødte hun en Datter og kaldte hendes Navn Dina.',
        22: 'Og Gud ihukom Rakel, og Gud hørte hende og aabnede hendes Moderliv.',
        23: 'Og hun undfik og fødte en Søn og sagde: Gud har borttaget min Forsmædelse.',
        24: 'Saa kaldte hun hans Navn Josef og sagde: Herren give mig endnu en anden Søn!',
        25: 'Og det skete, der Rakel havde født Josef, da sagde Jakob til Laban: Lad mig fare, og jeg vil gaa til mit Sted og til mit Land.',
        26: 'Giv mig mine Hustruer og mine Børn, for hvilke jeg har tjent dig, og jeg vil vandre bort; thi du kender min Tjeneste, hvorledes jeg har tjent dig.',
        27: 'Da sagde Laban til ham: Kære, maatte jeg have fundet Naade for dine Øjne! jeg har en Anelse om, at Herren har velsignet mig for din Skyld.',
        28: 'Og han sagde: Nævn din Løn for mig, og den vil jeg give dig.',
        29: 'Og han sagde til ham: Du ved selv, hvormed jeg har tjent dig, og hvad dit Kvæg er blevet til hos mig.',
        30: 'Thi det, som du havde, før jeg kom, var lidet; men nu har det udbredt sig mangfoldigt, og Herren har velsignet dig ved min Fod; og nu, naar skal jeg ogsaa gøre noget for mit eget Hus?',
        31: 'Og han sagde: Hvad skal jeg give dig? Og Jakob sagde: Du skal ikke give mig noget; dersom du vil gøre mig dette, saa vil jeg fremdeles røgte og vogte dine Faar.',
        32: 'Jeg vil i Dag gaa igennem al din Hjord og skille derfra hvert spættet og spraglet Stykke, hvert sort Stykke iblandt Faarene, og hvad der er spraglet og spættet iblandt Gederne; og dette skal være min Løn.',
        33: 'Saa skal min Retfærdighed svare for mig den Dag i Morgen, naar du kommer at bese min Løn; hvad som ikke er spættet eller spraglet iblandt Gederne og sort iblandt Lammene, det skal agtes for stjaalet hos mig.',
        34: 'Da sagde Laban: Se, gid det maa være, som du har sagt!',
        35: 'Og samme Dag skilte han de brogede og spraglede Bukke og alle spættede og spraglede Geder, alt det, som havde noget hvidt paa sig, og alt sort iblandt Faarene, og han gav det i sine Børns Hænder.',
        36: 'Og han gjorde tre Dages Rejse imellem sig og Jakob, og Jakob vogtede Labans øvrige Hjorde.',
        37: 'Og Jakob tog sig Kæppe af grønt Poppeltræ og Hassel og Kastanie og udskavede hvide Streger paa dem, saa det hvide blev bart, som var paa Kæppene.',
        38: 'Og han lagde Kæppene, som han havde udskavet, i Renderne, i Vandtrugene, hvor Faarene skulde komme at drikke, ret lige for Faarene, og disse parredes, naar de kom for at drikke.',
        39: 'Og Faarene parredes ved Kæppene, og Faarene fødte brogede, spættede og spraglede.',
        40: 'Saa lod Jakob Lammene skille fra og stillede Faarenes Ansigter overfor det brogede og alt det sorte iblandt Labans Hjord og gjorde sig Hjorde for sig selv alene, og dem lod han ikke komme til Labans Hjord.',
        41: 'Og det skete altid, naar de stærkere Faar løb, da lagde Jakob Kæppene for Faarenes Øjne i Renderne, at de skulde parre sig ved Kæppene.',
        42: 'Men naar Faarene vare svage, lagde han dem ikke; saa bleve de svage Labans og de stærke Jakobs.',
        43: 'Deraf blev Manden overmaade rig, saa at han havde mange Faar og Piger og Svende og Kameler og Asener.',
    },
    31: {
        1: 'Og han hørte Labans Sønners Ord, som sagde: Jakob har taget alt, hvad vor Faders var, og af vor Faders har han faaet al den ne Rigdom.',
        2: 'Og Jakob saa Labans Ansigt, og se, det var ikke imod ham som tilforn.',
        3: 'Da sagde Herren til Jakob: Drag tilbage til dine Fædres Land og til din Slægt, og jeg vil være med dig.',
        4: 'Da sendte Jakob og lod Rakel og Lea kalde ud paa Marken til sit Kvæg.',
        5: 'Og han sagde til dem: Jeg ser eders Faders Ansigt, at det ikke er imod mig som tilforn; men min Faders Gud har været med mig.',
        6: 'Og I vide selv, at jeg har tjent eders Fader af al min Magt.',
        7: 'Og eders Fader har bedraget mig og forandret min Løn ti Gange; men Gud har ikke tilstedet ham at gøre mig ondt.',
        8: 'Naar han sagde saaledes: De spættede skulle være din Løn, da fødte alt Kvæget spættede; og naar han sagde saaledes: De brogede skulle være din Løn, da fødte alt Kvæget brogede;',
        9: 'og Gud har borttaget eders Faders Kvæg og givet mig.',
        10: 'Og det skete, naar Tiden kom, at Kvæget skulde løbe, løftede jeg mine Øjne op og saa i Drømme, og se, Bukkene, som sprang Kvæget, vare brogede, spættede og haglede;',
        11: 'og den Guds Engel sagde til mig i Drømme: Jakob! og jeg svarede: Se, her er jeg.',
        12: 'Og han sagde: Opløft nu dine Øjne, og se, alle Bukkene, som springe Kvæget, ere brogede, spættede og haglede; thi jeg har set alt det, Laban gør dig.',
        13: 'Jeg er den Gud fra Bethel, hvor du salvede en Mindesten, hvor du gjorde mig Løfte; gør dig nu rede, far ud af dette Land og vend tilbage til din Slægts Land.',
        14: 'Da svarede Rakel og Lea og sagde til ham: Have vi endnu Del og Arv i vor Faders Hus?',
        15: 'Ere vi ikke regnede for ham som fremmede? thi han har solgt os, ja endogsaa aldeles fortæret, hvad han fik for os.',
        16: 'Derfor al den Rigdom, som Gud har borttaget fra vor Fader, den hører os og vore Børn til, og nu, gør alt det, som Gud har sagt til dig.',
        17: 'Saa gjorde Jakob sig rede og satte sine Børn og sine Hustruer paa Kamelerne',
        18: 'og bortførte alt sit Kvæg og al sin Formue, som han havde forhvervet, det Kvæg, han ejede, som han havde forhvervet i Paddan-Aram, for at komme til Isak sin Fader i Kannans Land.',
        19: 'Og Laban var gaaet hen at klippe sine Faar, og Rakel stjal sin Faders Husguder.',
        20: 'Jakob stjal Laban den Syrers Hjerte, idet han ikke gav ham til Kende, at han flyede.',
        21: 'Og han flyede med alt det, han havde, og gjorde sig rede og satte over Floden og vendte sit Ansigt mod Bjerget Gilead.',
        22: 'Og paa den tredje Dag blev det Laban tilkendegivet, at Jakob flyede.',
        23: 'Saa tog han sine Brøde med sig og forfulgte ham syv Dages Rejse og naaede ham paa Bjerget Gilead.',
        24: 'Men Gud kom til Laban den Syrer i en Drøm om Natten og sagde til ham: Forvar dig, at du ej taler med Jakob enten godt eller ondt.',
        25: 'Og Laban naaede Jakob, og Jakob havde slaaet sit Telt op paa Bjerget, og Laban med sine Brødre slog Telt paa Bjerget Gilead.',
        26: 'Da sagde Laban til Jakob: Hvad har du gjort, at du har stjaalet mit Hjerte og bortført mine Døtre, som var de fangne med Sværd?',
        27: 'Hvi flyede du hemmeligen og har stjaalet dig fra mig og ikke givet mig det til Kende, og jeg vilde have bortsendt dig med Glæde og med Sange, med Tromme og med Citer?',
        28: 'Og du har ikke ladet mig kysse mine Sønner og mine Døtre? nu, du har gjort daarligen.',
        29: 'Jeg havde vel Magt i min Haand at gøre ondt ved eder; men eders Faders Gud talede til mig i Gaar Nat, sigende: Forvar dig at tale med Jakob enten godt eller ondt.',
        30: 'Og nu, da du endeligen vilde vandre, efterdi du længtes saare efter din Faders Hus, hvi har du stjaalet mine Guder?',
        31: 'Og Jakob svarede og sagde til Laban: Fordi jeg frygtede; thi jeg tænkte, du maatte rive dine Døtre fra mig;',
        32: 'men den, hos hvem du finder dine Guder, skal ikke leve. Vedkend dig for vore Brødre det hos mig, som tilhører dig, og tag dig det; men Jakob vidste ikke, at Rakel havde stjaalet dem.',
        33: 'Da gik Laban ind i Jakobs Telt og i Leas Telt og i begge Tjenestekvindernes Telt og fandt dem ikke; saa gik han ud af Leas Telt og kom i Rakels Telt.',
        34: 'Men Rakel havde taget Husguderne og lagt dem i en Kamelsaddel og sad paa dem, og Laban ransagede hele Teltet og fandt intet.',
        35: 'Da sagde hun til sin Fader: Min Herre, bliv ikke vred, at jeg ikke kan staa op for dig, fordi det gaar mig paa Kvinders Vis; saa ledte han og fandt ikke Husguderne.',
        36: 'Da blev Jakob vred og trættede med Laban; og Jakob svarede og sagde til Laban: Hvad er min Overtrædelse, hvad er min Synd, at du forfølger mig saaledes?',
        37: "Eftersom du har følt og ransaget alt mit Tøj, hvad har du fundet af alt dit Hus's Tøj? læg det her frem for mine Brødre og dine Brødre, at de maa dømme imellem os to!",
        38: 'Jeg har været hos dig disse tyve Aar, dine Faar og dine Geder have ikke født i Utide, og Vædrene af dit Kvæg har jeg ikke ædet.',
        39: 'Hvad som var revet, har jeg ikke baaret til dig; jeg betalte det, du krævede det af min Haand, det, som var stjaalet om Dagen, og det, som var stjaalet om Natten.',
        40: 'Saa gik det mig: om Dagen fortærede Heden mig og Kulden om Natten, og der kom ikke Søvn i mine Øjne.',
        41: 'Det er nu tyve Aar, jeg er i dit Hus, jeg har tjent dig fjorten Aar for dine tvende Døtre og seks Aar for dit Kvæg, og du har forandret min Løn ti Gange.',
        42: 'Dersom ikke min Faders Gud, Abrahams Gud og Isaks Rædsel, havde været med mig, sandelig, du havde nu ladet mig fare tomhændet; Gud har set min Elendighed og mine Hænders Møje og straffede dig i Gaar Nat.',
        43: 'Og Laban svarede og sagde til Jakob: De Døtre ere mine Døtre, og de Sønner ere mine Sønner, og det Kvæg er mit Kvæg, og alt det, du ser, er mit; hvad skulde jeg gøre imod disse mine Døtre i Dag eller imod deres Sønner, som de have født?',
        44: 'Saa kom nu, lad os gøre en Pagt, jeg og du, og det skal være til et Vidne imellem mig og imellem dig.',
        45: 'Da tog Jakob en Sten og rejste den op til et Mindesmærke.',
        46: 'Og Jakob sagde til sine Brødre: Sanker Stene; og de toge Stene og gjorde en Hob, og de aade der paa Hoben.',
        47: 'Og Laban kaldte den Jegar Sahaduta, men Jakob kaldte den Gilead.',
        48: 'Da sagde Laban: Denne Hob skal være et Vidne i Dag imellem mig og imellem dig; derfor kaldte han dens Navn Gilead,',
        49: 'og Mizpa; thi han sagde: Herren skal se til imellem mig og imellem dig; thi vi komme hverandre af Syne.',
        50: 'Dersom du vil gøre mine Døtre Fortræd, og dersom du vil tage Hustruer foruden mine Døtre, da er her vel ingen Mand hos os; men se, Gud er Vidne imellem mig og imellem dig.',
        51: 'Og Laban sagde til Jakob: Se denne Hob, og se det Mindesmærke, som jeg har oprejst imellem mig og imellem dig,',
        52: 'denne Hob skal være Vidne, og dette Mindesmærke skal være Vidne, at jeg skal ikke fare forbi denne Hob til dig, og at du skal ikke fare forbi denne Hob og dette Mindesmærke til mig, til det onde.',
        53: 'Abrahams Gud og Nakors Gud, deres Faders Gud, skal dømme imellem os; og Jakob svor ved sin Fader Isaks Rædsel.',
        54: 'Og Jakob slagtede et Offer paa Bjerget og bad sine Brødre til Maaltid; og de aade Brød og bleve paa Bjerget om Natten.',
        55: 'Men om Morgenen stod Laban aarle op og kyssede sine Sønner og sine Døtre og velsignede dem, og Laban drog hen og vendte tilbage til sit Sted.',
    },
    32: {
        1: 'Og Jakob drog sin Vej, og Guds Engle mødte ham.',
        2: 'Og der Jakob saa dem, sagde han: Denne er Guds Hær; og han kaldte det samme Steds Navn Makanaim.',
        3: 'Og Jakob sendte Bud for sig til Esau sin Broder, til det Land Sejr, paa Edoms Mark.',
        4: 'Og han befalede dem og sagde: Saa skulle I sige til min Herre, til Esau: Saa siger din Tjener Jakob: Jeg har været fremmed hos Laban og dvælet der indtil nu.',
        5: 'Og jeg har Øksne og Asener, Kvæg og Svende og Tjenestepiger, og jeg har udsendt Bud, at give min Herre det til Kende for at finde Naade for dine Øjne.',
        6: 'Og Budene kom igen til Jakob og sagde: Vi kom til din Broder, til Esau; og han drager ogsaa imod dig, og fire Hundrede Mand med ham.',
        7: 'Da frygtede Jakob saare og blev bange; saa delte han Folket, som var hos ham, og Kvæget og Øksnene og Kamelerne i to Hære.',
        8: 'Og han sagde: Dersom Esau skulde komme til den ene Hær og slaar den, da kan den Hær, som bliver tilovers, undkomme.',
        9: 'Og Jakob sagde: Min Fader Abrahams Gud og min Fader Isaks Gud, Herre, du, som sagde til mig: Drag igen til dit Land og til din Slægt, og jeg vil gøre vel imod dig;',
        10: 'jeg er ringere end al den Miskundhed og al den Trofasthed, som du har bevist mod din Tjener; thi med min Stav gik jeg over denne Jordan, og nu er jeg vorden til to Hære.',
        11: 'Kære, udfri mig af min Broders Haand, af Esaus Haand; thi jeg frygter for ham, at han skal komme og slaa mig, ja Moderen med Børnene.',
        12: 'Og du har sagt: Jeg vil gøre meget vel imod dig og gøre din Sæd som Sand ved Havet, hvilket ikke kan tælles for Mangfoldighed.',
        13: 'Saa blev han der samme Nat og tog af det, han havde under sin Haand, til en Skænk for sin Broder Esau;',
        14: 'to Hundrede Geder og tyve Bukke, to Hundrede Faar og tyve Vædre,',
        15: 'Kameler, som gave at die, og deres Føl tredive, Køer fyrretyve, og Øksen ti, Aseninder tyve, og ti Føl.',
        16: 'Og han gav dem under sine Tjeneres Haand, hver Hjord for sig, og sagde til sine Tjenere: Gaar foran mig og gører Rum imellem hver Hjord!',
        17: 'Saa befalede han den første og sagde: Naar Esau, min Broder, møder dig og spørger dig og siger: Hvem hører du til, og hvor vil du rejse hen? og hvem høre disse til, som du driver for dig?',
        18: 'da skal du sige: Din Tjener Jakob; det er en Skænk, sendt til min Herre, til Esau, og se, han kommer ogsaa selv efter os.',
        19: 'Og han befalede den anden ligesaa og den tredje og alle dem, som gik efter Hjordene, og sagde: Paa denne Maade skulle I sige til Esau, naar I møde ham.',
        20: 'Og I skulle sige: Se, ogsaa din Tjener Jakob er bag os; thi han tænkte: Jeg vil forsone hans Ansigt med den Skænk, som gaar for mig, og siden se hans Ansigt, kanske han antager min Person.',
        21: 'Saa gik den Skænk foran ham; men han blev selv samme Nat ved Hæren.',
        22: 'Og han stod op i samme Nat og tog sine to Hustruer og sine to Tjenestekvinder og sine elleve Børn og gik over Vadestedet Jabok.',
        23: 'Og han tog dem og lod dem drage over Bækken og førte over, hvad han havde.',
        24: 'Og Jakob blev tilbage for sig selv alene; og der brødes en Mand med ham, indtil det dagedes.',
        25: 'Og der han saa, at han ikke kunde overvinde ham, da rørte han ved hans Hofteskaal, og Jakobs Hofteskaal gik af Led, idet han brødes med ham.',
        26: 'Og han sagde: Lad mig gaa, thi det dages; og han sagde: Jeg vil ikke lade dig gaa, uden du har velsignet mig.',
        27: 'Og han sagde til ham: Hvad er dit Navn? og han sagde: Jakob.',
        28: 'Og han sagde: Dit Navn skal ikke fremdeles kaldes Jakob, men Israel; thi du har kæmpet med Gud og med Mennesker og faaet Overhaand.',
        29: 'Og Jakob spurgte og sagde: Kære, kundgør mig dit Navn; og han sagde: Hvi spørger du dog om mit Navn? og han velsignede ham der.',
        30: 'Og Jakob kaldte Stedets Navn Pnuel; thi, sagde han, jeg har set Gud Ansigt til Ansigt, og min Sjæl er frelst.',
        31: 'Og der han kom forbi Pnuel, gik Solen op for ham, og han haltede paa sin Hofte.',
        32: 'Derfor æde Israels Børn ikke den Spændesene, som er paa Hofteskaalen, indtil denne Dag; thi han rørte Jakobs Hofteskaal paa Spændesenen.',
    },
    33: {
        1: 'Og Jakob opløftede sine Øjne og saa, og se, Esau kom, og fire Hundrede Mand med ham, og han fordelte Børnene til Lea og til Rakel og til begge Tjenestekvinderne.',
        2: 'Og han satte Tjenestekvinderne og deres Børn først og Lea og hendes Børn derefter og Rakel og Josef bagest.',
        3: 'Og han gik selv frem foran dem og bøjede sig til Jorden syv Gange, indtil han kom til sin Broder.',
        4: 'Og Esau løb mod ham og tog ham i Favn og faldt om hans Hals og kyssede ham, og de græd.',
        5: 'Og han opløftede sine Øjne og saa Kvinderne og Børnene og sagde: Hvo ere disse, som ere med dig? og han sagde: Det er de Børn, som Gud har skænket din Tjener.',
        6: 'Saa gik Tjenestekvinderne frem og deres Børn og nejede.',
        7: 'Og Lea gik ogsaa frem og hendes Børn og nejede, og derefter kom Josef og Rakel frem og nejede.',
        8: 'Og han sagde: Hvad vil du med al denne Hær, som jeg mødte? og han sagde: For at jeg maa finde Naade for min Herres Øjne.',
        9: 'Og Esau sagde: Jeg har meget, min Broder! behold du, hvad dit er.',
        10: 'Og Jakob sagde: Nej, kære, dersom jeg nu har fundet Naade for dig, da annam min Skænk af min Haand; thi derfor saa jeg dit Ansigt, som naar man kunde se Guds Ansigt, og du var mig naadig.',
        11: 'Kære, tag min Velsignelse, som er bragt til dig; thi Gud skænkede mig den, og jeg har alt dette; saa nødte han ham, og han tog det.',
        12: 'Og han sagde: Lad os drage frem og vandre, og jeg vil vandre videre med dig.',
        13: 'Og han sagde til ham: Min Herre ved, at Børnene ere svage, og her er Kvæg og nybære Køer med mig, og overdrev man dem en Dag, da døde alt Kvæget.',
        14: 'Min Herre rejse nu frem for sin Tjeners Aasyn, og jeg vil drive saa sagteligen, efter som Hjorden, der er for mig, kan gaa, og Børnene kunne gaa, indtil jeg kommer til min Herre, til Sejr.',
        15: 'Og Esau sagde: Kære, jeg vil lade nogle af det Folk, som er med mig, blive hos dig; og han sagde: Hvortil det? lad mig finde Naade for min Herres Øjne.',
        16: 'Saa drog Esau samme Dag tilbage ad sin Vej til Sejr.',
        17: 'Og Ja kob drog til Sukoth og byggede sig et Hus og gjorde Hytter til sit Kvæg; derfor kaldte han Stedets Navn Sukoth.',
        18: 'Og Jakob kom lykkeligt den Stad Sikem, som er i det Land Kanaan, der han kom fra Paddan-Aram, og han slog Lejr foran Staden.',
        19: 'Og han købte det Stykke Ager, paa hvilket han havde slaget Telt op, af Hemors, Sikems Faders, Sønner, for hundrede Penninge.',
        20: 'Og han oprejste der et Alter og kaldte det: Gud er Israels Gud.',
    },
    34: {
        1: 'Og Dina, Leas Datter, som hun havde født Jakob, gik ud for at se paa Landets Døtre.',
        2: 'Og Sikem, Landsherren Hemor den Heviters Søn, saa hende, og han tog hende og laa hos hende og krænkede hende.',
        3: 'Og hans Hjerte hængte ved Dina, Jakobs Datter, og han havde Pigen kær og talede kærligen med Pigen.',
        4: 'Og Sikem talede til sin Fader, Hemor, og sagde: Tag mig denne Pige til Hustru!',
        5: 'Og Jakob havde hørt, at han havde skændet Dina, hans Datter, og hans Sønner vare med hans Kvæg paa Marken, og Jakob tav, indtil de kom.',
        6: 'Og Hemor, Sikems Fader, gik ud til Jakob at tale med ham.',
        7: 'Og Jakobs Sønner kom fra Marken, der de hørte det, og Mændene forbitredes og bleve saare vrede; thi han havde gjort en Daarlighed mod Israel ved at ligge hos Jakobs Datter, og saaledes burde det ikke ske.',
        8: 'Da talede Hemor med dem og sagde: Min Søn Sikems Hjerte har Lyst til eders Datter; kære, giver ham hende til Hustru,',
        9: 'og gører Svogerskab med os; giver os eders Døtre, og tager eder vore Døtre!',
        10: 'Og I skulle bo hos os, og Landet skal være for eders Aasyn, bor og handler deri, tager eder Ejendom i det!',
        11: 'Og Sikem sagde til hendes Fader og til hendes Brødre: Lad mig finde Naade for eders Øjne, og jeg vil give, hvad I ville sige til mig.',
        12: 'Begærer saare meget af mig til Morgengave og Skænk, og jeg vil give, efter som I sige mig, men giver mig Pigen til Hustru!',
        13: 'Da svarede Jakobs Sønner Sikem og hans Fader Hemor svigagtigen og talede med dem, fordi han havde skændet Dina, deres Søster,',
        14: 'og de sagde til dem: Vi kunne ikke gøre denne Gerning, at give vor Søster til en Mand, som har Forhud; thi det er en Forsmædelse for os.',
        15: 'Dog ville vi være eder til Villie i dette, dersom I ville blive som vi, saa I lade alt Mandkøn hos eder omskære.',
        16: 'Og vi ville give eder vore Døtre og tage os eders Døtre og bo hos eder, og vi ville være eet Folk.',
        17: 'Men dersom I ikke ville høre os i at lade eder omskære, da ville vi tage vor Datter og drage bort.',
        18: 'Og deres Tale behagede Hemor og Sikem, Hemors Søn.',
        19: 'Og den unge Karl tøvede ikke med at gøre denne Gerning; thi han havde Lyst til Jakobs Datter, og han var æret fremfor hele sin Faders Hus.',
        20: 'Saa kom Hemor og Sikem, hans Søn, til deres Stads Port og talede til deres Bymænd og sagde:',
        21: 'disse Mænd ere fredsommelige hos os og ville bo i Landet og handle deri, og se, Landet er vidt nok for dem; vi ville tage os deres Døtre til Hustruer og give dem vore Døtre.',
        22: 'Dog i saa Maade ville Mændene være os til Villie med at bo hos os og blive eet Folk med os, om vi ville omskære alt Mandkøn iblandt os, lige som de ere omskaarne.',
        23: 'Deres Fæ og deres Gods og alt deres Kvæg, blive de ikke vore? ikkun at vi ere dem til Villie, da ville de bo hos os.',
        24: 'Og de løde Hemor og hans Søn Sikem, alle de, som gik ud af hans Stads Port, og alt Mandkøn lod sig omskære, alle som gik ud af hans Stads Port.',
        25: 'Og det skete paa den tredje Dag, der de havde Smerter, da toge de to Jakobs Sønner, Simeon og Levi, Dinas Brødre, hver sit Sværd og kom ind i den trygge Stad, og de sloge alt Mandkøn ihjel.',
        26: 'Og de sloge Hemor og hans Søn, Sikem, ihjel med skarpe Sværd og toge Dina af Sikems Hus og gik bort.',
        27: 'Saa kom Jakobs Sønner over de ihjelslagne og plyndrede Staden, fordi de havde skændet deres Søster.',
        28: 'Deres Kvæg og deres Øksen og deres Asener, baade hvad der var i Staden, og hvad der var paa Marken, toge de.',
        29: 'Og al deres Formue og alle deres Børn og deres Kvinder fangede og røvede de, og alt, hvad der var i Huset.',
        30: 'Da sagde Jakob til Simeon og Levi: I have forstyrret mig, idet I gjorde mig stinkende for dette Lands Indbyggere, for Kananiten og Feresiten, og jeg er en liden Hob, og de kunne samle sig imod mig og slaa mig, og jeg maatte ødelægges, jeg og mit Hus.',
        31: 'Og de sagde: Mon han skulde handle med vor Søster som med en Skøge?',
    },
    35: {
        1: 'Og Gud sagde til Jakob: Gør dig rede, drag op til Bethel og bliv der, og byg der et Alter for den Gud, som aabenbaredes for dig, der du flyede for din Broder Esaus Ansigt.',
        2: 'Da sagde Jakob til sit Hus og til alle, som vare med ham: Bortkaster de fremmede Guder, som ere iblandt eder, og renser eder og omskifter eders Klæder!',
        3: 'Og lader os gøre os rede og drage op til Bethel, og jeg vil der bygge et Alter for den Gud, som bønhørte mig paa min Nøds Dag og har været med mig paa Vejen, som jeg har vandret.',
        4: 'Saa gave de Jakob alle de fremmede Guder, som vare i deres Hænder, og Ringene, som vare i deres Øren, og Jakob skjulte dem under Egen, som var ved Sikem.',
        5: 'Saa rejste de; og Rædsel fra Gud var over de Stæder, som laa rundt omkring dem, at de ikke forfulgte Jakobs Sønner.',
        6: 'Og Jakob kom til Lus, som er i Kanaans Land, det er Bethel, han og alt Folket, som var med ham.',
        7: 'Og han byggede der et Alter og kaldte det Sted El-Beth-El, fordi Gud var aabenbaret der for ham, da han flyede for sin Broder.',
        8: 'Og Debora, Rebekkas Amme, døde og blev begraven neden for Bethel, under Egen, og han kaldte dens Navn Graadseg.',
        9: 'Og Gud aabenbaredes atter for Jakob, da han kom fra Paddan-Aram, og han velsignede ham.',
        10: 'Og Gud sagde til ham: Dit Navn er Jakob; dit Navn skal ikke ydermere kaldes Jakob; men Israel skal være dit Navn; og han kaldte hans Navn Israel.',
        11: 'Og Gud sagde til ham: Jeg er den almægtige Gud, vær frugtbar og former dig, Folk og Folkehobe skal der vorde af dig, og Konger skulle udkomme af dine Lænder.',
        12: 'Og det Land, som jeg har givet Abraham og Isak, det vil jeg give dig, og jeg vil give din Sæd efter dig Landet.',
        13: 'Og Gud for op fra ham, fra det Sted, hvor han talede med ham,',
        14: 'Saa oprejste Jakob et Mindesmærke paa det Sted, hvor han talede med ham, et Mindesmærke af Sten, og øste Drikoffer derpaa og overøste det med Olie.',
        15: 'Og Jakob kaldte det Steds Navn, hvor Gud talede med ham, Bethel.',
        16: 'Og de rejste fra Bethel, og der de vare endnu ikkun et Stykke Vej fra Efrat, da fødte Rakel, og hun havde en haard Fødsel.',
        17: 'Og det skete, da hun havde en haard Fødsel, at Jordemoderen sagde til hende: Frygt ikke; thi ogsaa her har du en Søn.',
        18: 'Og det skete, der hendes Sjæl for ud — thi hun døde — da kaldte hun hans Navn Ben-Oni; men hans Fader kaldte ham Ben-Jamin.',
        19: 'Saa døde Rakel og blev begraven paa Vejen til Efrat, det er Bethlehem.',
        20: 'Og Jakob satte et Mindesmærke over hendes Grav; dette er Rakels Gravs Mindesmærke indtil denne Dag.',
        21: 'Og Israel rejste derfra og opslog sit Telt paa hin Side Migdal Eder.',
        22: 'Og det hændte sig, der Israel boede i dette Land, da gik Ruben hen og laa hos Bilha, sin Faders Medhustru, og Israel hørte det. Og Jakob havde tolv Sønner.',
        23: 'Leas Sønner vare: Jakobs førstefødte, Ruben, og Simeon og Levi og Juda og Isaskar og Sebulon.',
        24: 'Rakels Sønner vare: Josef og Benjamin.',
        25: 'Og Rakels Pige Bilhas Sønner vare: Dan og Nafthali.',
        26: 'Og Leas Pige Silpas Sønner vare: Gad og Aser; disse ere Jakobs Sønner, som bleve ham fødte i Paddan-Aram.',
        27: 'Og Jakob kom til sin Fader Isak i Mamre, udi Kirjath-Arba, det er Hebron, hvor Abraham og Isak havde været fremmede.',
        28: 'Og Isak blev hundrede Aar og firsindstyve Aar gammel.',
        29: 'Og Isak opgav Aanden og døde og blev samlet til sit Folk, gammel og mæt af Dage; og Esau og Jakob, hans Sønner, begrove ham.',
    },
    36: {
        1: 'Og disse ere Esaus, det er Edoms, Slægter.',
        2: 'Esau tog sig Hustruer af Kanaans Døtre: Ada, Elons, den Hethiters Datter, og Oholibama, Anas Datter, Sibeons, den Heviters Datter,',
        3: 'og Basmat, Ismaels Datter, Nebajoths Søster.',
        4: 'Og Ada fødte Esau Elifas, og Basmat fødte Reguel.',
        5: 'Og Oholibama fødte Jeus og Jaelam og Kora; disse ere Esaus Sønner, som fødtes ham i Kanaans Land.',
        6: 'Og Esau tog sine Hustruer og sine Sønner og sine Døtre og alle Sjæle i sit Hus og sit Fæ og alt sit Kvæg og alt det Gods, som han havde forhvervet i Kanaans Land og drog til et Land, bort fra sin Broder Jakobs Ansigt.',
        7: 'Thi deres Gods var saa meget, at de ikke kunde bo tilsammen; og det Land, hvor de vare fremmede, kunde ikke bære dem for deres Kvægs Skyld.',
        8: 'Saa boede Esau paa det Bjerg Sejr; Esau, det er Edom.',
        9: 'Og disse ere Esaus, Edomiternes Faders, Slægter, paa det Bjerg Sejr.',
        10: 'Disse ere Esaus Sønners Navne: Elifas, Adas, Esaus Hustrus, Søn; Reguel, Basmats, Esaus Hustrus, Søn.',
        11: "Og disse vare Elifas' Sønner: Theman, Omar, Sefo og Gaetham og Kenas.",
        12: "Og Thimna var Elifas', Esaus Søns, Medhustru, og hun fødte Elifas Amalek; disse ere Adas, Esaus Hustrus, Sønner.",
        13: 'Og disse ere Reguels Sønner: Nahath og Serah, Samma og Missa; disse ere Basmats, Esaus Hustrus, Sønner.',
        14: 'Og disse vare Sønner af Oholibama, som var Anas Datter, Sibeons Datter, Esaus Hustru; og hun fødte Esau Jeus og Jaelam og Kora.',
        15: "Disse ere Fyrsterne iblandt Esaus Sønner: Elifas', Esaus førstefødtes, Sønner: Fyrsten Theman, Fyrsten Omar, Fyrsten Sefo, Fyrsten Kenas,",
        16: 'Fyrsten Kora, Fyrsten Gaetham, Fyrsten Amalek; disse ere Fyrsterne af Elifas i det Land Edom, disse vare Adas Sønner.',
        17: 'Og disse ere Reguels, Esaus Søns, Sønner: Fyrsten Nabath, Fyrsten Sera, Fyrsten Samma, Fyrsten Missa; disse ere Fyrsterne af Reguel i Edoms Land; disse ere Basmats, Esaus Hustrus, Sønner.',
        18: 'Og disse ere Oholibamas, Esaus Hustrus, Sønner: Fyrsten Jeus, Fyrsten Jaelam, Fyrsten Kora; disse ere Fyrsterne af Oholibama, Anas Datter, Esaus Hustru.',
        19: 'Disse ere Esaus Sønner, og disse deres Fyrster; det er Edom.',
        20: 'Disse ere Sejrs den Horiters Sønner, som boede i Landet: Lotan og Sobal og Sibeon og Ana',
        21: 'og Dison og Ezer og Disan; disse ere Horiternes Fyrster, Sejrs Sønner i det Land Edom.',
        22: 'Og Lotans Sønner vare: Hori og Heman, og Lotans Søster var Thimna.',
        23: 'Og disse vare Sobals Sønner: Alvan og Manahath og Ebal, Sefo og Onam.',
        24: 'Og disse ere Sibeons Sønner, baade Aja og Ana; denne Ana var det, som fandt varme Kilder i Ørken, der han vogtede sin Fader Sibeons Asener.',
        25: 'Og disse vare Anas Børn: Dison, og Oholibama var Anas Datter.',
        26: 'Og disse vare Disons Sønner: Hemdan og Esban og Jithran og Keran.',
        27: 'Disse vare Ezers Sønner: Bilhan og Savan og Akan.',
        28: 'Disse vare Disans Sønner: Uz og Aran.',
        29: 'Disse vare Horiternes Fyrster: Fyrsten Lotan, Fyrsten Sobal, Fyrsten Sibeon, Fyrsten Ana,',
        30: 'Fyrsten Dison, Fyrsten Ezer, Fyrsten Disan; disse vare Horiternes Fyrster, iblandt deres Fyrster, i Sejrs Land.',
        31: 'Og disse ere de Konger, som regerede i Edoms Land, førend der regerede en Konge over Israels Børn:',
        32: 'nemlig Bela, Beors Søn, var Konge i Edom, og hans Stads Navn var Dinhaba.',
        33: 'Og Bela døde, og Jobab, Seras Søn fra Bosra, blev Konge i hans Sted.',
        34: 'Og Jobab døde, og Husam af Themanitens Land blev Konge i hans Sted.',
        35: 'Og Husam døde, og Hadad, Bedads Søn, blev Konge i hans Sted, han, som slog Midianiterne paa Moabs Mark; og hans Stads Navn var Avith.',
        36: 'Og Hadad døde, og Samla af Masreka blev Konge i hans Sted.',
        37: 'Og Samla døde, og Saul af Rekoboth ved Floden blev Konge i hans Sted.',
        38: 'Og Saul døde, og Baal Hanan, Akbors Søn, blev Konge i hans Sted.',
        39: 'Og Baal Hanan, Akbors Søn, døde, og Hadar blev Konge i hans Sted, og hans Stads Navn var Pau, og hans Hustrus Navn var Mehetabeel, en Datter af Matred, som var Mesahabs Datter.',
        40: 'Og disse vare Fyrsternes Navne, som kom af Esau, efter deres Slægter, i deres Stæder, ved deres Navne: Fyrsten Thimna, Fyrsten Alva, Fyrsten Jetheth,',
        41: 'Fyrsten Oholibama, Fyrsten Ela, Fyrsten Pinon,',
        42: 'Fyrsten Kenas, Fyrsten Theman, Fyrsten Mibsar,',
        43: 'Fyrsten Magdiel, Fyrsten Iram; disse ere Fyrsterne i Edom, eftersom de boede i deres eget Land. Denne Esau er Fader til Edomiterne.',
    },
    37: {
        1: 'Og Jakob boede i det Land, hvori hans Fader havde været fremmed, i det Land Kanaan.',
        2: 'Disse ere Jakobs Slægter. Josef var sytten Aar gammel, der han vogtede Kvæg med sine Brødre, og var som Dreng hos Bilhas Sønner og hos Silpas Sønner, hans Faders Hustruers Børn; og Josef førte deres onde Rygte forderes Fader.',
        3: 'Og Israel elskede Josef fremfor alle sine Sønner, fordi han avlede ham i Alderdommen, og han gjorde ham en broget Kjortel.',
        4: 'Der hans Brødre saa, at deres Fader elskede ham mere end alle hans Brødre, da fik de Had til ham og kunde ikke tale fredeligen til ham.',
        5: 'Og Josef drømte en Drøm og forkyndte sine Brødre den; da fik de end større Had til ham.',
        6: 'Og han sagde til dem: Kære, hører denne Drøm, som jeg har drømt.',
        7: 'Se, vi bandt Neg midt paa Marken, og se, mit Neg rejste sig op og blev ogsaa staaende, og se, eders Neg stode omkring og bøjede sig for mit Neg.',
        8: 'Da sagde hans Brødre til ham: Skulde du virkelig regere over os? eller skulde du virkelig herske over os? Saa fik de end mere Had til ham for hans Drømme og for hans Tale.',
        9: 'Og han drømte endnu en anden Drøm, og han fortalte sine Brødre den og sagde: Se, jeg drømte endnu en Drøm, og se, Solen og Maanen og elleve Stjerner bøjede sig for mig.',
        10: 'Og der han fortalte det til sin Fader og til sine Brødre, da straffede hans Fader ham og sagde til ham: Hvad er det for en Drøm, som du drømte? mon jeg og din Moder og dine Brødre virkelig skulde komme og bøje os for dig til Jorden?',
        11: 'Og hans Brødre avindedes paa ham; men hans Fader bevarede den Tale.',
        12: 'Og hans Brødre gik at vogte deres Faders Kvæg i Sikem.',
        13: 'Og Israel sagde til Josef: Vogte ikke dine Brødre i Sikem? gak, og jeg vil sende dig til dem; og han sagde til ham: Se, jeg er rede.',
        14: 'Og han sagde til ham: Kære, gak, se, om det gaar vel med dine Brødre og vel med Kvæget, og bring mig Svar igen; saa sendte han ham fra Hebrons Dal, og han kom til Sikem.',
        15: 'Da mødte en Mand ham, og se, han vankede hid og did paa Marken, og Manden spurgte ham og sagde: Hvad leder du efter?',
        16: 'Og han sagde: Jeg leder efter mine Brødre; kære, giv mig til Kende, hvor de vogte.',
        17: 'Og Manden sagde: De droge herfra; thi jeg hørte dem sige: Lader os gaa til Dothan; saa gik Josef efter sine Brødre og fandt dem i Dothan.',
        18: 'Der de saa ham langt fra, og før han kom nær til dem, da lagde de Raad op mod ham at slaa ham ihjel.',
        19: 'Og de sagde, den ene til den anden: Se, denne Drømmemester kommer.',
        20: 'Og nu, kommer og lader os ihjel slaa ham og kaste ham i en af Gravene og sige: Et vildt Dyr har ædt ham, saa ville vi se, hvad der bliver af hans Drømme.',
        21: 'Der Ruben hørte dette, friede han ham af deres Hænder og sagde: Lader os ikke slaa ham ihjel!',
        22: 'Og Ruben sagde til dem: Udøser ikke Blod, kaster ham i denne Grav, som er i Ørken, og lægger ikke Haand paa ham; thi han vilde fri ham af deres Haand og føre ham tilbage til sin Fader.',
        23: 'Og det skete, der Josef kom til sine Brødre, da førte de Josef af hans Kjortel, af hans brogede Kjortel, som han havde paa sig.',
        24: 'Og de toge ham og kastede ham i Graven, og Graven var tom, intet Vand var i den.',
        25: 'Saa satte de sig til at æde Brød, og de løftede deres Øjne op og saa, og se, en rejsende Hob Ismaeliter kom fra Gilead, og deres Kameler bare Urter og Balsam og Ladanum, og de gik for at drage ned til Ægypten.',
        26: 'Da sagde Juda til sine Brødre: Hvad gavner det, om vi ihjelslaa vor Broder og dølge hans Blod?',
        27: 'Kommer og lader os sælge ham til Ismaeliterne, at vor Haand ikke skal i være paa ham, thi han er vor Broder, vort Kød; saa adløde hans Brødre ham.',
        28: 'Og da de midianitiske Mænd, som vare Købmænd, kom forbi, trak de Josef op og droge ham frem af Graven, og de solgte Josef til Ismaeliterne for tyve Sekel Sølv; og disse førte Josef til Ægypten.',
        29: 'Og Ruben kom til Graven igen, og se, Josef var ikke i Graven; og han sønderrev sine Klæder.',
        30: 'Og han kom tilbage til sine Brødre og sagde: Drengen er der ikke! og jeg, hvor skal jeg gaa hen!',
        31: 'Og de toge Josefs Kjortel og slagtede en Gedebuk og dyppede Kjortelen i Blodet,',
        32: 'og de sendte den brogede Kjortel og lode den bringe til deres Fader og sagde: Denne have vi fundet; kære, kend, om det er din Søns Kjortel eller ej?',
        33: 'Og han kendte den og sagde: Det er min Søns Kjortel, et vildt Dyr har ædt ham, Josef er visselig reven ihjel.',
        34: 'Og Jakob sønderrev sine Klæder og lagde Sæk om sine Lænder og sørgede over sin Søn lang Tid.',
        35: 'Og alle hans Sønner og alle hans I Døtre lagde sig efter at trøste ham; men han vilde ikke lade sig trøste og sagde: Thi jeg maa fare med Sorg ned i Graven til min Søn; og hans I Fader begræd ham.',
        36: 'Og Midianiterne solgte ham til Ægypten til Potifar, Faraos Hofsinde og Øverste for Livvagten.',
    },
    38: {
        1: 'Og det hændte sig til den Tid, at Juda drog ned fra sine Brødre og tog ind til en Mand, en Adullamiter, og hans Navn var Hira.',
        2: 'Og der saa Juda en kananitisk Mands Datter, og hans Navn var Sua; og han tog hende og gik ind til hende.',
        3: 'Og hun undfik og fødte en Søn, og hun kaldte hans Navn Er.',
        4: 'Og hun undfik atter og fødte en Søn, og han kaldte hans Navn Onan.',
        5: 'Og hun blev endnu ved og fødte en Søn, og hun kaldte hans Navn Sela, og han var i Kesib, der hun fødte ham.',
        6: 'Og Juda tog en Hustru for sin førstefødte, Er, og hendes Navn var Thamar.',
        7: 'Men Er, Judas førstefødte, var ond for Herrens Øjne, og Herren slog ham ihjel.',
        8: 'Da sagde Juda til Onan: Gak ind til din Broders Hustru, og tag hende til Ægte i din Broders Sted, og opvæk din Broder Sæd!',
        9: 'Og Onan forstod, at Sæden ikke skulde høre ham til; og det skete, naar han gik ind til sin Broders Hustru, da fordærvede han den paa Jorden, for ikke at give sin Broder Sæd.',
        10: 'Og det var ondt for Herrens Øjne, hvad han gjorde, og han slog ogsaa ham ihjel.',
        11: 'Da sagde Juda til Thamar, sin Sønnekvinde: Sid som Enke i din Faders Hus, indtil Sela, min Søn, bliver stor; thi han sagde: at ikke ogsaa han skal dø som hans Brødre; saa gik Thamar og blev i sin Faders Hus.',
        12: 'Der mange Dage vare forløbne, da døde Suas Datter, Judas Hustru, og efter at Juda var trøstet, gik han op til Thimnat til dem, som klippede hans Hjord, han og Hira, hans Ven, den Adullamiter.',
        13: 'Da blev det Thamar tilkendegivet og sagt: Se, din Svigerfader gaar op til Thimnat at klippe sin Hjord.',
        14: 'Da lagde hun sine Enkeklæder af sig og skjulte sig med et Slør og bedækkede sig og satte sig ved Indgangen til Enaim, som er paa Vejen til Thimnat; thi hun saa, at Sela var bleven stor, og hun blev ikke given ham til Hustru.',
        15: 'Der Juda saa hende, tænkte han, at det var en Skøge, fordi hun havde skjult sit Ansigt.',
        16: 'Og han bøjede af til hende paa Vejen og sagde: Velan, kære, lad mig komme til dig; thi han vidste ikke, at det var hans Søns Hustru; og hun sagde: Hvad vil du give mig, at du maa komme til mig?',
        17: 'Og han sagde: Jeg vil sende et Gedekid af Hjorden; og hun sagde: Dersom du vil give mig Pant, indtil du sender mig det.',
        18: 'Og han sagde: Hvad for et Pant er det, jeg skal give dig? og hun sagde: Dit Signet og din Snor og din Kæp, som du har i din Haand; saa gav han hende det og gik til hende, og hun undfik af ham.',
        19: 'Saa stod hun op og gik og lagde sit Slør af sig og førte sig i sine Enkeklæder.',
        20: 'Og Juda sendte det Gedekid ved sin Ven, den Adullamiter, at han skulde tage Pantet af Kvindens Haand, og han fandt hende ikke.',
        21: 'Da spurgte han Mændene ad der paa Stedet og sagde: Hvor er Skøgen, hun ved Enaim, paa Vejen? og de sagde: Paa dette Sted har ingen Skøge været.',
        22: 'Og han kom igen til Juda og sagde: Jeg fandt hende ikke, og tilmed sagde Folkene paa samme Sted: her har ingen Skøge været.',
        23: 'Da sagde Juda: Lad hende beholde det, paa det vi ikke skulle beskæmmes; se, jeg har sendt dette Kid, og du fandt hende ikke.',
        24: 'Og det skete henved tre Maaneder derefter, da blev det Juda tilkendegivet, saa der sagdes: Thamar, din Søns Hustru, har bedrevet Hor, og se, hun har ogsaa undfanget i Horeri; og Juda sagde: Fører hende ud, og hun skal brændes.',
        25: 'Hun blev ført ud, og hun sendte til sin Svigerfader, sigende: Ved den Mand har jeg undfanget, hvem dette hører til; og hun sagde: Kære, kend, hvem dette Signet og denne Snor og denne Kæp tilhører.',
        26: 'Og Juda kendte det og sagde: Hun er retfærdigere end jeg; thi dette er, fordi jeg ikke gav hende til min Søn Sela; og han kendte hende ikke ydermere.',
        27: 'Og det skete den Tid, hun skulde føde, se, da vare Tvillinger i hendes Liv.',
        28: 'Og det skete, der hun fødte, stak den ene en Haand frem, da tog Jordemoderen den og bandt en rød Traad om hans Haand, sigende: Denne kom først frem.',
        29: 'Og det skete, der han tog sin Haand tilbage, se, da kom hans Broder frem, og hun sagde: Hvi bryder du frem? for din Skyld er der sket et Brud. Og man kaldte hans Navn Peres.',
        30: 'Og siden kom hans Broder frem, som havde den røde Traad om sin Haand, og man kaldte hans Navn Sera.',
    },
    39: {
        1: 'Og Josef var ført ned til Ægypten, og Potifar, Faraos Hofsinde, Øverste for Livvagten, en ægyptisk Mand, købte ham af Ismaeliterne, som havde ført ham did ned.',
        2: 'Og Herren var med Josef, at han blev en lykkelig Mand, og han var i sin Herres, den Ægypters Hus.',
        3: 'Og hans Herre saa, at Herren var med ham; thi alt det, han gjorde, lod Herren lykkes ved hans Haand.',
        4: 'Og Josef fandt Naade for hans Øjne og tjente ham, og han satte ham over sit Hus, og alt det, han havde, gav han i hans Haand.',
        5: 'Og det skete, fra den Tid han havde sat ham over sit Hus og over alt, hvad han havde, da velsignede Herren Ægypterens Hus for Josefs Skyld; og der var Herrens Velsignelse i alt det, han havde i Huset og paa Marken.',
        6: 'Og han overlod alting, som han havde, i Josefs Haand, og saa ikke til med ham i noget uden den Mad, som han selv aad. Og Josef var smuk af Skikkelse og smuk af Udseende.',
        7: 'Og det hændte sig derefter, at hans Herres Hustru kastede sine Øjne paa Josef og sagde: Lig hos mig!',
        8: 'Men han vægrede sig og sagde til sin Herres Hustru: Se, min Herre ser ikke til med mig i noget af, hvad der er i Huset, og alt, hvad han har, har han givet i min Haand.',
        9: 'Han selv er ikke større i dette Hus end jeg, og han formener intet for mig uden dig, fordi du er hans Hustru; og hvorledes skal jeg gøre denne store Ondskab og synde imod Gud.',
        10: 'Og det skete, som hun talede til Josef Dag efter Dag, adlød han hende dog ikke med at ligge hos hende eller at være med hende.',
        11: 'Og det hændte sig en Dag, der han kom i Huset at gøre sin Gerning, og der var ingen af Husets Mænd der i Huset,',
        12: 'da tog hun ham fat ved hans Klædebon og sagde: Lig hos mig; men han efterlod sit Klædebon i hendes Haand og flyede og gik udenfor.',
        13: 'Og det skete, som hun saa, at han efterlod sit Klædebon i hendes Haand og flyede udenfor,',
        14: 'da kaldte hun ad sine Husfolk og sagde til dem, sigende: Ser, han har ført os en hebraisk Mand paa, at drive Spot med os; han kom ind til mig at ligge hos mig, men jeg kaldte med høj Røst.',
        15: 'Og det skete, der han hørte, at jeg opløftede min Røst og kaldte, da efterlod han sit Klædebon hos mig og flyede og gik udenfor.',
        16: 'Og hun lod hans Klædebon ligge hos sig, indtil hans Herre kom hjem.',
        17: 'Og hun talte til ham lige de samme Ord og sagde: Den hebraiske Tjener, som du har ført os paa, kom til mig at drive Spot med mig.',
        18: 'Og det skete, der jeg opløftede min Røst og kaldte, da efterlod han sit Klædebon hos mig og flyede udenfor.',
        19: 'Og det skete, der hans Herre hørte sin Hustrus Ord, som hun talede til ham, sigende: Paa den Maade har din Tjener gjort imod mig, da blev han meget vred.',
        20: 'Da tog Josefs Herre ham og kastede ham i Fængslets Hus, et Sted, hvor Kongens Fanger holdtes bundne, og han var der i Fængslets Hus.',
        21: 'Men Herren var med Josef og bøjede Miskundhed til ham og gav ham Naade hos Fængselhusets Forstander,',
        22: 'at Fængselhusets Forstander gav alle Fanger, som vare i Fængslets Hus, i Josefs Haand; og alt det, som skulde gøres der, det gjorde denne.',
        23: 'Forstanderen for Fængselhuset gav ikke Agt paa nogen Ting, som var i hans Haand, fordi Herren var med ham, og det, som han gjorde, gav Herren Lykke til.',
    },
    40: {
        1: 'Og det hændte sig derefter, at Kongen af Ægyptens Mundskænk og Bager syndede mod deres Herre, Kongen af Ægypten.',
        2: 'Og Farao blev vred paa begge sine Betjente, paa den øverste Mundskænk og den øverste Bager.',
        3: 'Og han satte dem i Forvaring i Huset hos Øversten for Livvagten, i Fængslets Hus, paa det Sted, hvor Josef var Fange.',
        4: 'Og Øversten for Livvagten beskikkede Josef til at være hos dem, og han betjente dem, og de vare en Tid i Forvaring.',
        5: 'Og de drømte begge en Drøm, hver sin Drøm i een Nat, hver sin Drøm efter sin Udtydning, Kongen af Ægyptens Mundskænk og Bager, som vare Fanger i Fængslets Hus.',
        6: 'Og Josef kom til dem om Morgenen og saa dem, og se, de vare bedrøvede.',
        7: 'Og han spurgte Faraos Betjente, som vare med ham i Forvaring i hans Herres Hus, og sagde: Hvi se I saa ilde ud i Dag?',
        8: 'Og de sagde til ham: Vi drømte en Drøm, og her er ingen, som kan udtyde den. Og Josef sagde til dem: Hører ikke Udtydninger Gud til fortæller mig det dog!',
        9: 'Da fortalte den øverste Mundskænk Josef sin Drøm og sagde til ham: Idet jeg drømte, se, da var et Vintræ for mig.',
        10: 'Og paa Vintræet vare tre Kviste, og det grønnedes, og dets Blomster fremkom, og Klaserne derpaa fik modne Bær.',
        11: 'Og Faraos Bæger var i min Haand, og jeg tog Druerne og trykkede dem i Faraos Bæger og gav Farao Bægeret i Haanden.',
        12: 'Da sagde Josef til ham: Denne er Udtydningen derpaa: de tre Vinkviste ere tre Dage.',
        13: 'Om tre Dage skal Farao opløfte dit Hoved og sætte dig i dit Sted igen, at du skal give Faraos Bæger i hans Haand, efter den forrige Vis, der du var hans Mundskænk.',
        14: 'Men tænk du paa mig, naar det gaar dig vel, og gør da den Miskundhed mod mig, at du erindrer mig hos Farao, at han tager mig ud af dette Hus.',
        15: 'Thi jeg er hemmelig stjaalen af de Hebræers Land; dertil har jeg ikke heller her gjort noget, at de have sat mig i Hulen.',
        16: 'Og der den øverste Bager saa, at han havde udtydet det vel, da sagde han til Josef: Jeg drømte ogsaa, og se, der var tre Kurve med Hvedebrød paa mit Hoved.',
        17: 'Og i den øverste Kurv var af alle Haande Mad, Bagværk til Farao, og Fuglene aade det af Kurven paa mit Hoved.',
        18: 'Da svarede Josef og sagde: Denne er Udtydningen derpaa: de tre Kurve ere tre Dage.',
        19: 'Om tre Dage skal Farao opløfte dit Hoved fra dig og hænge dig paa et Træ, og Fuglene skulle æde dit Kød af dig.',
        20: 'Og det skete paa den tredje Dag, paa Faraos Fødselsdag, da gjorde han alle sine Tjenere et Gæstebud og opløftede den øverste Mundskænks Hoved og den øverste Bagers Hoved iblandt sine Tjenere.',
        21: 'Og han satte den øverste Mundskænk til sit Skænkeembede igen, og han rakte Bægeret i Faraos Haand.',
        22: 'Men den øverste Bager lod han hænge, saasom Josef havde udtydet dem.',
        23: 'Og den øverste Mundskænk tænkte ikke paa Josef, men forglemte ham.',
    },
    41: {
        1: 'Og det skete, der to Aar vare omme, da drømte Farao, og se, han stod ved Floden.',
        2: 'Og se, af Floden opsteg syv Køer, skønne af Udseende og fede paa Kød, og aade i Engen.',
        3: 'Og se, syv andre Køer opstege efter disse af Floden, stygge af Udseende og magre paa Kød, og stode hos de andre Køer paa Bredden af Floden.',
        4: 'Og de Køer, som vare stygge af Udseende og magre paa Kød, opaade de syv Køer, som vare skønne af Udseende og fede; saa vaagnede Farao.',
        5: 'Og han faldt i Søvn og drømte anden Gang, og se, syv Aks voksede op paa eet Straa, fulde og gode.',
        6: 'Og se, syv Aks, tynde og svedne af Østenvinden, skøde op efter dem.',
        7: 'Og de magre Aks opslugte de syv fede og fulde Aks; da vaagnede Farao, og se, det var en Drøm.',
        8: 'Og det skete om Morgenen, da var hans Aand bekymret, og han sendte hen og lod kalde alle Spaamænd i Ægypten og alle de vise derudi, og Farao fortalte dem sin Drøm; men der var ingen, som udtydede Farao den.',
        9: 'Da talede den øverste Mundskænk til Farao og sagde: Jeg ihukommer i Dag min Synd.',
        10: 'Farao var vred paa sine Tjenere og lod mig sætte i Fængsel udi Huset hos den øverste for Livvagten, mig og den øverste Bager.',
        11: 'Da drømte vi en Drøm i een Nat, jeg og han; vi drømte, hver efter sin Drøms Udtydning.',
        12: 'Og der var hos os en hebraisk ung Karl, en Tjener hos den øverste for Livvagten, og ham fortalte vi, og han udtydede os vore Drømme; hver efter sin Drøm udtydede han det.',
        13: 'Og det skete, ligesom han udtydede os det, saa skete det; mig satte man i mit Sted igen, og ham hængte man.',
        14: 'Da sendte Farao hen og lod kalde Josef, og de lode ham straks ud af Hulen, og han lod sig rage og førte sig i andre Klæder og kom til Farao.',
        15: 'Da sagde Farao til Josef: Jeg drømte en Drøm, og ingen er der, som kan udtyde den; men jeg har hørt sige om dig, at naar du hører en Drøm, kan du udtyde den.',
        16: 'Og Josef svarede Farao og sagde: Det staar ikke til mig; Gud skal svare Farao godt.',
        17: 'Da sagde Farao til Josef: Der jeg drømte, se, da stod jeg paa Bredden af Floden.',
        18: 'Og se, syv Køer opstege af Floden, fede paa Kød og skønne af Skikkelse, og de aade i Engen.',
        19: 'Og se, efter dem opstege syv andre Køer, tynde og saare stygge af Skikkelse og magre paa Kød; jeg har ikke set saa stygge som dem i hele Ægyptens Land.',
        20: 'Og de magre og stygge Køer aade de syv første fede Køer.',
        21: 'Og der de havde opædt dem, kendtes det dog ikke paa dem, at de havde opædt dem, og de vare stygge at se til ligesom tilforn; og jeg vaagnede.',
        22: 'Og jeg saa, der jeg drømte, og se, syv Aks, som voksede op paa eet Straa, fulde og gode.',
        23: 'Og se, efter dem skøde syv tørre Aks frem, som vare tynde og svedne af Østenvinden.',
        24: 'Og de tynde Aks opslugte de syv gode Aks; og jeg har sagt Spaamændene det, men ingen kan udtyde mig det.',
        25: 'Og Josef sagde til Farao: Faraos Drøm, den er een: Gud giver Farao til Kende, hvad han vil gøre.',
        26: 'De syv gode Køer, de ere syv Aar, og de syv gode Aks, de ere syv Aar, det er een Drøm.',
        27: 'Og de syv magre og stygge Køer, de ere syv Aar, og de syv tomme Aks, svedne af Østenvinden, skulle være syv Hungers Aar.',
        28: 'Det er det Ord, som jeg har sagt Farao: Gud lader Farao se, hvad han vil gøre.',
        29: 'Se, der kommer syv Aar med stor Overflødighed i hele Ægyptens Land.',
        30: 'Og syv Hungers Aar skulle komme efter dem, at al den Overflødighed skal glemmes i Ægyptens Land, og Hungeren skal fortære Landet.',
        31: 'Og der skal ikke vides af den Overflødighed i Landet for den Hunger, som kommer derefter; thi den bliver meget svar.',
        32: 'Men at Farao har drømt igen anden Gang betyder, at det skal visselig ske af Gud, og Gud skal snarlig gøre dette.',
        33: 'Saa se nu Farao sig om efter en forstandig og viis Mand, som han kan sætte over Ægyptens Land.',
        34: 'Dette gøre Farao, og han beskikke Tilsynsmænd over Landet og tage den femte Del af Ægyptens Land i de syv Overflødigheds Aar.',
        35: 'Og de skulle samle alle Haande Spise udi disse tilkommende gode Aar og sanke Korn under Faraos Haand til Spise, i Stæderne, og de skulle forvare det.',
        36: 'Og den Spise skal være beskikket for Landet til de syv Hungerens Aar, som skulle komme over Ægyptens Land, at Landet ikke skal ødelægges af Hunger.',
        37: 'Og denne Tale var god for Faraos Øjne og for alle hans Tjeneres Øjne.',
        38: 'Og Farao sagde til sine Tjenere: Mon vi kunne finde nogen som denne, en Mand, i hvem Guds Aand er?',
        39: 'Og Farao sagde til. Josef: Efterdi Gud har ladet dig vide alt dette, da er ingen saa forstandig og viis som du.',
        40: 'Du skal være over mit Hus, og alt mit Folk skal være dine Ord lydigt; alene ved Tronen vil jeg være større end du.',
        41: 'Og Farao sagde til Josef: Se, jeg har sat dig over alt Ægyptens Land.',
        42: 'Og Farao tog sin Ring af sin Haand og satte den paa Josefs Haand og lod ham føre i kostelige Linklæder og hængte en Guldkæde om hans Hals',
        43: 'og lod ham age paa sin anden Vogn, og de raabte for ham: Abrek; og han satte ham over hele Ægyptens Land.',
        44: 'Og Farao sagde til Josef: Jeg er Farao; og uden din Villie skal ingen Mand opløfte sin Haand eller sin Fod i hele Ægyptens Land.',
        45: 'Og Farao kaldte Josefs Navn Zafnath Panea og gav ham Asnath, en Datter af Præsten Potifera i On, til Hustru; saa drog Josef ud over Ægyptens Land.',
        46: 'Og Josef var tredive Aar gammel, der han stod for Farao, Kongen i Ægypten; og Josef gik ud fra Farao og rejste igennem hele Ægyptens Land.',
        47: 'Og Landet bar i Hobetal i de syv Overflødigheds Aar.',
        48: 'Og han samlede al Spise i de syv Aar, som vare i Ægyptens Land, og lagde Spise i Stæderne; hvad der voksede paa Markerne omkring hver Stad til Spise, det lagde han derudi.',
        49: 'Saa samlede Josef Korn som Havets Sand, overmaade meget, indtil han lod af at tælle; thi der var ikke Tal derpaa.',
        50: 'Og før Hungerens Aar kom, blev der født Josef to Sønner, hvilke Asnath, en Datter af Præsten Potifera i On, fødte ham.',
        51: 'Og Josef kaldte den førstefødtes Navn Manasse; „thi Gud har ladet mig glemme al min Møje og alt min Faders Hus‟.',
        52: 'Og den andens Navn kaldte han Efraim; „thi Gud har gjort mig frugtbar i min Elendigheds Land‟.',
        53: 'Og de syv Overflødigheds Aar endte, som vare i Ægyptens Land.',
        54: 'Og de syv Hungerens Aar begyndte at komme, som Josef havde sagt, og der var Hunger i alle Landene, men der var Brød i det hele Ægyptens Land.',
        55: 'Der hele Ægyptens Land led Hunger, da raabte Folket til Farao om Brød; men Farao sagde til alle Ægyptere: Gaar til Josef, hvad han siger eder, skulle I gøre.',
        56: 'Der Hungeren var i hele Landet, da oplod Josef alle Steder, hvor noget var, og solgte Ægypterne Korn; thi Hungeren tog Overhaand i Ægyptens Land.',
        57: 'Og fra alle Lande kom man til Ægypten for at købe hos Josef; thi Hungeren var meget svar i alle Lande.',
    },
    42: {
        1: 'Der Jakob saa, at Korn var til fals i Ægypten, da sagde Jakob til sine Sønner: Hvi se I paa hverandre?',
        2: 'Og han sagde: Se, jeg hører, at der er Korn til føls i Ægypten, farer did ned og køber til os derfra, at vi maa leve og ikke dø.',
        3: 'Saa droge Josefs ti Brødre ned at købe Korn i Ægypten.',
        4: 'Men Jakob lod ikke Benjamin, Josefs Broder, fare med sine Brødre; thi han sagde: Der kunde vederfares ham nogen Ulykke.',
        5: 'Saa kom Israels Sønner at købe iblandt dem, som kom; thi der var Hunger i Landet Kanaan.',
        6: 'Og Josef var Regent over Landet, han var den, som solgte til alt Folket i Landet; og Josefs Brødre kom, og de faldt ned for ham paa deres Ansigt til Jorden.',
        7: 'Og Josef saa sine Brødre og kendte dem og holdt sig fremmed mod dem og talede haarde Ting med dem og sagde til dem: Hvorfra komme I? og de sagde: Fra det Land Kanaan for at købe Spise.',
        8: 'Og Josef kendte sine Brødre; men de kendte ikke ham.',
        9: 'Og Josef kom de Drømme i Hu, som han havde drømt om dem, og sagde til dem: I ere Spejdere, I ere komne at bese, hvor Landet er blot.',
        10: 'Og de sagde til ham: Nej, min Herre! men dine Tjenere ere komne for at købe Spise.',
        11: 'Vi ere alle een Mands Sønner, vi ere redelige, dine Tjenere ere ikke Spejdere.',
        12: 'Og han sagde til dem: Nej, men I ere komne for at bese, hvor Landet er blot.',
        13: 'De svarede: Vi, dine Tjenere, vare tolv Brødre, een Mands Sønner i Kanaans Land; og se, den yngste er endnu hos vor Fader, men den ene er ikke til.',
        14: 'Og Josef sagde til dem: Det er det, som jeg har talet til eder, der jeg sagde: I ere Spejdere.',
        15: 'Derpaa skulle I prøves: saa sandt Farao lever, skulle I ikke komme herfra, uden eders yngste Broder kommer hid.',
        16: 'Sender een af eder bort, at han skal hente eders Broder; men I skulle være fangne, og eders Ord skulle prøves, om I fare med Sandhed; thi hvis ikke, da ere I, saa sandt Farao lever, Spejdere.',
        17: 'Og han satte dem tilsammen i Forvaring i tre Dage.',
        18: 'Men den tredje Dag sagde Josef til dem: Gører dette, saa skulle I leve; jeg frygter Gud.',
        19: 'Dersom I ere redelige, da lader een af eders Brødre blive som Fange i eders Forvaringshus; men farer I andre hen og fører det hjem, som I have købt mod Hungeren, for eders Huse,',
        20: 'og henter eders yngste Broder til mig, saa skulle eders Ord tros, og I skulle ikke dø; og de gjorde saaledes.',
        21: 'Men de sagde den ene til den anden: Vi have sandelig forskyldt dette for vor Broder, da vi saa hans Sjæls Angest, idet han bad os, og vi vilde ikke høre, derfor kommer denne Angest over os.',
        22: 'Og Ruben svarede dem og sagde: Talede jeg det ikke til eder, der jeg sagde: synder ikke mod Drengen, og I hørte ikke? og se, nu kræves ogsaa hans Blod.',
        23: 'Men de vidste ikke, at Josef forstod det; thi der var en Tolk imellem dem.',
        24: 'Og han vendte sig fra dem og græd, og han vendte sig til dem igen og talede med dem og tog Simeon fra dem og lod ham binde for deres Øjne.',
        25: 'Og Josef befalede, at man skulde fylde deres Poser med Korn og give dem deres Penge igen, hver i sin Sæk, og give dem Tæring paa Vejen; og han gjorde saa mod dem.',
        26: 'Og de lagde deres Korn paa deres Asener og fore derfra.',
        27: 'Men der den ene lod sin Sæk op for at give sit Asen Foder i Herberget, da saa han sine Penge, og se, de laa oven i hans Pose.',
        28: 'Og han sagde til sine Brødre: Mine Penge ere komne igen, og se, de ere her i min Pose; da faldt deres Mod, og de forskrækkedes den ene med den anden og sagde: Hvorfor har Gud gjort os dette?',
        29: 'Og de kom til Jakob, deres Fader, til Kanaans Land; og de gave ham til Kende alt det, som var dem vederfaret, og sagde:',
        30: 'Den Mand, som er Herre i Landet, talte os haardelig til og holdt os for Landets Spejdere.',
        31: 'Og vi svarede ham: vi ere redelige, vi ere ikke Spejdere.',
        32: 'Vi vare tolv Brødre, vor Faders Sønner, den ene er ikke til, og den yngste er endnu hos vor Fader i Kanaans Land.',
        33: 'Da sagde Manden, Landets Herre, til os: derpaa vil jeg kende, om I ere redelige: lader den ene af eders Brødre blive hos mig, og tager, hvad I behøve mod Hungeren for eders Huse, og farer hen',
        34: 'og henter eders yngste Broder til mig, saa kan jeg kende, at I ikke ere Spejdere, men at I ere redelige; saa vil jeg give eder eders Broder igen, og I maa handle i Landet.',
        35: 'Og det skete, der de tømte deres Sække, se, da var hvers Pengeknude i hans Sæk; og de saa deres Pengeknuder, de og deres Fader, og frygtede.',
        36: 'Da sagde Jakob, deres Fader, til dem: I berøve mig mine Børn; Josef er ikke til, og Simeon er ikke til, og Benjamin ville I tage hen; over mig kommer det altsammen.',
        37: 'Og Ruben talede til sin Fader og sagde: Du maa slaa begge mine Sønner ihjel, om jeg ikke fører ham til dig igen; giv ham i min Haand, og jeg vil føre ham til dig igen.',
        38: 'Og han sagde: Min Søn skal ikke fare ned med eder; thi hans Broder er død, og han alene er bleven tilbage, og møder ham nogen Ulykke paa Vejen, som I drage hen paa, da skulle I føre mine graa Haar med Sorg til Graven. Og Hungeren var svar i Landet.',
    },
    43: {
        1: 'Og det skete, der de havde fortæret Kornet, som de havde hentet fra Ægypten, da sagde deres Fader til dem: Farer hen igen og køber os lidt Spise!',
        2: 'Da talede Juda til ham, sigende: Manden vidnede alvorlig for os og sagde: I skulle ikke se mit Ansigt, uden eders Broder er med eder.',
        3: 'Dersom du sender vor Broder med os, ville vi fare ned og købe dig Spise.',
        4: 'Men dersom du ikke vil sende ham, fare vi ikke ned; thi Manden sagde til os: I skulle ikke se mit Ansigt, uden eders Broder er med eder.',
        5: 'Og Israel sagde: Hvi have I gjort ilde mod mig ved at kundgøre Manden, at I havde endnu en Broder?',
        6: 'Og de sagde: Manden spurgte nøje om os og om vor Slægt og sagde: lever eders Fader endnu? have I nogen Broder? da kundgjorde vi ham, eftersom han adspurgte; hvorlunde kunde vi saa lige vide, at han skulde sige: fører eders Broder ned?',
        7: 'Da sagde Juda til Israel, sin Fader: Lad den unge Mand fare med mig, at vi kunne gøre os rede og drage hen og leve og ikke dø, baade vi og du og vore smaa Børn.',
        8: 'Jeg vil være ansvarlig for ham, du maa kræve ham af min Haand; dersom jeg ikke fører ham igen til dig og sætter ham for dit Ansigt, da vil jeg bære Skyld for dig alle Dage.',
        9: 'Thi dersom vi ikke havde tøvet, da havde vi nu to Gange været her igen.',
        10: 'Og Israel, deres Fader, sagde til dem: Om det saa skal være, da gører dette: tager af Landets bedste Frugt i eders Sække og fører ned til Manden som Skænk: lidt Balsam og lidt Honning, Urter og Ladanum, Pistacienødder og Mandler.',
        11: 'Tager og andre Penge med eder; og tager de Penge, som vare komne oven i eders Poser, igen med eder; maaske det er en Vildfarelse;',
        12: 'og tager eders Broder og gører eder rede, farer igen til Manden!',
        13: 'Og den almægtige Gud give eder Barmhjertighed for den Mand, at han lader eders anden Broder og Benjamin følge tilbage med eder; og jeg, skal jeg da være berøvet mine Børn, saa faar jeg være berøvet mine Børn.',
        14: 'Saa toge Mændene denne Skænk og toge dobbelte Penge i deres Haand og Benjamin og gjorde sig rede og droge ned til Ægypten og stode for Josefs Ansigt.',
        15: 'Da saa Josef Benjamin med dem og sagde til den, som forestod hans Hus: Før de Mænd til Huset og slagt Slagtekvæg og lav det til; thi disse Mænd skulle faa Mad med mig til Middag.',
        16: 'Og Manden gjorde, som Josef sagde; og Manden førte Mændene i Josefs Hus.',
        17: 'Men Mændene frygtede, fordi de bleve førte i Josefs Hus, og sagde: Vi føres her ind for de Penges Skyld, som forrige Gang vare komne tilbage i vore Poser, for at han kan vælte sig ind paa os og overfalde os og tage os til Trælle med vore Asener.',
        18: 'Derfor gik de til Manden, som forestod Josefs Hus, og talede med ham ved Husets Dør.',
        19: 'Og de sagde: Hør mig, min Herre! vi vare jo tilforn dragne ned for at købe Spise.',
        20: 'Og det skete, der vi kom i Herberget og oplode vore Poser, se, da havde hver sine Penge oven i sin Pose, vore Penge efter deres Vægt, derfor have vi ført dem med os igen.',
        21: 'Og vi have taget andre Penge ned med os til at købe Spise for; vi vide ikke, hvo der lagde vore Penge i vore Poser.',
        22: 'Og han sagde: Fred være med eder, frygter ikke! eders Gud og eders Faders Gud har givet eder en Skat i eders Poser, eders Penge kom til mig; og han lod Simeon ud til dem.',
        23: 'Og Manden førte Mændene i Josefs Hus og gav dem Vand, og de toede deres Fødder; og han gav deres Asener Foder.',
        24: 'Men de gjorde Gaven rede, indtil Josef kom om Middagen; thi de havde hørt, at de skulde faa Mad der.',
        25: 'Og Josef kom ind i Huset, og de bare ham den Skænk, som de havde i deres Haand, ind i Huset, og de faldt ned for ham paa Jorden.',
        26: 'Men han hilsede dem og sagde: Gaar det eders Fader, den gamle, vel, som I talede om? lever han endnu?',
        27: 'De sagde: Det gaar din Tjener, vor Fader, vel, han lever endnu; og de bøjede sig og faldt ned for ham.',
        28: 'Da opløftede han sine Øjne og saa Benjamin sin Broder, sin Moders Søn, og sagde: Er denne eders yngste Broder, som I talte til mig om? og han sagde: Gud være dig naadig, min Søn!',
        29: 'Og Josef skyndte sig; thi hans Hjerte brændte imod hans Broder, og han søgte et Sted, hvor han kunde græde, og han gik ind i Kammeret og græd der.',
        30: 'Og der han havde toet sit Ansigt, da gik han ud, og han holdt sig og sagde: Sætter Maden frem!',
        31: 'Saa satte de for ham særskilt og for dem særskilt og for Ægypterne, som aade med ham, særskilt, fordi Ægypterne ikke kunde æde Brød med Hebræerne; thi det er Ægypterne en Vederstyggelighed.',
        32: 'Og de sade lige for ham, den førstefødte efter sin Førstefødsel og den yngste efter sin Ungdom; og Mændene forundrede sig imellem sig indbyrdes.',
        33: 'Og han lod bære Retter af det, som var for ham, til dem, og lod Benjamins Ret være mere end alle de andres Retter, fem Gange; og de drak og bleve drukne med ham.',
    },
    44: {
        1: 'Og han befalede den, som forestod hans Hus, og sagde: Fyld Mændenes Poser med Spise, efter som de kunne føre, og læg hvers Penge øverst i hans Pose!',
        2: 'Og min Skaal, den Sølvskaal, skal du lægge øverst i den yngstes Pose og Pengene for hans Korn; og han gjorde efter Josefs Ord, som han havde sagt.',
        3: 'Om Morgenen, der det blev lyst, bleve Mændene sendte bort, de og deres Asener.',
        4: 'Der de vare dragne ud af Staden og ikke vare komne langt, sagde Josef til den, som forestod hans Hus: Staa op, forfølg Mændene, og naar du naar dem, da skal du sige til dem: hvorfor have I betalt ondt for godt?',
        5: 'Er det ikke den, som min Herre drikker af? og hvorved han spaar? I have gjort ilde i, hvad I have gjort.',
        6: 'Og han naaede dem og talede disse Ord til dem.',
        7: 'Og de sagde til ham: Hvi taler min Herre saadanne Ord? det være langt fra dine Tjenere at gøre saadan Gerning.',
        8: 'Se, de Penge, som vi fandt oven i vore Poser, have vi bragt til dig igen fra Kanaans Land; hvorledes skulde vi da stjæle af din Herres Hus Sølv eller Guld?',
        9: 'Hos hvem af dine Tjenere den findes, han skal dø; dertil ville vi ogsaa være min Herres Trælle.',
        10: 'Og han sagde: Ja nu, det skal saa være efter eders Ord: hos hvem den findes, han skal være min Træl, og I skulle være frie.',
        11: 'Saa hastede de, og hver lagde sin Pose ned paa Jorden, og hver oplod sin Pose.',
        12: 'Og han ransagede; han begyndte med den ældste og endte med den yngste, og Skaalen fandtes udi Benjamins Pose.',
        13: 'Da sønderreve de deres Klæder, og hver lagde paa sit Asen, og de fore til Staden igen.',
        14: 'Og Juda og hans Brødre kom til Josefs Hus, og han selv var endnu der, og de faldt til Jorden for hans Ansigt.',
        15: 'Da sagde Josef til dem: Hvad er dette for en Gerning, som I have gjort? vide I ikke, at en Mand, som jeg er, kunde spaa det?',
        16: 'Og Juda sagde: Hvad skulle vi sige til min Herre? hvad skulle vi tale, og hvormed ville vi retfærdiggøre os? Gud har fundet dine Tjeneres Misgerning; se, vi ere min Herres Trælle, baade vi, saa og den, i som Skaalen er funden hos.',
        17: 'Og han sagde: Det være langt fra mig at gøre dette; den Mand, som Skaalen er funden hos, skal være min Træl; men drager I op med Fred til eders Fader!',
        18: 'Da gik Juda frem til ham og sagde: Hør mig, min Herre! kære, lad din Tjener tale et Ord for min Herres Øren, og lad din Vrede ikke forhaste sig paa din I Tjener; thi du er ligesom Farao.',
        19: 'Min Herre spurgte sine Tjenere ad og sagde: Have I Fader eller Broder?',
        20: 'Da sagde vi til min Herre: Vi have en gammel Fader, og han har en ung Søn, han avlede i sin Alderdom; og hans Broder er død, og han er alene bleven igen efter sin Moder, og hans Fader har ham kær.',
        21: 'Da sagde du til dine Tjenere: Fører ham ned til mig, at jeg kan se ham.',
        22: 'Da sagde vi til min Herre: Den unge Mand kan ikke forlade sin Fader, dersom han forlader sin Fader, da dør denne.',
        23: 'Da sagde du til dine Tjenere: Dersom ikke eders yngste Broder kommer ned med eder, skulle I ikke se mit Ansigt mere.',
        24: 'Og det skete, at vi i fore op til din Tjener, min Fader, i og vi gave ham min Herres Tale i til Kende.',
        25: 'Da sagde vor Fader: Drager hen igen, køber os lidt Spise!',
        26: 'Da sagde vi: Vi kunne ikke I fare ned; dersom vor yngste Broder er med os, da ville vi rejse ned; thi vi kunne ikke se den Mands Ansigt, dersom vor yngste Broder ikke er med os.',
        27: 'Da sagde din Tjener, min Fader, til os: I vide, at min Hustru har født mig to.',
        28: 'Og den ene gik bort fra mig, og jeg sagde: Han er vist reven ihjel, og jeg har ikke set ham hidindtil.',
        29: 'Dersom I toge ogsaa denne fra mit Ansigt, og han kom til Ulykke, da førte I mine graa Haar med Kummer ned i Graven.',
        30: 'Og nu, dersom jeg kommer til din Tjener, min Fader, og den unge Mand ikke er med os, efterdi hans Sjæl er bunden til den unge Mands Sjæl,',
        31: 'da sker det, naar han ser, at den unge Mand ikke er der, at han dør, og dine Tjenere ville bringe din Tjeners, vor Faders, graa Haar med Sorg til Graven.',
        32: 'Thi din Tjener blev ansvarlig for den unge Mand hos min Fader og sagde: Dersom jeg ikke bringer dig ham igen, da vil jeg bære Skyld for min Fader alle Dage.',
        33: 'Og nu, kære, lad din Tjener blive min Herres Træl i Stedet for den unge Mand, men den unge Mand drage op med sine Brødre.',
        34: 'Thi hvorledes skulde jeg fare op til min Fader, uden at den unge Mand er med mig? jeg maatte da se paa det onde, som skulde ramme min Fader.',
    },
    45: {
        1: 'Og Josef kunde ikke holde sig for alle dem, som stode hos ham, og han raabte: Lader hver Mand gaa ud fra mig; og ikke een Mand stod hos ham, der Josef lod sig kende for sine Brødre.',
        2: 'Og han opløftede sin Røst med Graad, og Ægypterne hørte det, og Faraos Hus hørte det.',
        3: 'Og Josef sagde til sine Brødre: Jeg er Josef; lever min Fader endnu? og hans Brødre kunde ikke svare ham; thi de forfærdedes for hans Ansigt.',
        4: 'Da sagde Josef til sine Brødre: Kommer dog hid til mig; og de gik frem; og han sagde: Jeg er Josef, eders Broder, som I solgte til Ægypten.',
        5: 'Men værer nu ikke bekymrede, og lader det ikke være mishageligt for eders Øjne, at I solgte mig hid; thi for at I skulde blive holdte ved Live, har Gud sendt mig hid foran eder.',
        6: 'Thi nu har der været to Aar Hunger i Landet, og endnu er der fem Aar, i hvilke der ikke skal være Pløjning eller Høst.',
        7: 'Men Gud har sendt mig foran eder, at lade eder blive tilovers i Landet og at lade eder leve, til en stor Befrielse.',
        8: 'Og nu, ikke I have sendt mig hid, men Gud; og han har sat mig til en Fader for Farao og til en Herre over alt hans Hus og til en Hersker i alt Ægyptens Land.',
        9: 'Skynder eder og drager op til min Fader, og I skulle sige til ham: Saa siger din Søn Josef: Gud har sat mig til en Herre over al Ægypten; kom ned til mig, tøv ikke!',
        10: 'Og du skal bo i Gosen Land og være nær hos mig, du og dine Børn og dine Børnebørn og dit Kvæg og dine Øksen og alt det, du har.',
        11: 'Og jeg vil opholde dig der; thi endnu er der fem Aar Hunger; paa det du ikke skal forarmes, du og dit Hus og alt det, som tilhører dig.',
        12: 'Og se, eders Øjne og min Broder Benjamins Øjne se, at jeg taler mundtligen til eder.',
        13: 'Og I skulle forkynde min Fader al min Herlighed i Ægypten, og alt det, som I have set; og skynder eder og lader min Fader komme hid ned.',
        14: 'Saa faldt han om Benjamins, sin Broders, Hals og græd, og Benjamin græd om hans Hals.',
        15: 'Og han kyssede alle sine Brødre og græd over dem, og derefter talede hans Brødre med ham.',
        16: 'Og det rygtedes i Faraos Hus, og der sagdes: Josefs Brødre ere komne; det var godt baade i Faraos Øjne og i hans Tjeneres Øjne.',
        17: 'Og Farao sagde til Josef: Sig til dine Brødre: gører dette, belæsser eders Dyr og gaar, at I maa komme til Kanaans Land.',
        18: 'Og tager eders Fader og eders Husfolk og kommer til mig, og jeg vil give eder det bedste i Ægyptens Land, at I skulle æde af Landets Fedme.',
        19: 'Og det er dig befalet: gører dette; tager eder Vogne af Ægyptens Land til eders Børn og til eders Hustruer, og fører eders Fader der paa og kommer.',
        20: 'Og lader eders Øjne ikke se hen til eders Boskab; thi det bedste, som er i alt Ægyptens Land, er eders.',
        21: 'Og Israels Sønner gjorde saa, og Josef gav dem Vogne efter Faraos Ord og gav dem Tæring paa Vejen.',
        22: 'Han gav alle, hver især, Klædninger til at skifte med; men Benjamin gav han tre Hundrede Sekel Sølv og fem Klædninger til at skifte med.',
        23: 'Og han sendte sin Fader ligervis ti Asener, som bare af Ægyptens bedste Gods, og ti Aseninder, som bare Korn og Brød og Føde, til hans Fader paa Vejen.',
        24: 'Og han lod sine Brødre fare, og de gik; og han sagde til dem: Kives ikke paa Vejen!',
        25: 'Saa droge de op af Ægypten, og de kom til det Land Kanaan, til Jakob, deres Fader.',
        26: 'Og de forkyndte ham, sigende: Josef lever endnu, og han er en Hersker over alt Ægyptens Land; men hans Hjerte blev koldt, thi han troede dem ikke.',
        27: 'Da sagde de ham alle Josefs Ord, som han havde sagt til dem, og han saa Vognene, som Josef havde sendt til at føre ham paa; og Jakobs, deres Faders, Aand blev levende.',
        28: 'Og Israel sagde: Det er meget, Josef min Søn lever endnu; jeg vil fare hen og se ham, før jeg dør.',
    },
    46: {
        1: 'Og Israel rejste med alt det, han havde, og kom til Beersaba og ofrede sin Fader Isaks Gud Slagtoffer.',
        2: 'Og Gud talede til Israel i Syner om Natten og sagde: Jakob! Jakob! og han sagde: Se, her er jeg.',
        3: 'Og han sagde: Jeg er Gud, din Faders Gud, frygt ikke for at drage ned til Ægypten, thi der vil jeg gøre dig til et stort Folk.',
        4: 'Jeg vil fare ned med dig til Ægypten, og jeg vil ogsaa visselig føre dig op igen; og Josef skal lægge sin Haand paa dine Øjne.',
        5: 'Saa brød Jakob op fra Beersaba; og Israels Sønner førte Jakob, deres Fader, og deres smaa Børn og deres Hustruer paa Vognene, som Farao havde sendt til at føre ham paa.',
        6: 'Og de toge deres Kvæg og deres Gods, som de havde forhvervet i Kanaans Land, og kom til Ægypten, Jakob og al hans Sæd med ham;',
        7: 'hans Sønner og hans Sønners Sønner med ham, hans Døtre og hans Sønners Døtre og al hans Sæd; han førte dem med sig til Ægypten.',
        8: 'Og disse ere Israels Børns Navne, som kom til Ægypten, Jakob og hans Sønner: Ruben, Jakobs førstefødte;',
        9: 'og Rubens Sønner: Hanok og Pallu og Hezron og Karmi;',
        10: 'og Simeons Sønner: Jemuel og Jamin og Ohad og Jakin og Zohar og Saul, den kananæiskes Søn;',
        11: 'og Levi Sønner: Gerson, Kahath og Merari;',
        12: "og Judas Sønner: Er og Onan og Sela og Perez og Sera; men Er og Onan vare døde i Kanaans Land; og Perez' Sønner vare Hezron og Hamul;",
        13: 'og Isaskars Sønner: Thola og Pua og Job og Simron;',
        14: 'og Sebulons. Sønner: Sered og Elon og Jahleel.',
        15: 'Disse ere Leas Børn, som hun fødte Jakob i Paddan-Aram, og hans Datter var Dina; alle hans Sønner og hans Døtre vare tre og tredive Sjæle.',
        16: 'Og Gads Sønner: Zifjon og Haggi, Sini og Ezbon, Eri og Arodi og Areli;',
        17: 'og Asers Sønner: Jimna og Jisva og Jisui og Bria, og Sera, deres Søster; og Brias Sønner: Heber og Malkiel.',
        18: 'Disse ere Silpas Børn, hvilken Laban gav Lea sin Datter; og hun fødte Jakob disse, seksten Sjæle.',
        19: 'Rakels, Jakobs Hustrus, Sønner: Josef og Benjamin.',
        20: 'Og der blev født Josef Sønner i Ægyptens Land, hvilke Asnath, en Datter af Potifera, Præsten i On, fødte ham: Manasse og Efraim.',
        21: 'Og Benjamins Sønner: Bela og Beker og Asbel, Gera og Naaman, Ehi og Ros, Muppim og Huppim og Ard.',
        22: 'Disse ere Rakels Børn, som fødtes Jakob, ialt fjorten Sjæle.',
        23: 'Og Dans Sønner: Husim;',
        24: "og Nafthali' Sønner: Jahzeel og Guni og Jezer og Sillem.",
        25: 'Disse ere Bilhas Sønner, hvilken Laban gav Rakel sin Datter, og hun fødte Jakob disse, ialt syv Sjæle.',
        26: 'Alle, de Sjæle, som kom med Jakob til Ægypten, som vare udkomne af hans Lænd, foruden Jakobs Sønners Hustruer, ere i alt seks og tresindstyve Sjæle.',
        27: 'Og Josefs Sønner, som fødtes ham i Ægypten, vare to Sjæle; alle Sjæle af Jakobs Hus, som kom til Ægypten, vare halvfjerdsindstyve.',
        28: 'Og han sendte Juda foran sig til Josef, for at denne skulde vise ham til Gosen, og de kom til Gosen Land.',
        29: 'Da lod Josef spænde for sin Vogn og drog op til Gosen at møde Israel sin Fader, og han saas af ham og faldt om hans Hals og græd længe om hans Hals,',
        30: 'Da sagde Israel til Josef: Jeg vil nu gerne dø, efter at jeg har set dit Ansigt, at du endnu er levende.',
        31: 'Og Josef sagde til sine Brødre og til sin Faders Hus: Jeg vil drage op og give Farao til Kende og sige til ham: Mine Brødre og min Faders Hus, som var i Kanaans Land, ere komne til mig.',
        32: 'Og Mændene ere Faarehyrder; thi de ere Mænd, som drive Kvægavl, og deres Faar og deres Øksne og alt det, de eje, have de ført hid.',
        33: 'Og det skal ske, naar Farao kalder ad eder, og han siger: Hvad er eders Haandtering?',
        34: 'da skulle I sige: Dine Tjenere ere Mænd, som drive Kvægavl fra vor Ungdom og indtil nu, baade vi og vore Fædre, paa det I maa bo i det Land Gosen; thi alle Faarehyrder ere Ægypterne en Vederstyggelighed.',
    },
    47: {
        1: 'Og Josef kom og forkyndte Farao det og sagde: Min Fader og mine Brødre og deres Faar og deres Øksne og alt det, de have, ere komne fra Kanaans Land; og se, de ere i Gosen Land.',
        2: 'Og af samtlige sine Brødre tog han fem Mænd og stillede dem for Farao.',
        3: 'Da sagde Farao til hans Brødre: Hvad er eders Haandtering? og de sagde til Farao: Dine Tjenere ere Faarehyrder, baade vi og vore Fædre.',
        4: 'Og de sagde til Farao: Vi ere komne at være fremmede i Landet; thi der er ingen Føde til det Kvæg, som dine Tjenere have; thi Hungeren er svar i Kanaans Land; og nu, kære, lad dine Tjenere bo i Gosen Land.',
        5: 'Og Farao talede til Josef og sagde: Din Fader og dine Brødre ere komne til dig.',
        6: 'Ægyptens Land ligger for dig, lad din Fader og dine Brødre bo paa det bedste Sted i Landet, lad dem bo i Gosen Land, og dersom du ved, at der er duelige Mænd iblandt dem, da sæt dem til Opsynsmænd over Kvæget, over det, som jeg har.',
        7: 'Og Josef førte Jakob sin Fader ind og stillede ham for Faraos Ansigt, og Jakob velsignede Farao.',
        8: 'Og Farao sagde til Jakob: Hvor gammel er du?',
        9: 'Og Jakob sagde til Farao: Min Udlændigheds Aars Dage ere hundrede og tredive Aar; faa og onde have mit Livs Aars Dage været og have ikke naaet til mine Fædres Livs Aars Dage i deres Udlændigheds Dage.',
        10: 'Og Jakob velsignede Farao og gik ud fra Farao.',
        11: 'Men Josef lod sin Fader og sine Brødre bo og gav dem Ejendom i Ægyptens Land, paa det bedste Sted i Landet, i det Land Raamses, som Farao havde befalet.',
        12: 'Og Josef underholdt sin Fader og sine Brødre og alt sin Faders Hus med Brød til de smaa Børns Mund.',
        13: 'Og der var ikke Brød i alt Landet; thi Hungeren var saare svar, saa at Ægyptens Land og Kanaans Land forsmægtede for Hungerens Skyld.',
        14: 'Og Josef samlede alle Pengene, som fandtes i Ægyptens Land og i Kanaans Land, for det Korn, som de købte, og Josef lod Pengene komme i Faraos Hus.',
        15: 'Og da det var forbi med Pengene i Ægyptens Land og i Kanaans Land, da kom alle Ægypterne til Josef og sagde: Fly os Brød, og hvi skulle vi dø for dig? thi Pengene ere borte.',
        16: 'Og Josef sagde: Flyr hid eders Kvæg, saa vil jeg give eder Brød for eders Kvæg, dersom Pengene ere borte.',
        17: 'Saa førte de deres Kvæg til Josef, og Josef gav dem Brød for Hestene og for Kvæget, som de ejede, og for Øksnene, som de ejede, og for Asenerne; saa hjalp han dem med Brød for alt deres Kvæg i det samme Aar.',
        18: 'Der det samme Aar havde Ende, da kom de i det andet Aar til ham og sagde til ham: Vi ville ikke dølge for min Herre, at ikke alene Pengene ere borte, men og Kvæget, som vi ejede, er kommet til min Herre; vi have intet tilbage til min Herre, uden vore Legemer og vor Jord.',
        19: 'Hvi skulle vi dø for dine Øjne, baade vi og tilmed vor Jord blive øde? køb os og vor Jord for Brød; og vi med vor Jord ville være Faraos Tjenere, og giv os Sæd, at vi maa leve og ikke dø, og Jorden ikke blive øde.',
        20: 'Og Josef købte af Ægyptens Jord til Farao; thi Ægypterne solgte hver sin Ager, fordi Hungeren var svar over dem; og Landet blev Faraos.',
        21: 'Og han lod Folket flytte om i Stæderne, fra den ene Ende af Ægyptens Land til den anden.',
        22: 'Alene Præsternes Jord købte han ikke; thi Præsterne havde deres beskikkede Del af Farao; og de aade deres beskikkede Del, som Farao havde givet dem, derfor solgte de ikke deres Jord.',
        23: 'Da sagde Josef til Folket: Se, jeg har i Dag købt eder og eders Jord til Farao, se, der have I Sæd, og I skulle besaa Jorden.',
        24: 'Og med Afgrøden skal det være saaledes, at I skulle give Farao den femte Part, og de fire Parter skulle I beholde til Sæd til Ageren og til Spise for eder og for dem, som ere i eders Huse, og til eders smaa Børn at æde.',
        25: 'Og de sagde: Du har holdt os ved Live, lad os finde Naade for min Herres Øjne, og vi ville være Faraos Trælle.',
        26: 'Saa gjorde Josef det til en Skik indtil denne Dag over Ægyptens Jord, at Farao skal have den femte Part; ikkun Præsternes Jord, den alene, blev ikke Faraos.',
        27: 'Og Israel boede i Ægyptens Land, i Gosen Land; og de fik Ejendom der og vare frugtbare og bleve saare mangfoldige.',
        28: 'Og Jakob levede i Ægyptens Land sytten Aar; og Jakobs Dage, hans Livs Aar, vare hundrede og syv og fyrretyve Aar.',
        29: 'Og Israels Dage kom nær, at han skulde dø, og han kaldte ad sin Søn Josef og sagde til ham: Kære, dersom jeg har fundet Naade for dig, da læg, kære, din Haand under min Lænd, og bevis den Miskundhed og Troskab mod mig, at du, kære, ikke begraver mig i Ægypten.',
        30: 'Og jeg vil ligge hos mine Fædre, og du skal føre mig af Ægypten og begrave mig i deres Grav; og han sagde: Jeg vil gøre, som du har sagt.',
        31: 'Men han sagde: Sværg mig; og han svor ham; og Israel bøjede sig over Hovedgærdet i Sengen.',
    },
    48: {
        1: 'Og det skete derefter, at der sagdes til Josef: Se, din Fader er syg; og han tog begge sine Sønner med sig, Manasse og Efraim.',
        2: 'Og det gaves Jakob til Kende, og der sagdes: Se, din Søn Josef kommer til dig; saa gjorde Israel sig stærk og sad paa Sengen.',
        3: 'Og Jakob sagde til Josef: Den almægtige Gud aabenbaredes for mig i Lus, udi Kanaans Land, og velsignede mig,',
        4: 'og han sagde til mig: Se, jeg vil gøre dig frugtbar og formere dig og gøre dig til en Hob Folk og give din Sæd efter dig dette Land til Ejendom evindelig.',
        5: 'Og nu, dine to Sønner, som ere fødte dig i Ægyptens Land, før jeg kom til dig i Ægypten, de skulle høre mig til; Efraim og Manasse skulle høre mig til, som Ruben og Simeon.',
        6: 'Men dit Afkom, som du avler efter dem, skal høre dig til; de skulle kaldes efter deres Brødres Navn i deres Arv.',
        7: 'Og der jeg kom fra Paddan, døde Rakel for mig i Kanaans Land paa Vejen, der jeg havde endnu et Stykke Vej for at komme til Efrath, og jeg begrov hende der paa Vejen til Efrath, det er Bethlehem.',
        8: 'Og Israel saa Josefs Sønner og sagde: Hvo ere disse?',
        9: 'Og Josef sagde til sin Fader: Det er mine Sønner, som Gad har givet mig her, og han sagde: Kære, led dem til mig, og jeg vil velsigne dem.',
        10: 'Og Israels Øjne vare matte af Alder, han kunde ikke se; og han lod dem komme til ham, og han kyssede dem og tog dem i Favn.',
        11: 'Og Israel sagde til Josef: Jeg havde ikke tænkt at se dit Ansigt, og se, Gud har endog ladet mig se din Sæd.',
        12: 'Og Josef førte dem ud fra hans Knæ og bøjede sig med sit Ansigt til Jorden.',
        13: 'Og Josef tog dem begge, Efraim i sin højre Haand, for Israels venstre Haand, og Manasse i sin venstre Haand, for Israels højre Haand, og lod dem komme nær til ham.',
        14: 'Og Israel rakte sin højre Haand ud og lagde den paa Efraims Hoved, enddog han var den yngste, og sin venstre Haand paa Manasses Hoved; vidende gjorde han saaledes med sine Hænder, thi Manasse var den førstefødte.',
        15: 'Og han velsignede Josef og sagde: Den Gud, for hvis Ansigt mine Fædre, Abraham og Isak, vandrede, den Gud, som vogtede mig, fra jeg blev til, indtil denne Dag,',
        16: 'den Engel, som udløste mig fra alt ondt, velsigne Drengene, at de maa kaldes efter mit Navn og efter mine Fædres, Abrahams og Isaks, Navn, og at de maa blive saare mange midt i Landet.',
        17: 'Der Josef saa, at hans Fader lagde sin højre Haand paa Efraims Hoved, da mishagede det ham; og han tog fat paa sin Faders Haand for at føre den fra Efraims Hoved paa Manasses Hoved.',
        18: 'Og Josef sagde til sin Fader: Ikke saa, min Fader! thi denne er den førstefødte, læg din højre Haand paa hans Hoved.',
        19: 'Men hans Fader vægrede sig og sagde: Jeg ved det, min Søn, jeg ved det; han skal ogsaa blive til Folk, og han skal ogsaa blive stor; men hans yngste Broder skal blive større end han, og hans Sæd skal være en stor Hob Folk.',
        20: 'Saa velsignede han dem paa den samme Dag og sagde: Ved dig skal Israel velsigne og sige: Gud sætte dig som Efraim og som Manasse! og han satte Efraim foran Manasse.',
        21: 'Og Israel sagde til Josef: Se, jeg dør, og Gud skal være med eder og føre eder til eders Fædres Land igen.',
        22: 'Og jeg har givet dig fremfor dine Brødre et Stykke Land, som jeg har taget af Amoriternes Haand med mit Sværd og med min Bue.',
    },
    49: {
        1: 'Og Jakob kaldte ad sine Sønner og sagde: Samler eder, og jeg vil forkynde eder, hvad eder skal vederfares i de sidste Dage.',
        2: 'Kommer til Hobe og hører, Jakobs Sønner! og hører paa Israel, eders Fader.',
        3: 'Ruben, du er min førstefødte, min Magt og min første Kraft, ypperlig i Værdighed og ypperlig i Styrke!',
        4: 'Du bruser op som Vandet; du skal ikke være ypperlig; thi du besteg din Faders Leje, da besmittede du det; han har besteget min Seng.',
        5: 'Simeon og Levi ere Brødre; Volds Vaaben ere deres Sværd.',
        6: 'Min Sjæl skal ikke komme i deres hemmelige Raad, min Ære skal ikke forenes med deres Forsamling; thi i deres Vrede have de slaget Mænd ihjel, og i deres Egenraadighed have de lemlæstet Oksen.',
        7: 'Forbandet være deres Vrede, thi den var streng, og deres Hastighed, thi den var haard; jeg vil fordele dem i Jakob og adsprede dem i Israel.',
        8: 'Juda, dig skulle dine Brødre love, din Haand skal være paa dine Fjenders Nakke; for dig skulle din Faders Sønner bøje sig.',
        9: 'Juda er en ung Løve; du opsteg fra Rov, min Søn! han har bøjet sig, han laa som en Løve og som en Løvinde; hvem tør jage ham op?',
        10: 'Der skal ikke vige Kongespir fra Juda og ikke Herskerstav fra hans Fødder, førend Silo skal komme, og Folkene skulle hænge ved ham.',
        11: 'Han binder sit unge Asen til Vintræet og sin Asenindes Føl til Vinranken; han tor sit Klædebon i Vin, og sin Kjortel i Vindrueblod.',
        12: 'Han er rødere i Øjnene end Vin, og hvidere paa Tænderne end Mælk.',
        13: 'Sebulon skal bo ved Havets Strand, og han skal være ved Skibenes Strand, og hans Side ligger op til Sidon.',
        14: 'Isaskar skal være et knokkelstærkt Asen, som ligger imellem Kvægfoldene.',
        15: 'Thi han saa, at Hvilen var god, og at Landet var dejligt, og han har bøjet sine Skuldre til at bære og er bleven en skatskyldig Tjener.',
        16: 'Dan skal dømme sit Folk, som en af Israels Stammer.',
        17: 'Dan skal være en Slange paa Vejen, en Hornslange paa Stien, som bider Hestens Hov, saa dens Rytter falder bag af.',
        18: 'Herre, jeg bier efter din Frelse!',
        19: 'Gad — en Skare skal trænge ind paa ham, men han skal trænge den tilbage.',
        20: 'Fra Aser kommer det fede, som er hans Brød; og han skal give kongelige Lækkerheder.',
        21: 'Nafthali er en frit løbende Hind, han, som giver dejlig Tale.',
        22: 'Josef er en Kvist paa det frugtbare Træ, en Kvist paa det frugtbare Træ ved Kilden; Grenene gaa op over Muren.',
        23: 'Og Bueskytterne forbitrede ham og skøde og hadede ham.',
        24: 'Og hans Bue blev dog stærk, og hans Hænders Arme smidige; det kom fra Jakobs mægtiges Hænder, hist fra, fra Hyrden, fra Israels Klippe.',
        25: 'Fra din Faders Gud — og han hjælpe dig! — og fra den Almægtige — og han velsigne dig! — komme Velsignelser fra Himmelen ovenfra og Velsignelser fra Dybet nedenfra, Brysters og Moderlivs Velsignelser.',
        26: 'Din Faders Velsignelser ere mægtigere end mine Forfædres Velsignelser, indtil de evige Højes Grænser; de skulle komme paa Josefs Hoved og paa hans Isse, som er en Fyrste iblandt sine Brødre.',
        27: 'Benjamin skal røve som en Ulv; om Morgenen skal han æde Rov, og om Aftenen skal han uddele Bytte.',
        28: 'Alle disse ere de tolv Israels Stammer; og dette er det, som deres Fader talede til dem, da han velsignede dem, hver efter sin Velsignelse velsignede han dem.',
        29: 'Og han befalede dem og sagde til dem: Naar jeg er samlet til mit Folk, da begraver mig hos mine Fædre i den Hule, som er paa Efron den Hethiters Ager,',
        30: 'i den Hule, som er paa den Ager Makpela, som er tvært over for Mamre i Kanaans Land, hvilken Ager Abraham købte af Efron den Hethiter til Begravelses Ejendom.',
        31: 'Der have de begravet Abraham og Sara, hans Hustru; der have de begravet Isak og Rebekka, hans Hustru; og der har jeg begravet Lea.',
        32: 'Den Agers Ejendom og den Hule, som er derpaa, er købt af Heths Børn.',
        33: 'Der Jakob var kommen til Ende med at byde sine Børn dette, da tog han sine Fødder til sig op paa Sengen og opgav sin Aand og blev samlet til sit Folk.',
    },
    50: {
        1: 'Da faldt Josef over sin Faders Ansigt og græd over ham og kyssede ham.',
        2: 'Og Josef befalede sine Tjenere, Lægerne, at balsamere hans Fader; saa balsamerede Lægerne Israel.',
        3: 'Og fyrretyve Dage medgik hertil; thi saa mange Dage medgaa til Balsameringen; og Ægypterne begræd ham halvfjerdsindstyve Dage.',
        4: 'Og der Grædedagene over ham vare forbi, da talede Josef til Faraos Hus og sagde: Kære, dersom jeg har fundet Naade for eders Øjne, da taler, kære, for Faraos Øren og siger:',
        5: 'Min Fader tog en Ed af mig og sagde: Se, jeg dør; i min Grav, som jeg lod mig grave i Kanaans Land, der skal du begrave mig; og nu, kære, vil jeg drage op og begrave min Fader, og jeg vil komme igen.',
        6: 'Og Farao sagde: Drag op og begrav din Fader, saaledes som han tog Ed af dig.',
        7: 'Og Josef drog op for at begrave sin Fader, og alle Faraos Tjenere fore op med ham, de ældste af hans Hus, og alle de ældste af Ægyptens Land,',
        8: 'og Josefs ganske Hus og hans Brødre og hans Faders Hus, kun deres smaa Børn og deres Faar og deres Øksne lode de blive i Gosen Land.',
        9: 'Og baade Vogne og Ryttere droge op med ham, og det var en meget stor Hær.',
        10: 'Der de kom til den Lade Atad, som ligger paa hin Side Jordan, da holdt de der en stor og saare svar Klage, og han lod holde Sorrig for sin Fader syv Dage.',
        11: 'Og Kananiten, som boede i Landet, saa den Sorrig ved den Lade Atad, og de sagde: Denne er en svar Sorrig for Ægypterne; derfor kaldte man det Steds Navn: Ægypternes Sorrig, som er paa hin Side Jordan.',
        12: 'Og hans Sønner gjorde saaledes med ham, som han havde befalet dem.',
        13: 'Og hans Sønner førte ham til Kanaans Land og begrove ham i Hulen paa den Ager Makpela, den Ager, som Abraham havde købt til Begravelses Ejendom af Efron den Hethiter, tvært over for Mamre.',
        14: 'Og Josef kom igen til Ægypten, han og hans Brødre og alle de, som vare dragne op med ham til at begrave hans Fader, efter at han havde begravet sin Fader.',
        15: 'Der Josefs Brødre saa, at deres Fader var død, da sagde de: Maaske Josef hader os, saa han visselig vil betale os igen alt det onde, som vi have gjort imod ham.',
        16: 'Og de beskikkede nogen at tale til Josef, sigende: Din Fader befalede, før han døde og sagde:',
        17: 'Saa skulle I sige til Josef: Kære, forlad dog dine Brødre deres Overtrædelse og deres Synd, at de gjorde ilde imod dig; kære, saa forlad nu din Faders Guds Tjenere deres Overtrædelse; da græd Josef, der de talede til ham.',
        18: 'Og hans Brødre gik ogsaa selv hen og faldt ned for hans Ansigt og sagde: Se, vi ere dine Tjenere!',
        19: 'Og Josef sagde til dem: Frygter ikke; thi monne jeg være i Guds Sted?',
        20: 'Og I tænkte ondt imod mig; Gud tænkte at vende det til det gode, for at gøre, hvad der sker paa denne Dag, at holde meget Folk ved Live.',
        21: 'Saa frygter nu ikke, jeg vil opholde eder og eders smaa Børn; saa trøstede han dem og talede kærlig med dem.',
        22: 'Saa boede Josef i Ægypten, han og hans Faders Hus, og Josef levede hundrede og ti Aar.',
        23: 'Og Josef saa Efraims Sønner i tredje Led; desligeste Makirs, Manasse Søns, Sønner bleve fødte paa Josefs Knæ.',
        24: 'Og Josef sagde til sine Brødre: Jeg dør, og Gud skal visselig besøge eder og føre eder op af dette Land, til det Land, som han har tilsvoret Abraham, Isak og Jakob.',
        25: 'Og Josef tog en Ed af Israels Børn og sagde: Gud skal visselig besøge eder, og I skulle føre mine Ben op herfra.',
        26: 'Saa døde Josef hundrede og ti Aar gammel; og de balsamerede ham, og man lagde ham i Kiste i Ægypten.',
    },
}
